window.kbParts["paper-519fed2577e0f3e3"] = {"qs":{"国考 2025 地市级 行测#1":{"stem":"习近平总书记指出，马克思主义是为人民立言、为人民代言的理论，是为改变人民命运而创立、在人民求解放的\n实践中丰富和发展的，人民的创造性实践是马克思主义理论创新的不竭源泉。下列说法与这一论述相符的是：\n①人民不仅是物质财富的创造者，也是精神财富的创造者\n②要坚持以理论工作者的首创精神为引领，注重从理论创新中总结实践经验\n③无论是毛泽东思想、中国特色社会主义理论体系，还是习近平新时代中国特色社会主义思想，无不源自于人民的\n智慧、人民的探索、人民的创造\n④各级领导干部身处实践最前沿，对实践变化感知最敏感、感受最深切，也最聪慧","options":["①②","①③","②④","③④"],"answer":"B","analysis":"1. 正确答案：B\n解析：\n本题考查理论与政策。\n①正确，2023年6月30日，习近平总书记在二十届中共中央政治局第六次集体学习时强调，“马克思主义是为人民立\n言、为人民代言的理论，是为改变人民命运而创立、在人民求解放的实践中丰富和发展的，人民的创造性实践是马\n克思主义理论创新的不竭源泉。人民作为历史的创造者，不仅是物质财富的创造者，也是精神财富的创造者。”\n②错误，2023年6月30日，习近平总书记在二十届中共中央政治局第六次集体学习时强调，“要尊重人民首创精神，\n注重从人民的创造性实践中总结新鲜经验，上升为理性认识，提炼出新的理论成果，着力让党的创新理论深入亿万\n人民心中，成为接地气、聚民智、顺民意、得民心的理论。”\n③正确，2023年6月30日，习近平总书记在二十届中共中央政治局第六次集体学习时强调，“无论是毛泽东思想、中\n国特色社会主义理论体系，还是新时代中国特色社会主义思想，无不源自于人民的智慧、人民的探索、人民的创\n造。”\n④错误，《求是》杂志发表习近平总书记重要文章《必须坚持人民至上》中指出：“人民群众身处实践最前沿，对实\n践变化感知最敏感、感受最深切，也最聪慧，只要走到人民群众中去，很多百思不得其解的问题就能豁然开朗、找\n到答案。”\n故①③表述正确。\n故正确答案为B。\n【考点】\n政治建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论","哲学"],"nature":"知识题","current":false,"links":[{"id":"k-1147d5c7af105768","label":"人民群众是物质财富和精神财富的创造者","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"人民作为历史的创造者，不仅是物质财富的创造者，也是精神财富的创造者。","why":"这条历史唯物主义原理说明人民群众在两类社会财富创造中的作用。","origin":"逐题标记"},{"id":"k-e5c94d5d20f83e29","label":"人民的创造性实践是马克思主义理论创新的源泉","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"人民的创造性实践是马克思主义理论创新的不竭源泉。","why":"这一原理说明党的创新理论源于人民的智慧、探索和创造。","origin":"逐题标记"}]},"国考 2025 地市级 行测#2":{"stem":"习近平总书记指出，问题是事物矛盾的表现形式，我们强调增强问题意识、坚持问题导向，就是承认矛盾的普遍\n性、客观性，就是要善于把认识和化解矛盾作为打开工作局面的突破口。关于矛盾的普遍性、客观性，下列说法正\n确的是：","options":["矛盾的普遍性是有条件的，并根据条件的变化而变化","矛盾的客观性从属于主观性，不能脱离人的认知、情感、意志而存在","矛盾的普遍性是矛盾的共性，矛盾的特殊性是矛盾的个性","矛盾的普遍性、客观性决定了事物的不同性质，是认清事物本质和发展规律的基础"],"answer":"C","analysis":"2. 正确答案：C\n解析：\n本题考查马克思主义。\nA项错误，矛盾的普遍性是指矛盾存在于一切事物中，存在于一切事物发展过程的始终，旧的矛盾解决了，新的矛盾\n又产生，事物始终在矛盾中运动。矛盾的普遍性即矛盾的共性，矛盾的共性是无条件的、绝对的。故“矛盾的普遍性\n是有条件的”说法错误。\nB项错误，矛盾规律具有普遍性和客观性，是不以人的意志为转移的。“矛盾的客观性从属于主观性，不能脱离人的\n认知、情感、意志而存在”的观点认为主观决定客观，属于唯心主义的范畴，故说法错误。\nC项正确，矛盾的普遍性和特殊性是辩证统一的关系。矛盾的普遍性即矛盾的共性，矛盾的特殊性即矛盾的个性。矛\n盾的共性是无条件的、绝对的，矛盾的个性是有条件的、相对的。\nD项错误，矛盾的特殊性是指各个具体事物的矛盾、同一事物的矛盾在不同发展过程和发展阶段、每一个矛盾的各个\n方面各有其特点。矛盾的特殊性决定了事物的不同性质，如实地分析矛盾的特殊性是认清事物本质和发展规律的基\n础，故说法错误。\n故正确答案为C。\n【考点】\n辩证法","figs":[],"state":"已标记","notes":[],"domains":["哲学"],"nature":"知识题","current":false,"links":[{"id":"k-bbfcc1599e79a235","label":"辩证法 · 三大规律","catalog_id":"c394cdef1420fc60","type":"原理与机制","role":"直接考查","field":"answer","quote":"矛盾的普遍性即矛盾的共性，矛盾的特殊性即矛盾的个性。","why":"题目考查对立统一规律中矛盾的共性和个性，并要求区分矛盾的客观性与特殊性的作用。","origin":"逐题标记"}]},"国考 2025 地市级 行测#3":{"stem":"关于马克思主义政治经济学，下列说法正确的是：","options":["商品的价值量是由生产该商品所需的个别劳动时间决定的","货币的价值尺度职能是通过实际的物质交换来实现的","具体劳动和抽象劳动是不同商品生产过程中的不同劳动","具体劳动创造商品的使用价值，抽象劳动形成商品的价值"],"answer":"D","analysis":"3. 正确答案：D\n解析：\n本题考查马克思主义。\nA项错误，商品的价值量是指商品价值的大小，是由生产商品的社会必要劳动时间决定的。社会必要劳动时间即在现\n有的社会正常的生产条件下，在社会平均的劳动熟练程度和劳动强度下制造某种使用价值所需要的劳动时间。\nB项错误，货币的价值尺度职能，是指以自身价值作为尺度来衡量其他商品的价值。货币执行价值尺度职能，不需要\n现实的货币，只需要观念上的货币，不需要通过实际的物质交换来实现。\n\nC项错误，具体劳动和抽象劳动，是生产商品的同一劳动过程的两个方面，而不是两种劳动或两次劳动。具体劳动说\n明的是劳动是什么样的，是怎样进行的；抽象劳动说明的是劳动的量的多少，劳动时间的长短。\nD项正确，具体劳动是指人们在一定的具体形式下进行的劳动，体现着人和自然的关系，生产出各种各样的使用价\n值。抽象劳动是指撇开一切具体形式的无差别的一般人类劳动，即人的体力和脑力的消耗。抽象劳动形成商品的价\n值。\n故正确答案为D。\n【考点】\n商品与货币","figs":[],"state":"已标记","notes":[],"domains":["经济"],"nature":"知识题","current":false,"links":[{"id":"k-labor","label":"商品经济理论 · 劳动二重性","catalog_id":"8b483b708f211e74","type":"原理与机制","role":"直接考查","field":"question","quote":"具体劳动创造商品的使用价值，抽象劳动形成商品的价值","why":"题目要求区分同一生产劳动的两个方面及其分别对应的使用价值和价值。","origin":"逐题标记"}]},"国考 2025 地市级 行测#4":{"stem":"习近平总书记指出：“中国共产党人的理想信念，建立在马克思主义科学真理的基础之上，建立在马克思主义揭示\n的人类社会发展规律的基础之上，建立在为最广大人民谋利益的崇高价值的基础之上。我们坚定，是因为我们追求\n的是真理。我们坚定，是因为我们遵循的是规律。我们坚定，是因为我们代表的是最广大人民根本利益。”这一论述\n最直接体现了马克思主义的哪一基本观点？","options":["真理尺度与价值尺度的辩证统一","认识世界与改造世界的辩证统一","量变与质变的辩证统一","矛盾的特殊性与普遍性的辩证统一"],"answer":"A","analysis":"4. 正确答案：A\n解析：\n本题考查马克思主义。\nA项正确，真理是标志主观与客观相符合的哲学范畴，是对客观事物及其规律的正确反映。“中国共产党人的理想信\n念，建立在马克思主义科学真理和人类社会发展规律的基础之上”即体现了真理原则。价值是指在实践基础上形成的\n主体和客体之间的意义关系，是客体对个人、群体乃至整个社会的生活和活动所具有的积极意义。“建立在为最广大\n人民谋利益的崇高价值的基础之上”和“代表的是最广大人民根本利益”即体现了价值原则。\nB项错误，从认识论的角度来看，人类的活动不外乎两种，即认识世界和改造世界。认识世界的任务不仅在于解释世\n界，更重要的在于为改造世界提供理论指导。认识世界和改造世界是相互依赖、相互制约、辩证统一的。认识世界\n是为了改造世界，正确地认识世界是有效地改造世界的必要前提。题干并未体现认识世界与改造世界的辩证统一。\nC项错误，量变质变规律揭示了事物发展的形式和状态，量变是质变的必要准备，质变是量变的必然结果，量变和质\n变相互渗透。题干并未体现量变与质变的辩证统一。\nD项错误，矛盾的普遍性和特殊性的关系，也就是共性与个性、一般与个别的关系。矛盾普遍性与特殊性是互相联系\n的。普遍性存在于特殊性之中，特殊性中包含着普遍性；普遍性与特殊性在一定条件下可以互相转化。题干并未体\n现矛盾的特殊性与普遍性的辩证统一。\n故正确答案为A。\n【考点】\n唯物论","figs":[],"state":"已标记","notes":[],"domains":["哲学"],"nature":"知识题","current":false,"links":[{"id":"k-7a9c4e72b481a4bc","label":"真理尺度与价值尺度的辩证统一","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"真理尺度与价值尺度的辩证统一","why":"遵循客观规律体现真理尺度，为最广大人民谋利益体现价值尺度，题干把两者统一于理想信念的基础之中。","origin":"逐题标记"}]},"国考 2025 地市级 行测#5":{"stem":"高质量发展是全面建设社会主义现代化国家的首要任务，金融要为经济社会发展提供高质量服务。下列与之相关\n的表述不准确的是：","options":["优化资金供给结构，把更多金融资源用于促进科技创新、绿色发展、传统制造和国有企业","要着力营造良好的货币金融环境，切实加强对重大战略、重点领域和薄弱环节的优质金融服务","始终保持货币政策的稳健性，更加注重做好跨周期和逆周期调节，充实货币政策工具箱","完善机构定位，支持国有大型金融机构做优做强，当好服务实体经济的主力军和维护金融稳定的压舱石"],"answer":"A","analysis":"5. 正确答案：A\n解析：\n本题考查理论与政策。\n2023年10月30日至31日，中央金融工作会议在北京举行。习近平总书记出席会议并发表重要讲话，科学回答了金融\n事业发展的一系列重大理论和实践问题。\nB、C两项正确，A项错误，会议指出，高质量发展是全面建设社会主义现代化国家的首要任务，金融要为经济社会\n发展提供高质量服务。要着力营造良好的货币金融环境，切实加强对重大战略、重点领域和薄弱环节的优质金融服\n务。始终保持货币政策的稳健性，更加注重做好跨周期和逆周期调节，充实货币政策工具箱。优化资金供给结构，\n把更多金融资源用于促进科技创新、先进制造、绿色发展和中小微企业，大力支持实施创新驱动发展战略、区域协\n调发展战略，确保国家粮食和能源安全等。\nD项正确，会议指出，完善机构定位，支持国有大型金融机构做优做强，当好服务实体经济的主力军和维护金融稳定\n的压舱石，严格中小金融机构准入标准和监管要求，立足当地开展特色化经营，强化政策性金融机构职能定位，发\n挥保险业的经济减震器和社会稳定器功能。\n本题为选非题，故正确答案为A。\n【考点】\n经济建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-016afa40aa881bae","label":"金融资源重点投向科技创新、先进制造、绿色发展和中小微企业","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"把更多金融资源用于促进科技创新、先进制造、绿色发展和中小微企业","why":"政策明确了优化资金供给结构时应重点支持的产业方向和企业群体。","origin":"逐题标记"},{"id":"k-9d9271537a7a63d7","label":"金融服务重点覆盖重大战略、重点领域和薄弱环节","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"切实加强对重大战略、重点领域和薄弱环节的优质金融服务","why":"会议部署明确了优质金融服务的重点覆盖范围。","origin":"逐题标记"},{"id":"k-265101863520c2c1","label":"保持货币政策稳健并加强跨周期和逆周期调节","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"始终保持货币政策的稳健性，更加注重做好跨周期和逆周期调节，充实货币政策工具箱。","why":"会议部署同时明确了货币政策的基调、调节要求和工具安排。","origin":"逐题标记"},{"id":"k-68911927a32560ef","label":"国有大型金融机构服务实体经济和维护金融稳定的职责","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"当好服务实体经济的主力军和维护金融稳定的压舱石","why":"这两项职责具体界定了会议对国有大型金融机构的定位。","origin":"逐题标记"}]},"国考 2025 地市级 行测#6":{"stem":"习近平总书记强调，粮食安全是“国之大者”。下列保障粮食安全的举措正确的有几项？\n①全面落实粮食安全党政同责，坚持稳面积、增单产两手发力\n②树立大农业观、大食物观，农林牧渔并举，构建多元化食物供给体系\n③加大高标准农田建设投入和管护力度，确保耕地数量有保障、质量有提升\n④扩大粮食领域高水平对外开放，逐步加大国外优质种业资源和海外粮食产品在我国市场的占有率\n\n⑤强化科技和改革双轮驱动，加大核心技术攻关力度","options":["2项","3项","4项","5项"],"answer":"C","analysis":"6. 正确答案：C\n解析：\n本题考查理论与政策。\n①正确，2023年12月14日至15日，习近平总书记来到广西考察，指出乡村振兴是建设农业强国的基础性工程，要落\n实规划、扎实推进。要全面落实粮食安全党政同责，坚持稳面积、增单产两手发力，实现粮食均衡增产。\n②正确，2024年9月15日发布的《国务院办公厅关于践行大食物观构建多元化食物供给体系的意见》指出，树立大农\n业观、大食物观，农林牧渔并举，构建多元化食物供给体系，是党中央提出的明确要求，是保障粮食和重要农产品\n稳定安全供给的客观要求和重要举措。\n\n③⑤正确，2023年12月19日召开的中央农村工作会议指出，要守住耕地这个命根子，坚决整治乱占、破坏耕地违法\n行为，加大高标准农田建设投入和管护力度，确保耕地数量有保障、质量有提升。要强化科技和改革双轮驱动，加\n大核心技术攻关力度，改革完善“三农”工作体制机制，为农业现代化增动力、添活力。\n④错误，中央经济工作会议提出，在经济全球化深入发展的背景下，我国进一步推进农业现代化，同样要用好国内\n国际两个市场、两种资源，深化农业对外开放，发挥超大规模市场和强大生产能力的优势。但“加大国外优质种业资\n源和海外粮食产品在我国市场的占有率”的做法不利于我国的粮食安全。习总书记强调的“中国人的饭碗任何时候都要\n牢牢端在自己手中”，是基于对粮食基本属性的正确认识和粮食战略价值的准确评估作出的重大判断，对于维护社会\n稳定、保障国民经济平稳运行、应对国际变局具有重要意义。\n故正确的有4项。\n故正确答案为C。\n【考点】\n经济建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-b52208ee259a41b2","label":"粮食安全党政同责与稳面积、增单产并举","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"全面落实粮食安全党政同责，坚持稳面积、增单产两手发力","why":"这一要求同时明确粮食安全的责任安排和实现均衡增产的两条途径。","origin":"逐题标记"},{"id":"k-6129abc029f16867","label":"多元化食物供给体系","catalog_id":"9784754828cadfa9","type":"制度与规则","role":"直接考查","field":"question","quote":"树立大农业观、大食物观，农林牧渔并举，构建多元化食物供给体系","why":"农林牧渔并举是保障粮食和重要农产品稳定安全供给的政策举措。","origin":"逐题标记"},{"id":"k-3e95b77eeabd0099","label":"高标准农田建设","catalog_id":"18b15dd81bc52dab","type":"制度与规则","role":"直接考查","field":"question","quote":"加大高标准农田建设投入和管护力度，确保耕地数量有保障、质量有提升","why":"题目核对农田建设和管护投入服务于耕地数量保障与质量提升的要求。","origin":"逐题标记"},{"id":"k-10875ff0d8a54918","label":"农业现代化坚持科技和改革双轮驱动并加强核心技术攻关","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"强化科技和改革双轮驱动，加大核心技术攻关力度","why":"中央农村工作会议把科技攻关和完善农业农村工作机制共同纳入农业现代化部署。","origin":"逐题标记","originalId":"k-865d37e48a1ad809"},{"id":"k-b0009f035ababd61","label":"农业对外开放须以保障粮食安全为前提","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"中国人的饭碗任何时候都要牢牢端在自己手中","why":"粮食安全的自主保障要求用于判断扩大海外粮食产品和国外种业资源市场份额这一举措。","origin":"逐题标记"}]},"国考 2025 地市级 行测#7":{"stem":"习近平总书记强调，要坚定不移贯彻新发展理念，更加自觉地把高质量充分就业作为经济社会发展的优先目标。\n下列关于高质量充分就业的表述正确的是：\n①全面贯彻劳动者自主就业、政府主导就业、市场促进就业的方针\n②坚持扩大就业容量和提升就业质量相结合\n③坚持就业带动创业\n④加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点","options":["①②","①③","②④","③④"],"answer":"C","analysis":"7. 正确答案：C\n解析：\n本题考查理论与政策。\n2024年10月31日，《求是》杂志发表习近平总书记的重要文章《促进高质量充分就业》。\n①错误，文章指出：“要坚持以人民为中心的发展思想，全面贯彻劳动者自主就业、市场调节就业、政府促进就业和\n鼓励创业的方针，以推动高质量发展为基础，以实施就业优先战略为引领，以强化就业优先政策为抓手，以深化就\n业体制机制改革为动力，持续促进就业质的有效提升和量的合理增长，不断增强广大劳动者的获得感幸福感安全\n感，为以中国式现代化全面推进强国建设、民族复兴伟业提供有力支撑。”\n②正确，③错误，文章指出：“在这个过程中，我们不断深化对新时代就业工作规律的认识，积累了许多经验，主要\n包括：坚持党对就业工作的全面领导，坚持把就业作为民生之本，坚持实施就业优先战略，坚持依靠发展促进就\n业，坚持扩大就业容量和提升就业质量相结合，坚持突出抓好重点群体就业，坚持创业带动就业，坚持营造公平就\n业环境，坚持构建和谐劳动关系，等等。这些经验十分宝贵，要长期坚持并不断丰富发展。”\n④正确，文章指出：“加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点，及时总结经验、形成制\n度。加强市场监管和劳动保障监察执法，有效治理就业歧视、欠薪欠保、违法裁员等乱象。”\n故②④表述正确。\n故正确答案为C。\n【考点】\n经济建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济","社会治理"],"nature":"知识题","current":true,"links":[{"id":"k-c9e54faa00997e23","label":"促进高质量充分就业","catalog_id":"89c071eacc7a83cb","type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持扩大就业容量和提升就业质量相结合","why":"这一要求把扩大就业规模与改善就业质量共同作为就业工作目标。","origin":"逐题标记"},{"id":"k-1ee6f0c02f41907a","label":"劳动者自主就业、市场调节就业、政府促进就业和鼓励创业的方针","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"全面贯彻劳动者自主就业、市场调节就业、政府促进就业和","why":"就业方针明确了劳动者、市场和政府的不同作用，并纳入鼓励创业。","origin":"逐题标记"},{"id":"k-2c4328a87ea1b2ff","label":"坚持创业带动就业","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"坚持创业带动就业","why":"政策明确以创业带动就业，带动方向是判断相关表述的依据。","origin":"逐题标记"},{"id":"k-18c82678850d3bcc","label":"保障灵活就业和新就业形态劳动者权益并扩大职业伤害保障试点","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"加强灵活就业和新就业形态劳动者权益保障，扩大职业伤害保障试点","why":"这一举措明确了权益保障对象及职业伤害保障试点的推进方向。","origin":"逐题标记","originalId":"k-d1592e3853590e62"}]},"国考 2025 地市级 行测#8":{"stem":"党的十八大以来，在推进全面从严治党的伟大实践中，我们不断进行实践探索和理论思考，在毛泽东同志当年给\n出“让人民来监督政府”的第一个答案基础上，给出了第二个答案，那就是不断推进党的自我革命。关于深入推进党的\n自我革命实践，下列表述不准确的是：","options":["以引领伟大社会革命为根本目的","以跳出历史周期率为战略目标","以解决大党独有难题为主攻方向","以自我监督和法律监督相结合为强大动力"],"answer":"D","analysis":"8. 正确答案：D\n解析：\n本题考查理论与政策。\nA、B、C三项正确，D项错误。习近平总书记在二十届中央纪委三次全会上深刻阐述了党的自我革命的重要思想，对\n持续发力、纵深推进反腐败斗争作出战略部署，明确提出了新征程上深入推进党的自我革命“九个以”的实践要求。以\n坚持党中央集中统一领导为根本保证。以引领伟大社会革命为根本目的。以习近平新时代中国特色社会主义思想为\n根本遵循。以跳出历史周期率为战略目标。以解决大党独有难题为主攻方向。以健全全面从严治党体系为有效途\n径。以锻造坚强组织、建设过硬队伍为重要着力点。以正风肃纪反腐为重要抓手。以自我监督和人民监督相结合为\n强大动力。\n本题为选非题，故正确答案为D。\n【考点】\n党的建设,重大会议及讲话","figs":[],"state":"待核","notes":["作答依赖全会提出的具体实践要求，所给解析只有届次和会次，缺少用于确认时政窗口的召开年份。"],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-1632ca8680fadb9b","label":"深入推进党的自我革命的“九个以”实践要求","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"明确提出了新征程上深入推进党的自我革命“九个以”的实践要求。","why":"题目核对引领伟大社会革命、跳出历史周期率、解决大党独有难题以及自我监督和人民监督相结合各自对应的实践要求。","origin":"逐题标记"}]},"国考 2025 地市级 行测#9":{"stem":"习近平总书记指出，要加强科技基础能力建设，深化科技体制改革，打造科创高地。关于深化科技体制改革，下\n列表述正确的是：","options":["建立以竞争性支持取代稳定支持的基础研究投入机制","允许科研类事业单位实行比一般事业单位更灵活的管理制度","限制开展高风险、高投入基础研究","降低科技人员在科技成果转化收益分配上的自主权"],"answer":"B","analysis":"9. 正确答案：B\n解析：\n本题考查理论与政策。\n2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过了《中共中央关于进一步全面深化改革 推进\n中国式现代化的决定》（以下简称《决定》）。\nA项错误，《决定》在“四、构建支持全面创新体制机制”部分的“（14）深化科技体制改革”中指出：“改进科技计划管\n理，强化基础研究领域、交叉前沿领域、重点领域前瞻性、引领性布局。加强有组织的基础研究，提高科技支出用\n\n于基础研究比重，完善竞争性支持和稳定支持相结合的基础研究投入机制，鼓励有条件的地方、企业、社会组织、\n个人支持基础研究，支持基础研究选题多样化，鼓励开展高风险、高价值基础研究。”\nB项正确，《决定》在“四、构建支持全面创新体制机制”部分的“（14）深化科技体制改革”中指出：“完善中央财政科\n技经费分配和管理使用机制，健全中央财政科技计划执行和专业机构管理体制······允许科研类事业单位实行比一般\n事业单位更灵活的管理制度，探索实行企业化管理。”\nC项错误，《决定》在“四、构建支持全面创新体制机制”部分的“（14）深化科技体制改革”中指出：“加强有组织的基\n础研究，提高科技支出用于基础研究比重，完善竞争性支持和稳定支持相结合的基础研究投入机制，鼓励有条件的\n地方、企业、社会组织、个人支持基础研究，支持基础研究选题多样化，鼓励开展高风险、高价值基础研究。”\nD项错误，《决定》在“四、构建支持全面创新体制机制”部分的“（14）深化科技体制改革”中指出：“允许科技人员在\n科技成果转化收益分配上有更大自主权，建立职务科技成果资产单列管理制度，深化职务科技成果赋权改革。深化\n高校、科研院所收入分配改革。”\n故正确答案为B。\n【考点】\n经济建设,重要文件","figs":[],"state":"已标记","notes":[],"domains":["政治理论","科技","公共管理"],"nature":"知识题","current":true,"links":[{"id":"k-33019888376c71a6","label":"科研类事业单位实行更灵活的管理制度","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"允许科研类事业单位实行比一般事业单位更灵活的管理制度","why":"解析确认《决定》允许科研类事业单位实行更灵活的管理制度，并提出探索实行企业化管理。","origin":"逐题标记"}]},"国考 2025 地市级 行测#10":{"stem":"完善收入分配制度，构建初次分配、再分配、第三次分配协调配套的制度体系，是进一步全面深化改革的重要任\n务。关于完善收入分配制度，下列表述不准确的是：","options":["提高劳动报酬在初次分配中的比重","完善劳动者工资决定、合理增长、支付保障机制，健全按要素分配政策制度","规范财富积累机制，多渠道增加城乡居民财产性收入","完善税收、社会保障、转移支付等第三次分配调节机制"],"answer":"D","analysis":"10. 正确答案：D\n解析：\n本题考查理论与政策。\n2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过了《中共中央关于进一步全面深化改革 推进\n中国式现代化的决定》（以下简称《决定》）。\nA、B两项正确，D项错误，《决定》在“十一、健全保障和改善民生制度体系”部分“（42）完善收入分配制度”中指\n出：“构建初次分配、再分配、第三次分配协调配套的制度体系，提高居民收入在国民收入分配中的比重，提高劳动\n报酬在初次分配中的比重。完善劳动者工资决定、合理增长、支付保障机制，健全按要素分配政策制度。完善税\n收、社会保障、转移支付等再分配调节机制。支持发展公益慈善事业。”\nC项正确，《决定》在“十一、健全保障和改善民生制度体系”部分“（42）完善收入分配制度”中指出：“规范收入分配\n秩序，规范财富积累机制，多渠道增加城乡居民财产性收入，形成有效增加低收入群体收入、稳步扩大中等收入群\n体规模、合理调节过高收入的制度体系。深化国有企业工资决定机制改革，合理确定并严格规范国有企业各级负责\n人薪酬、津贴补贴等。”\n本题为选非题，故正确答案为D。\n【考点】\n社会建设,重要文件","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-a00a8fcb9d224472","label":"收入分配制度","catalog_id":"5cbd9b1179a2a2b6","type":"制度与规则","role":"直接考查","field":"answer","quote":"社会保障、转移支付等再分配调节机制。支持发展公益慈善事业。","why":"税收、社会保障和转移支付是再分配调节手段，公益慈善是第三次分配的重要形式。","origin":"逐题标记"}]},"国考 2025 地市级 行测#11":{"stem":"习近平总书记强调，要牢牢扭住自主创新这个“牛鼻子”。关于自主创新的举措，下列表述正确的有几项？\n①主动对接国家战略需求，整合和优化科教创新资源\n②培育产业园区，加强对口合作，加快科研成果落地转化\n③培育新能源、新材料、先进制造、电子信息等战略性新兴产业\n④建设风光火核储一体化能源基地\n⑤逐步弱化央地合作，鼓励各地自主发展新兴产业","options":["2项","3项","4项","5项"],"answer":"C","analysis":"11. 正确答案：C\n解析：\n本题考查理论与政策。\n2023年9月7日，中共中央总书记、国家主席、中央军委主席习近平在黑龙江省哈尔滨市主持召开新时代推动东北全\n面振兴座谈会并发表重要讲话（以下简称“讲话”）。\n①②③④正确，⑤错误，习近平总书记在讲话中强调，要以科技创新推动产业创新，加快构建具有东北特色优势的\n现代化产业体系······主动对接国家战略需求，整合和优化科教创新资源，加大研发投入，掌握更多关键核心技术。\n积极培育产业园区，加强对口合作，加快科研成果落地转化。积极培育新能源、新材料、先进制造、电子信息等战\n略性新兴产业，积极培育未来产业，加快形成新质生产力，增强发展新动能。加快发展风电、光电、核电等清洁能\n源，建设风光火核储一体化能源基地······创新央地合作模式，促进央地融合发展，更好带动地方经济发展。\n综上，共4项正确。\n故正确答案为C。\n【考点】\n经济建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济","科技"],"nature":"知识题","current":true,"links":[{"id":"k-bab481d884488a98","label":"东北振兴对接国家战略需求并整合科教创新资源","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"主动对接国家战略需求，整合和优化科教创新资源","why":"讲话要求东北面向国家战略需求配置科教创新资源。","origin":"逐题标记"},{"id":"k-8f8bdc0df14e77f0","label":"东北振兴通过产业园区和对口合作促进科研成果转化","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"积极培育产业园区，加强对口合作，加快科研成果落地转化。","why":"讲话将培育产业园区和加强对口合作列为促进科研成果落地的举措。","origin":"逐题标记"},{"id":"k-0b5dc68bbfc10583","label":"新兴产业和未来产业","catalog_id":"f5b282a655709f81","type":"制度与规则","role":"直接考查","field":"question","quote":"培育新能源、新材料、先进制造、电子信息等战略性新兴产业","why":"解析确认讲话将所列产业纳入东北振兴的战略性新兴产业培育部署，并提出培育未来产业。","origin":"逐题标记"},{"id":"k-e49c8bd2f1169d98","label":"东北振兴建设风光火核储一体化能源基地","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"建设风光火核储一体化能源基地","why":"讲话把建设风光火核储一体化能源基地列为东北能源发展的具体举措。","origin":"逐题标记"},{"id":"k-5742012cd85fd304","label":"东北振兴创新央地合作模式并促进央地融合发展","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"创新央地合作模式，促进央地融合发展","why":"央地融合发展的要求决定了应如何判断逐步弱化央地合作的说法。","origin":"逐题标记"}]},"国考 2025 地市级 行测#12":{"stem":"党的二十届三中全会提出，要稳步扩大制度型开放。关于稳步扩大制度型开放，下列举措不恰当的是：","options":["独立自主构建不同于国际经贸规则的中国特色经贸规则体系","有序扩大我国商品市场、服务市场、资本市场、劳务市场等对外开放","积极参与全球经济治理体系改革，提供更多全球公共产品","扩大对最不发达国家单边开放"],"answer":"A","analysis":"12. 正确答案：A\n解析：\n本题考查理论与政策。\nA项错误，B、C、D三项正确，2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过的《中共中央\n关于进一步全面深化改革 推进中国式现代化的决定》在“七、完善高水平对外开放体制机制”部分指出：“（24）稳步\n扩大制度型开放。主动对接国际高标准经贸规则，在产权保护、产业补贴、环境标准、劳动保护、政府采购、电子\n\n商务、金融领域等实现规则、规制、管理、标准相通相容，打造透明稳定可预期的制度环境。扩大自主开放，有序\n扩大我国商品市场、服务市场、资本市场、劳务市场等对外开放，扩大对最不发达国家单边开放······积极参与全球\n经济治理体系改革，提供更多全球公共产品······”\n本题为选非题，故正确答案为A。\n【考点】\n和平外交建设,重要文件","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-76f3ab01b88b79f9","label":"制度型开放","catalog_id":"31699340f47012e7","type":"制度与规则","role":"直接考查","field":"answer","quote":"主动对接国际高标准经贸规则","why":"制度型开放要求在相关领域推动规则、规制、管理和标准相通相容，以此判断经贸规则建设的方向。","origin":"逐题标记"}]},"国考 2025 地市级 行测#13":{"stem":"习近平总书记指出，宣传思想文化工作事关党的前途命运，事关国家长治久安，事关民族凝聚力和向心力，是一\n项极端重要的工作。宣传思想文化工作的首要政治任务是：","options":["培育和践行社会主义核心价值观","用党的创新理论武装全党、教育人民","提升国家文化软实力和中华文化影响力","赓续中华文脉、推动中华优秀传统文化创造性转化和创新性发展"],"answer":"B","analysis":"13. 正确答案：B\n解析：\n本题考查理论与政策。\n2023年10月7日至8日，全国宣传思想文化工作会议在北京召开。会上传达了习近平总书记对宣传思想文化工作作出\n的重要指示。\nB项正确，A、C、D三项错误，习近平总书记强调，宣传思想文化工作面临新形势新任务，必须要有新气象新作为。\n要坚持以新时代中国特色社会主义思想为指导，全面贯彻党的二十大精神，聚焦用党的创新理论武装全党、教育人\n民这个首要政治任务······着力培育和践行社会主义核心价值观······着力赓续中华文脉、推动中华优秀传统文化创造\n性转化和创新性发展······不断提升国家文化软实力和中华文化影响力，为全面建设社会主义现代化国家、全面推进\n中华民族伟大复兴提供坚强思想保证、强大精神力量、有利文化条件。\n故正确答案为B。\n【考点】\n社会建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论","文化"],"nature":"知识题","current":true,"links":[{"id":"k-5463af2ea6914a4a","label":"宣传思想文化工作的首要政治任务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"用党的创新理论武装全党、教育人民","why":"解析确认重要指示明确将用党的创新理论武装全党、教育人民列为首要政治任务。","origin":"逐题标记","originalId":"k-b4ba07f3316e4b25"}]},"国考 2025 地市级 行测#14":{"stem":"完善大统战工作格局，是习近平总书记关于做好新时代党的统一战线工作的重要思想的重要内容，是做好新时代\n统战工作的重要保障，也是进一步全面深化改革、为推进中国式现代化凝心聚力的重要举措。下列各项不属于完善\n大统战格局措施的是：","options":["更好发挥党外人士作用，健全党外代表人士队伍建设制度","制定民族团结进步促进法，健全铸牢中华民族共同体意识制度机制","全面构建亲清政商关系，健全促进非公有制经济健康发展、非公有制经济人士健康成长工作机制","健全人大议事规则和论证、评估、评议、听证制度"],"answer":"D","analysis":"14. 正确答案：D\n解析：\n本题考查理论与政策。\n2024年7月18日，中国共产党第二十届中央委员会第三次全体会议正式通过《中共中央关于进一步全面深化改革 推\n进中国式现代化的决定》（以下简称《决定》）。\nA、B、C三项正确，《决定》在“八、健全全过程人民民主制度体系”部分指出：“（32）完善大统战工作格局。完善\n发挥统一战线凝聚人心、汇聚力量政治作用的政策举措。坚持好、发展好、完善好中国新型政党制度。更好发挥党\n外人士作用，健全党外代表人士队伍建设制度。制定民族团结进步促进法，健全铸牢中华民族共同体意识制度机\n制，增强中华民族凝聚力。系统推进我国宗教中国化，加强宗教事务治理法治化。完善党外知识分子和新的社会阶\n层人士政治引领机制。全面构建亲清政商关系，健全促进非公有制经济健康发展、非公有制经济人士健康成长工作\n机制。完善港澳台和侨务工作机制。”\nD项错误，《决定》在“八、健全全过程人民民主制度体系”部分指出：“（29）加强人民当家作主制度建设······健全人\n大议事规则和论证、评估、评议、听证制度。丰富人大代表联系人民群众的内容和形式。健全吸纳民意、汇集民智\n工作机制。发挥工会、共青团、妇联等群团组织联系服务群众的桥梁纽带作用。”\n本题为选非题，故正确答案为D。\n【考点】\n政治建设,重要文件","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":true,"links":[{"id":"k-440f6bbced89d97b","label":"完善大统战工作格局的制度举措","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"完善发挥统一战线凝聚人心、汇聚力量政治作用的政策举措。","why":"党外代表人士队伍建设、铸牢中华民族共同体意识和亲清政商关系建设均列入《决定》的统战改革部署。","origin":"逐题标记"},{"id":"k-95dcffde921a07f8","label":"人民当家作主制度建设中的人大议事和听证制度","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"（29）加强人民当家作主制度建设······健全人\n大议事规则和论证、评估、评议、听证制度。","why":"《决定》将人大议事规则和相关程序列入加强人民当家作主制度建设的部署。","origin":"逐题标记"}]},"国考 2025 地市级 行测#15":{"stem":"党的二十届三中全会提出，健全绿色低碳发展机制，实施支持绿色低碳发展的财税、金融、投资、价格政策和标\n准体系，发展绿色低碳产业，健全绿色消费激励机制，促进绿色低碳循环发展经济体系建设。关于健全绿色低碳发\n展机制，下列举措不恰当的是：","options":["优化政府绿色采购政策，完善绿色税制","建立碳排放双控向能耗双控全面转型新机制","完善资源总量管理和全面节约制度，健全废弃物循环利用体系","加快规划建设新型能源体系，完善新能源消纳和调控政策措施"],"answer":"B","analysis":"15. 正确答案：B\n解析：\n本题考查理论与政策。\nA、C、D三项正确，B项错误，《中共中央关于进一步全面深化改革、推进中国式现代化的决定》“十二、深化生态\n文明体制改革”部分指出：“（49）健全绿色低碳发展机制。实施支持绿色低碳发展的财税、金融、投资、价格政策和\n标准体系，发展绿色低碳产业，健全绿色消费激励机制，促进绿色低碳循环发展经济体系建设。优化政府绿色采购\n政策，完善绿色税制。完善资源总量管理和全面节约制度，健全废弃物循环利用体系。健全煤炭清洁高效利用机\n制。加快规划建设新型能源体系，完善新能源消纳和调控政策措施。完善适应气候变化工作体系。建立能耗双控向\n碳排放双控全面转型新机制。构建碳排放统计核算体系、产品碳标识认证制度、产品碳足迹管理体系，健全碳市场\n交易制度、温室气体自愿减排交易制度，积极稳妥推进碳达峰碳中和。”\n本题为选非题，故正确答案为B。\n【考点】\n经济建设,重要文件","figs":[],"state":"已标记","notes":[],"domains":["政治理论","生态环境"],"nature":"知识题","current":true,"links":[{"id":"k-8c1fa4140851f799","label":"能耗双控向碳排放双控全面转型","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"建立能耗双控向\n碳排放双控全面转型新机制。","why":"《决定》将能耗双控确定为转型起点，将碳排放双控确定为转型方向。","origin":"逐题标记"}]},"国考 2025 地市级 行测#16":{"stem":"深化医药卫生体制改革，是进一步全面深化改革的重要任务。关于深化医药卫生体制改革，下列举措不恰当的\n是：","options":["促进优质医疗资源扩容下沉和区域均衡布局","加快建设分级诊疗体系，强化基层医疗卫生服务","完善公立医院薪酬制度，严格限制、缩减编制数量","促进医疗、医保、医药协同发展和治理"],"answer":"C","analysis":"16. 正确答案：C\n\n解析：\n本题考查理论与政策。\n2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过了《中共中央关于进一步全面深化改革 推进\n中国式现代化的决定》（以下简称《决定》）。\nA、B、D三项正确，C项错误，《决定》中“十一、健全保障和改善民生制度体系”中“（45）深化医药卫生体制改\n革”部分指出：“实施健康优先发展战略，健全公共卫生体系，促进社会共治、医防协同、医防融合，强化监测预警、\n风险评估、流行病学调查、检验检测、应急处置、医疗救治等能力。促进医疗、医保、医药协同发展和治理。促进\n优质医疗资源扩容下沉和区域均衡布局，加快建设分级诊疗体系，推进紧密型医联体建设，强化基层医疗卫生服\n务。深化以公益性为导向的公立医院改革，建立以医疗服务为主导的收费机制，完善薪酬制度，建立编制动态调整\n机制。引导规范民营医院发展。创新医疗卫生监管手段。健全支持创新药和医疗器械发展机制，完善中医药传承创\n新发展机制。”故“严格限制、缩减编制数量”说法错误。\n本题为选非题，故正确答案为C。\n【考点】\n社会建设,重要文件","figs":[],"state":"已标记","notes":[],"domains":["政治理论","公共管理"],"nature":"知识题","current":true,"links":[{"id":"k-71ef9e139ab9eee8","label":"公立医院编制动态调整机制","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"完善薪酬制度，建立编制动态调整\n机制。","why":"《决定》要求公立医院在完善薪酬制度的同时建立编制动态调整机制，据此可判断缩减编制的说法。","origin":"逐题标记"}]},"国考 2025 地市级 行测#17":{"stem":"完善市场经济基础制度是构建高水平社会主义市场经济体制的重要内容。下列不属于完善市场经济基础制度内容\n的是：","options":["完善财政转移支付体系","完善市场信息披露制度","完善市场准入制度","完善产权制度"],"answer":"A","analysis":"17. 正确答案：A\n解析：\n本题考查理论与政策。\nA项错误，B、C、D三项正确，2024年7月18日中国共产党第二十届中央委员会第三次全体会议通过《中共中央关于\n进一步全面深化改革 推进中国式现代化的决定》，其中“二、构建高水平社会主义市场经济体制”部分指出：“（7）\n完善市场经济基础制度。完善产权制度，依法平等长久保护各种所有制经济产权，建立高效的知识产权综合管理体\n制。完善市场信息披露制度，构建商业秘密保护制度······完善市场准入制度，优化新业态新领域市场准入环境。深\n化注册资本认缴登记制度改革，实行依法按期认缴。健全企业破产机制，探索建立个人破产制度，推进企业注销配\n套改革，完善企业退出制度。健全社会信用体系和监管制度。”而“完善财政转移支付体系”属于“深化财税体制改革”的\n内容。\n本题为选非题，故正确答案为A。\n【考点】\n经济建设,重要文件","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-792ffc72bda5a188","label":"完善市场经济基础制度的内容","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"B.完善市场信息披露制度\nC.完善市场准入制度\nD.完善产权制度","why":"三项均列入《决定》关于完善市场经济基础制度的部署。","origin":"逐题标记"},{"id":"k-7c21a486552ce461","label":"完善财政转移支付体系属于深化财税体制改革","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"“完善财政转移支付体系”属于“深化财税体制改革”的\n内容。","why":"依据该事项在《决定》中的归属判断改革类别。","origin":"逐题标记"}]},"国考 2025 地市级 行测#18":{"stem":"习近平总书记强调，加强党风廉政建设，一体推进不敢腐、不能腐、不想腐，严格落实中央八项规定精神，督促\n党员、干部特别是领导干部清廉自守、廉洁从政、干净做事。根据《中国共产党纪律处分条例》，下列违纪情况属\n于违反廉洁纪律的是：","options":["在重大原则问题上不同党中央保持一致且有实际言论、行为或者造成不良后果的","拒不执行党组织的分配、调动、交流等决定的","干涉生产经营自主权，致使群众财产遭受较大损失的","滥用职权或者职务上的影响操办婚丧喜庆事宜，造成不良影响的"],"answer":"D","analysis":"18. 正确答案：D\n解析：\n本题考查理论与政策。《中国共产党纪律处分条例》以下简称《条例》。\nA项错误，《条例》“第六章 对违反政治纪律行为的处分”第四十九条规定：“在重大原则问题上不同党中央保持一致\n且有实际言论、行为或者造成不良后果的，给予警告或者严重警告处分；情节较重的，给予撤销党内职务或者留党\n察看处分；情节严重的，给予开除党籍处分。”\nB项错误，《条例》“第七章 对违反组织纪律行为的处分”第七十九条第一款规定：“拒不执行党组织的分配、调动、\n交流等决定的，给予警告、严重警告或者撤销党内职务处分。”\nC项错误，《条例》“第九章 对违反群众纪律行为的处分”第一百二十三条规定：“干涉生产经营自主权，致使群众财\n产遭受较大损失的，对直接责任者和领导责任者，给予警告或者严重警告处分；情节严重的，给予撤销党内职务或\n者留党察看处分。”\nD项正确，《条例》“第八章 对违反廉洁纪律行为的处分”第一百条规定：“利用职权或者职务上的影响操办婚丧喜庆\n事宜，造成不良影响的，给予警告或者严重警告处分；情节严重的，给予撤销党内职务处分；借机敛财或者有其他\n侵犯国家、集体和人民利益行为的，从重或者加重处分，直至开除党籍。”\n故正确答案为D。\n【考点】\n党的建设","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-af13498b6f12d3f0","label":"利用职权或职务影响操办婚丧喜庆事宜并造成不良影响属于违反廉洁纪律","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"利用职权或者职务上的影响操办婚丧喜庆\n事宜，造成不良影响的","why":"《条例》第一百条据此认定相关行为违反廉洁纪律。","origin":"逐题标记"}]},"国考 2025 地市级 行测#19":{"stem":"习近平总书记指出，要推动各级领导班子认真践行正确政绩观，切实形成正确工作导向。下列表述与正确政绩观\n要求相符合的是：","options":["领导干部要树牢竞争优先、力争上游的政绩观","坚持高质量发展，要完善推动高质量发展的政绩考核评价办法","坚持打基础利长远，要注重在做强发展指标、做优发展数据上下功夫","坚持出实招求实效，要大力发展高标准、大气派的工程"],"answer":"B","analysis":"19. 正确答案：B\n解析：\n本题考查理论与政策。\nA项错误，2024年全国两会期间，习近平总书记在参加十四届全国人大一次会议江苏代表团审议时强调，“不要有大\n干快上的冲动，也就是不能不按规律办事，急功近利、急于出成绩。要把这种浮躁心理、急躁心态都压下来，扎扎\n实实、踏踏实实地搞现代化建设”。“竞争优先、力争上游”的政绩观过于浮躁，不利于党和国家事业的稳定发展。\n\nB项正确，坚持新发展理念、推动高质量发展，是以习近平同志为核心的党中央作出的一项重大战略部署，是关系我\n国发展全局的一场深刻变革。要充分发挥政绩考核指挥棒作用，把贯彻落实习近平总书记重要指示批示精神和党中\n央决策部署，贯彻新发展理念、推动高质量发展的实际表现和工作实绩，作为评价领导班子和领导干部政绩的基本\n依据。2024年2月，习近平总书记在中共中央政治局第十一次集体学习时强调，“完善推动高质量发展的考核评价体\n系，为推动高质量发展打牢基础”。\nC项错误，习近平总书记在2022年春季学期中央党校（国家行政学院）中青年干部培训班开班式上指出：“有些事情\n是不是好事实事，不能只看群众眼前的需求，还要看是否会有后遗症，是否会‘解决一个问题，留下十个遗憾’。我们\n做事情、干工作要既符合党、国家和人民眼前利益的要求，又符合党、国家和人民长远利益的要求。”所以，选项“坚\n持打基础利长远”的说法正确，但“要注重在做强发展指标、做优发展数据上下功夫”表述有误，属于形式主义，与正\n确政绩观“干实事”的要求不一致。\nD项错误，习近平总书记在2021年春季学期中央党校（国家行政学院）中青年干部培训班开班式上的讲话中指\n出：“要坚持实事求是、求真务实，从实际出发谋划事业和工作，使提出的点子、政策、方案符合实际情况、符合客\n观规律、符合科学精神，以创造性工作把党中央决策部署落到实处。”与选项“坚持出实招求实效”的说法对应，属于\n正确政绩观，但“大力发展高标准、大气派的工程”是在搞形象工程，背离了广大群众的利益，会造成严重影响和巨大\n损失。\n故正确答案为B。\n【考点】\n党的建设","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-1adc02dd34141bad","label":"正确政绩观要求以推动高质量发展的实际表现和工作实绩评价政绩","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"贯彻新发展理念、推动高质量发展的实际表现和工作实绩，作为评价领导班子和领导干部政绩的基本\n依据。","why":"该要求明确了完善高质量发展政绩考核评价办法应采用的基本依据。","origin":"逐题标记"}]},"国考 2025 地市级 行测#20":{"stem":"西部地区在全国改革发展稳定大局中举足轻重。要一以贯之抓好党中央推动西部大开发政策举措的贯彻落实，进\n一步形成大保护、大开放、高质量发展新格局。关于新时代推动西部大开发，下列表述不正确的是：","options":["要坚持把全面发展新兴产业作为主攻方向，加快西部地区产业转型升级","要坚持以大开放促进大开发，提高西部地区对内对外开放水平","要坚持统筹发展和安全，提升能源资源等重点领域安全保障能力","要坚持推进新型城镇化和乡村全面振兴有机结合，在发展中保障和改善民生"],"answer":"A","analysis":"20. 正确答案：A\n解析：\n本题考查理论与政策。\n2024年4月23日，中共中央总书记、国家主席、中央军委主席习近平在重庆主持召开新时代推动西部大开发座谈会并\n发表重要讲话。\nA项错误，习近平强调，要坚持把发展特色优势产业作为主攻方向，因地制宜发展新兴产业，加快西部地区产业转型\n升级。强化科技创新和产业创新深度融合，积极培养引进用好高层次科技创新人才，努力攻克一批关键核心技术。\nB项正确，习近平强调，要坚持以大开放促进大开发，提高西部地区对内对外开放水平。大力推进西部陆海新通道建\n设，推动沿线地区开发开放，深度融入共建“一带一路”。\nC项正确，习近平指出，要坚持统筹发展和安全，提升能源资源等重点领域安全保障能力。加快建设新型能源体系，\n做大做强一批国家重要能源基地。\nD项正确，习近平强调，要坚持推进新型城镇化和乡村全面振兴有机结合，在发展中保障和改善民生。深入实施乡村\n振兴战略，加大对国家乡村振兴重点帮扶县支持力度，建立低收入人口和欠发达地区常态化帮扶机制，坚决防止发\n生规模性返贫。\n本题为选非题，故正确答案为A。\n【考点】\n经济建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-3c04393c3295bdcb","label":"新时代西部大开发以发展特色优势产业为主攻方向，因地制宜发展新兴产业","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"要坚持把发展特色优势产业作为主攻方向，因地制宜发展新兴产业","why":"部署分别明确了产业升级的主攻方向和发展新兴产业的条件。","origin":"逐题标记","originalId":"k-abd16a0c792d3701"},{"id":"k-2e4d8e52be2a1238","label":"西部大开发以大开放促进大开发，提高对内对外开放水平","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"要坚持以大开放促进大开发，提高西部地区对内对外开放水平。","why":"该部署明确了开放对西部大开发的带动作用及开放范围。","origin":"逐题标记"},{"id":"k-0c637554e885a5b8","label":"西部大开发统筹发展和安全，提升能源资源等重点领域安全保障能力","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"要坚持统筹发展和安全，提升能源资源等重点领域安全保障能力。","why":"该部署将统筹发展和安全落实到西部重点领域的保障能力建设。","origin":"逐题标记"},{"id":"k-67a5775d9a28143d","label":"西部大开发推进新型城镇化和乡村全面振兴有机结合，在发展中保障和改善民生","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"要坚持推进新型城镇化和乡村全面振兴有机结合，在发展中保障和改善民生。","why":"该部署明确了西部城乡发展与民生保障的政策要求。","origin":"逐题标记"}]},"国考 2025 地市级 行测#21":{"stem":"国家主席习近平在二〇二四年新年贺词中指出：“良渚、二里头的文明曙光，殷墟甲骨的文字传承，三星堆的文\n化瑰宝，国家版本馆的文脉赓续······泱泱中华，历史何其悠久。文明何其博大，这是我们的自信之基、力量之\n源。”下列与之相关的说法不准确的是：","options":["“良渚”遗址中出土了大量的玉器","“殷墟甲骨”中包含了大量的卜辞","“蚕丛及鱼凫”与“二里头”遗址有关","青铜神树是“三星堆的文化瑰宝”之一"],"answer":"C","analysis":"21. 正确答案：C\n解析：\n本题考查人文常识。\nA项正确，良渚古城遗址，位于浙江省杭州市余杭区瓶窑镇凤都路，1986年，考古学者在浙江余杭反山遗址发掘了良\n渚文化大墓11座，出土了1200多件套玉器，包括完整的玉琮、玉璧等。\nB项正确，殷墟位于河南省安阳市，是商代晚期的都城遗址。殷墟甲骨文中的绝大多数材料是卜辞，即占卜记录，但\n占卜的范围很广，包含鬼神、祭祀、战争、农业、田猎、天象、疾病、历法等丰富内容，涉及当时社会的王室、贵\n族、平民和奴隶等各个阶层。\nC项错误，“蚕丛及鱼凫”应与三星堆遗址有关。蚕丛和鱼凫是传说中古蜀国两位国王的名字。三星堆遗址出土的纵目\n面具被认为是蚕丛的象征，出土大量的鸟头勺柄，鸟头形象颇似鱼凫（鱼鹰），被认为可能与古蜀传说中以鱼凫为\n族名、族徽的鱼凫王朝有关。“二里头”遗址，位于洛阳盆地东部的偃师区境内，是迄今为止可确认的中国最早的王国\n都城遗址。\n\nD项正确，三星堆遗址位于四川省广汉市三星堆镇鸭子河南岸。在三星堆遗址共发掘出6棵青铜神树，是“三星堆的文\n化瑰宝”。其中最完整的是Ⅰ号大型铜神树，由底座、树和龙三部分组成，采用分段铸造法铸造，使用了套铸、铆\n铸、嵌铸等工艺，通高3.96米，是中国现存最大的单件青铜文物。\n本题为选非题，故正确答案为C。\n【考点】\n文化常识","figs":[],"state":"已标记","notes":[],"domains":["历史","文化"],"nature":"知识题","current":false,"links":[{"id":"k-1e815463fcb8cf8c","label":"古蜀传说中的蚕丛、鱼凫与三星堆遗址的关联","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"“蚕丛及鱼凫”应与三星堆遗址有关。","why":"解析以传说中的古蜀王及三星堆出土器物的形象解释这组关联。","origin":"逐题标记"},{"id":"k-867a8370eb1e49a0","label":"良渚遗址出土的玉器","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"出土了1200多件套玉器，包括完整的玉琮、玉璧等。","why":"玉琮、玉璧等出土器物支持题中的良渚遗址描述。","origin":"逐题标记"},{"id":"k-36f6c25100a535c5","label":"殷墟甲骨文以卜辞为主","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"殷墟甲骨文中的绝大多数材料是卜辞，即占卜记录","why":"卜辞的含义及其在甲骨文材料中的占比用于核对题中描述。","origin":"逐题标记"},{"id":"k-393b4174ea13962b","label":"三星堆遗址出土的青铜神树","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"在三星堆遗址共发掘出6棵青铜神树","why":"出土记录支持题中青铜神树与三星堆的对应关系。","origin":"逐题标记"}]},"国考 2025 地市级 行测#22":{"stem":"下列情形不在申请行政复议范围之内的是：","options":["餐馆甲因食品卫生不达标，被吊销餐饮服务许可证，甲不服","建设单位乙在申请建筑工程施工许可证时，因申请材料不全被拒绝，乙不服","公务员丙不能胜任工作，其所属行政机关作出降职处理决定，丙不服","工人丁提出工伤认定申请，当地人力资源和社会保障局作出不予受理决定，丁不服"],"answer":"C","analysis":"22. 正确答案：C\n解析：\n本题考查法律常识。\nA项正确，根据《中华人民共和国行政复议法》第十一条第一项规定：“有下列情形之一的，公民、法人或者其他组\n织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服。”根据《中华人民共和国行政处罚法》\n第九条规定：“行政处罚的种类：（一）警告、通报批评；（二）罚款、没收违法所得、没收非法财物；（三）暂扣\n许可证件、降低资质等级、吊销许可证件；（四）限制开展生产经营活动、责令停产停业、责令关闭、限制从业；\n（五）行政拘留；（六）法律、行政法规规定的其他行政处罚。”吊销餐饮服务许可证属于行政处罚，因此，餐馆甲\n有权申请行政复议。\nB项正确，根据《中华人民共和国行政复议法》第十一条第三项规定：“有下列情形之一的，公民、法人或者其他组\n织可以依照本法申请行政复议：（三）申请行政许可，行政机关拒绝或者在法定期限内不予答复，或者对行政机关\n作出的有关行政许可的其他决定不服。”建设单位乙在申请建筑工程施工许可证时，因申请材料不全被拒绝，属于对\n行政机关作出的有关行政许可的决定不服，建设单位乙有权申请行政复议。\nC项错误，根据《中华人民共和国行政复议法》第十二条第三项规定：“下列事项不属于行政复议范围：（三）行政\n机关对行政机关工作人员的奖惩、任免等决定。”针对公务员丙作出的降职处理决定，属于对行政机关工作人员的奖\n惩、任免等决定，不在行政复议范围之内。\nD项正确，根据《中华人民共和国行政复议法》第十一条第七项规定：“有下列情形之一的，公民、法人或者其他组\n织可以依照本法申请行政复议：（七）对行政机关作出的不予受理工伤认定申请的决定或者工伤认定结论不服。”工\n人丁提出工伤认定申请，当地人力资源和社会保障局作出不予受理决定，属于对行政机关作出的不予受理工伤认定\n申请的决定不服，工人丁有权申请行政复议。\n本题为选非题，故正确答案为C。\n【考点】\n行政法","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":false,"links":[{"id":"k-df66ec7589c300c4","label":"行政复议范围排除行政机关内部人事决定","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"行政\n机关对行政机关工作人员的奖惩、任免等决定。","why":"公务员降职属于行政机关内部人事处理，适用该排除条款。","origin":"逐题标记"}]},"国考 2025 地市级 行测#23":{"stem":"关于所有权的取得，下列说法正确的是：","options":["甲在公园捡到一条金项链，经多方寻找失主未果，此时甲获得项链的所有权","乙以市价购买了一辆自行车，后发现该车是卖家借来的，乙仍可获得该车的所有权","丙继承了一处房产，但尚未办理变更登记，丙此时还未获得该房产的所有权","丁从村集体处承包了一块田地用于农作物种植，丁同时取得这块田地的所有权"],"answer":"B","analysis":"23. 正确答案：B\n解析：\n本题考查法律常识。\nA项错误，根据《中华人民共和国民法典》第三百一十四条规定：“拾得遗失物，应当返还权利人。拾得人应当及时\n通知权利人领取，或者送交公安等有关部门。”因此，甲应当及时通知权利人领取，或者送交公安等有关部门，甲并\n不可以获得项链的所有权。\nB项正确，根据《中华人民共和国民法典》第三百一十一条第一款规定：“无处分权人将不动产或者动产转让给受让\n人的，所有权人有权追回；除法律另有规定外，符合下列情形的，受让人取得该不动产或者动产的所有权：（一）\n受让人受让该不动产或者动产时是善意；（二）以合理的价格转让；（三）转让的不动产或者动产依照法律规定应\n当登记的已经登记，不需要登记的已经交付给受让人。”因此，乙以市价购买了一辆自行车，后发现该车是卖家借来\n的，乙可以善意取得该车的所有权。\nC项错误，根据《中华人民共和国民法典》第一千一百二十一条规定：“继承从被继承人死亡时开始。”第二百三十条\n规定：“因继承取得物权的，自继承开始时发生效力。”因此，丙对于该房屋所有权的取得，自继承开始即被继承人死\n亡时发生效力。\nD项错误，根据《中华人民共和国民法典》第三百二十四条规定：“国家所有或者国家所有由集体使用以及法律规定\n属于集体所有的自然资源，组织、个人依法可以占有、使用和收益。”因此，丁对该田地可以依法享有占有、使用和\n收益的权利，并不享有所有权。\n故正确答案为B。\n【考点】\n民法","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":false,"links":[{"id":"k-7b359c13fe41cdea","label":"所有权善意取得的要件","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"受让人受让该不动产或者动产时是善意；（二）以合理的价格转让；（三）转让的不动产或者动产依照法律规定应\n当登记的已经登记，不需要登记的已经交付给受让人。","why":"善意、合理价格和法定的登记或交付是判断无权处分时能否取得所有权的条件。","origin":"逐题标记","originalId":"k-96af23235485e6c6"},{"id":"k-858911ce1d33ae7f","label":"拾得遗失物的返还义务","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"拾得遗失物，应当返还权利人。","why":"拾得人负有返还义务，暂未找到失主不足以使拾得人取得所有权。","origin":"逐题标记"},{"id":"k-5f862ab0ae36cb2d","label":"继承取得物权自继承开始时生效","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"因继承取得物权的，自继承开始时发生效力。","why":"继承开始的时间决定房屋所有权的取得时间。","origin":"逐题标记"},{"id":"k-b21fb3ecf7bc3ab2","label":"集体土地承包经营权的占有、使用和收益权能","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"依法享有占有、使用和\n收益的权利","why":"土地承包产生占有、使用和收益的权利，土地所有权仍归集体。","origin":"逐题标记"}]},"国考 2025 地市级 行测#24":{"stem":"根据《中华人民共和国公司法》的规定，下列事项必须通过国家企业信用信息公示系统公示的是：","options":["某公司与其他公司的合并决议","其公司股东实缴出资额和出资方式","某公司股东会作出的减少注册资本的决议","某公司的破产清算公告"],"answer":"B","analysis":"24. 正确答案：B\n\n解析：\n本题考查法律常识。\nA项错误，根据《中华人民共和国公司法》第二百二十条规定：“公司合并，应当由合并各方签订合并协议，并编制\n资产负债表及财产清单。公司应当自作出合并决议之日起十日内通知债权人，并于三十日内在报纸上或者国家企业\n信用信息公示系统公告。债权人自接到通知之日起三十日内，未接到通知的自公告之日起四十五日内，可以要求公\n司清偿债务或者提供相应的担保。”因此，公司合并决议也可以在报纸上公告。\nB项正确，根据《中华人民共和国公司法》第四十条第一款规定：“公司应当按照规定通过国家企业信用信息公示系\n统公示下列事项：（一）有限责任公司股东认缴和实缴的出资额、出资方式和出资日期，股份有限公司发起人认购\n的股份数；（二）有限责任公司股东、股份有限公司发起人的股权、股份变更信息；（三）行政许可取得、变更、\n注销等信息；（四）法律、行政法规规定的其他信息。”\nC项错误，根据《中华人民共和国公司法》第二百二十四条第二款规定：“公司应当自股东会作出减少注册资本决议\n之日起十日内通知债权人，并于三十日内在报纸上或者国家企业信用信息公示系统公告。债权人自接到通知之日起\n三十日内，未接到通知的自公告之日起四十五日内，有权要求公司清偿债务或者提供相应的担保。”因此，公司减少\n注册资本的决议也可以在报纸上公告。\nD项错误，根据《中华人民共和国公司法》第二百三十五条第一款规定：“清算组应当自成立之日起十日内通知债权\n人，并于六十日内在报纸上或者国家企业信用信息公示系统公告。债权人应当自接到通知之日起三十日内，未接到\n通知的自公告之日起四十五日内，向清算组申报其债权。”因此，公司清算也可以在报纸上公告。\n故正确答案为B。\n【考点】\n经济法","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":false,"links":[{"id":"k-e3d1e70dc90271c2","label":"有限责任公司股东出资信息的强制公示","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"公司应当按照规定通过国家企业信用信息公示系\n统公示下列事项：（一）有限责任公司股东认缴和实缴的出资额、出资方式和出资日期","why":"条文明确指定了股东出资额、出资方式和出资日期的公示渠道。","origin":"逐题标记"},{"id":"k-8b41c00e0b50fc03","label":"公司合并、减资和清算公告可选择报纸或国家企业信用信息公示系统","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"在报纸上或者国家企业信用信息公示系统公告","why":"解析所引的三类公告条款均允许在两个公告渠道中选择。","origin":"逐题标记"}]},"国考 2025 地市级 行测#25":{"stem":"《中华人民共和国消费者权益保护法实施条例》自2024年7月1日起施行。下列说法或做法符合相关法律法规的\n是：","options":["甲公司在消费者订购云服务前将自动续费条款放置于显著位置，消费者同意订购并勾选自动续费，甲公司可在该\n服务到期时自动扣费","乙加油站为消费者提供免费洗车服务时造成车身划痕，该加油站无需承担赔偿责任","丙在某直播平台上直播卖服装，称自己的服装为尾货和瑕疵品，要求大家谨慎购买，该商品不适用七天无理由退\n货","丁健身馆与消费者签订书面合同，约定提供为期半年的健身私教课程服务并收取3000元预付款"],"answer":"D","analysis":"25. 正确答案：D\n解析：\n本题考查法律常识。\nA项错误，根据《中华人民共和国消费者权益保护法实施条例》第十条第二款规定：“经营者采取自动展期、自动续\n费等方式提供服务的，应当在消费者接受服务前和自动展期、自动续费等日期前，以显著方式提请消费者注意。”因\n此，甲公司的自动扣费业务，不仅应当在消费者接受服务前以显著方式提请消费者注意，还应当在自动续费日期\n前，以显著方式提请消费者注意。\nB项错误，根据《中华人民共和国消费者权益保护法实施条例》第七条第二款规定：“经营者向消费者提供商品或者\n服务（包括以奖励、赠送、试用等形式向消费者免费提供商品或者服务），应当保证商品或者服务符合保障人身、\n财产安全的要求······”因此，乙加油站虽然为消费者提供的是免费洗车服务，但仍应当保证商品或者服务符合保障人\n身、财产安全的要求。\nC项错误，根据《中华人民共和国消费者权益保护法实施条例》第十九条第一、二款规定：“经营者通过网络、电\n视、电话、邮购等方式销售商品的，应当遵守消费者权益保护法第二十五条规定，不得擅自扩大不适用无理由退货\n的商品范围。经营者应当以显著方式对不适用无理由退货的商品进行标注，提示消费者在购买时进行确认，不得将\n不适用无理由退货作为消费者默认同意的选项。未经消费者确认，经营者不得拒绝无理由退货。”根据《中华人民共\n和国消费者权益保护法》第二十五条第一、二款规定：“经营者采用网络、电视、电话、邮购等方式销售商品，消费\n者有权自收到商品之日起七日内退货，且无需说明理由，但下列商品除外：（一）消费者定作的；（二）鲜活易腐\n的；（三）在线下载或者消费者拆封的音像制品、计算机软件等数字化商品；（四）交付的报纸、期刊。除前款所\n列商品外，其他根据商品性质并经消费者在购买时确认不宜退货的商品，不适用无理由退货。”因此，在消费者权益\n保护法第二十五条明确规定不适用无理由退货的商品范围以外的商品，未经消费者确认，经营者不得拒绝无理由退\n货。\nD项正确，根据《中华人民共和国消费者权益保护法实施条例》第二十二条第一款规定：“经营者以收取预付款方式\n提供商品或者服务的，应当与消费者订立书面合同，约定商品或者服务的具体内容、价款或者费用、预付款退还方\n式、违约责任等事项。”因此，丁健身馆与消费者约定提供为期半年的健身私教课程服务并收取3000元预付款，可以\n通过订立书面合同的方式约定。\n故正确答案为D。\n【考点】\n其他法律法规","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":true,"links":[{"id":"k-2d60c095aba8bb2e","label":"预付款经营须订立书面合同","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"应当与消费者订立书面合同，约定商品或者服务的具体内容、价款或者费用、预付款退还方\n式、违约责任等事项。","why":"健身服务收取预付款时，书面合同及其应约定的事项构成合规判断依据。","origin":"逐题标记"},{"id":"k-1f8c7e775e5e8d3c","label":"自动续费须在接受服务前和续费前分别显著提醒","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"应当在消费者接受服务前和自动展期、自动续费等日期前，以显著方式提请消费者注意。","why":"订购前的显著提示只是两个法定提醒时点之一。","origin":"逐题标记"},{"id":"k-bfe92274319a826f","label":"免费商品和服务同样适用人身、财产安全保障要求","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"（包括以奖励、赠送、试用等形式向消费者免费提供商品或者服务），应当保证商品或者服务符合保障人身、\n财产安全的要求","why":"免费洗车属于经营者向消费者提供的服务，适用财产安全保障要求。","origin":"逐题标记"},{"id":"k-e37f814fbdab8427","label":"网络销售不得擅自扩大无理由退货例外且须提示消费者确认","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"经营者应当以显著方式对不适用无理由退货的商品进行标注，提示消费者在购买时进行确认","why":"直播中提示尾货或瑕疵，仍须核对商品是否属于适用例外的范围以及消费者是否在购买时确认。","origin":"逐题标记"}]},"国考 2025 地市级 行测#26":{"stem":"纪录片《何以中国》讲述了多元一体中华民族的形成和中华文明创生的故事。下列哪句解说词不可能出现在《秦\n汉》一集中？","options":["他登峰山，攀泰山，上琅琊，经之罘，过东观，临碣石，至会稽，巡行之处皆刊石勒铭","武丁左手扶住卜骨，右手持炭棒，灼烧着钻槽，通红的棒头神秘地闪烁，不久后，裂缝在钻槽边绽开，发出脆响","从长安出发时，车马粼粼百余人，回程路上，只有两人，一十三年间，有利益相诱，有武力相胁，温柔乡、囹圄\n境，却从未丢失身为汉使的旌节，从未磨灭此行的初心","龙首原上，长乐、未央两宫东西并峙，于高处制掣全城。桂宫、北宫、明光宫横列两宫之北"],"answer":"B","analysis":"26. 正确答案：B\n解析：\n\n本题考查人文常识。\nA项正确，秦始皇在统一六国后，为了巩固统治，多次进行巡游。这段话描述的是秦始皇巡游的路线和所到之处刻石\n勒铭的情况，可能出现在《秦汉》一集中。\nB项错误，这段话描述的是武丁进行占卜的情景，武丁是商朝晚期的君主，这与秦汉时期的历史背景不符，不可能出\n现在《秦汉》一集中。\nC项正确，这段话描述的是汉代使节张骞出使西域的艰辛历程，是秦汉时期的重要历史事件，可能出现在《秦汉》一\n集中。\nD项正确，这段话描述的是汉代长安城的宫殿布局，是秦汉时期的重要建筑和文化象征。长乐宫，是在秦离宫兴乐宫\n基础上改建而成的西汉第一座正规宫殿，位于西汉长安城内东南隅，始建于高祖五年。未央宫，西汉帝国的大朝正\n宫，汉朝的政治中心和国家象征，建于汉高祖七年。长乐宫、未央宫和建章宫同为汉代三宫，可能出现在《秦汉》\n一集中。\n本题为选非题，故正确答案为B。\n【考点】\n中国历史","figs":[],"state":"已标记","notes":[],"domains":["历史"],"nature":"知识题","current":false,"links":[{"id":"k-fff7f3fd68d45e66","label":"武丁是商朝晚期君主","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"武丁是商朝晚期的君主","why":"武丁所属的朝代决定了占卜场景的时代归属。","origin":"逐题标记"},{"id":"k-39213f4e56d7d142","label":"秦始皇统一六国后的巡游与刻石","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"秦始皇在统一六国后，为了巩固统治，多次进行巡游。","why":"秦始皇的巡游活动为刊石勒铭的解说词提供时代线索。","origin":"逐题标记"},{"id":"k-84ac23a3ac8d111e","label":"汉代张骞出使西域","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"汉代使节张骞出使西域的艰辛历程","why":"张骞出使西域的史实用于确认汉使经历的时代归属。","origin":"逐题标记"},{"id":"k-a1b35b5e9fe82f88","label":"长乐宫和未央宫属于西汉长安宫殿","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"长乐宫、未央宫和建章宫同为汉代三宫","why":"两座宫殿的朝代归属用于核对长安宫殿布局的解说词。","origin":"逐题标记"}]},"国考 2025 地市级 行测#27":{"stem":"下列物理学家与其提出的著名观点对应错误的是：","options":["麦克斯韦：能量的交换不是连续的，而是以最小的不可分割的单元进行，这些单元被称为“量子”","安培：在原子、分子等物质微粒的内部，存在着一种环形电流-分子电流、使每个微粒成为微小的磁体","牛顿：任何两个物体之间都存在引力，这种力的大小与它们质量的乘积成正比，与它们之间的距离的平方成反比","伽利略：物体的运动并不需要力来维持，运动的物体之所以会停下来，是因为受到了阻力"],"answer":"A","analysis":"27. 正确答案：A\n解析：\n本题考查科技常识。\nA项错误，量子是现代物理的重要概念，即一个物理量如果存在最小的不可分割的基本单位，则这个物理量是量子化\n的，并把最小单位称为量子。该概念最早是由德国物理学家M·普朗克在1900年提出的。他假设黑体辐射中的辐射能\n量是不连续的，只能取能量基本单位的整数倍，从而很好地解释了黑体辐射的实验现象。麦克斯韦的主要贡献包括\n预言了电磁波的存在，建立了麦克斯韦方程组。\nB项正确，分子电流假说是安培提出的电磁学理论，他认为在原子、分子等物质微粒的内部，存在着一种环形电流\n——分子电流，使每个微粒成为微小的磁体，分子的两侧相当于两个磁极。通常情况下磁体分子的分子电流取向是\n杂乱无章的，它们产生的磁场互相抵消，对外不显磁性。当外界磁场作用后，分子电流的取向大致相同，分子间相\n邻的电流作用抵消，而表面部分未抵消，它们的效果显示出宏观磁性。\nC项正确，万有引力定律是艾萨克·牛顿于1687年在《自然哲学的数学原理》上所发表的一种自然规律，表述如下：\n任何两个质点都存在通过其连心线方向上的相互吸引的力。该引力大小与它们质量的乘积成正比，与它们之间的距\n离的平方成反比，与两物体的化学组成和其间介质种类无关。\nD项正确，物体的运动并不需要力来维持，运动的物体之所以会停下来，是因为受到了阻力。这一观点首先由伽利略\n通过实验分析得出的。伽利略通过斜面实验结合推理，证明了力不是维持物体运动的原因，而是改变物体运动状态\n的原因。\n本题为选非题，故正确答案为A。\n【考点】\n物理常识","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"知识题","current":false,"links":[{"id":"k-5c070066cb2636ae","label":"普朗克提出能量量子化假设","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"该概念最早是由德国物理学家M·普朗克在1900年提出的。","why":"量子概念的提出者用于核对题中能量交换以离散单位进行的观点归属。","origin":"逐题标记"},{"id":"k-acc5d65138a2d1be","label":"安培的分子电流假说","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"分子电流假说是安培提出的电磁学理论","why":"分子电流假说用微粒内部的环形电流解释微粒的磁性。","origin":"逐题标记"},{"id":"k-940d02176bad177c","label":"牛顿的万有引力定律","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"这种力的大小与它们质量的乘积成正比，与它们之间的距离的平方成反比","why":"质量乘积与距离平方的比例关系用于辨认牛顿的万有引力定律。","origin":"逐题标记"},{"id":"k-e93b36ad4839b5bc","label":"伽利略关于阻力改变物体运动状态的观点","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"运动的物体之所以会停下来，是因为受到了阻力","why":"用阻力解释物体停止运动是辨认伽利略运动观点的依据。","origin":"逐题标记"}]},"国考 2025 地市级 行测#28":{"stem":"下列人物所说的话与经济有关，其中说法正确的是：","options":["社区居民：我的定期储蓄存款被统计在货币供应量M1中","外资企业CEO：我公司的产值持续增长，为中国GDP提升做出了贡献","留美学生：人民币汇率降低，我的学费也降低了","纳税商户：相比于增值税，营业税的好处是避免重复征税"],"answer":"B","analysis":"28. 正确答案：B\n解析：\n本题考查经济常识。\nA项错误，中国货币供应量的层次划分为：M0=流通中现金；M1=M0+单位活期存款；M2=M1+单位定期存款+个人\n存款+其他存款。社区居民的定期储蓄存款属于个人存款，通常被计入M2。\nB项正确，GDP（国内生产总值）是指一个国家和地区所有常住单位在一定时期内生产活动的全部最终成果。外资企\n业在中国的生产活动产生的价值会计入中国的GDP。\nC项错误，人民币汇率降低，意味着人民币贬值，美元相对升值。对于在美国留学的学生来说，这通常会导致他们需\n要支付更多的人民币来兑换美元以支付学费，而不是降低。\nD项错误，营业税是一种流转税，是在商品销售或劳务提供过程中，针对流转额（如销售额、营业额等）征收的税\n款。而增值税是对商品和服务在流转过程中产生的增值额进行征税。增值税的一个重要特点就是可以避免重复征\n税，因为它只对每个环节的增值部分征税。\n故正确答案为B。\n【考点】\n宏观经济与调控政策","figs":[],"state":"已标记","notes":[],"domains":["经济"],"nature":"知识题","current":false,"links":[{"id":"k-43fbc0d9fd6aabe3","label":"国内生产总值（GDP）","catalog_id":"0daa793a65a0589f","type":"概念与词义","role":"直接考查","field":"answer","quote":"一个国家和地区所有常住单位在一定时期内生产活动的全部最终成果","why":"GDP按常住单位的生产活动统计，在中国生产的外资企业对中国GDP有贡献。","origin":"逐题标记"},{"id":"k-cdbbbc6622e2047b","label":"居民定期储蓄存款计入广义货币M2","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"社区居民的定期储蓄存款属于个人存款，通常被计入M2。","why":"定期储蓄存款的归类用于核对居民所说的货币供应量层次。","origin":"逐题标记"},{"id":"k-a3a53f22cea89a37","label":"人民币对美元贬值提高固定美元支出的人民币成本","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"人民币贬值，美元相对升值","why":"同额美元学费在人民币对美元贬值后需要用更多人民币兑换。","origin":"逐题标记"},{"id":"k-d6f88a4c4154fd57","label":"增值税按各环节增值额计税以避免重复征税","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"它只对每个环节的增值部分征税。","why":"按增值额征税的机制用于区分增值税与按流转额征收的营业税。","origin":"逐题标记"}]},"国考 2025 地市级 行测#29":{"stem":"在关于真菌的科普文章中，下列表述存在错误的是：","options":["古人很早就利用真菌发酵食物，比如利用乳酸菌酿造果酒","人类历史上发现的第一种抗生素来自微型真菌","羊肚菌、松茸等食用真菌味道鲜美，含有丰富的优质蛋白质","植物的根能和真菌形成共生关系，菌丝吸收水分、无机盐等供给植物"],"answer":"A","analysis":"29. 正确答案：A\n\n解析：\n本题考查科技常识。\nA项错误，约9000年前，我们的祖先就会利用微生物将谷物、水果等发酵为含酒精的饮料。1857年，法国微生物学\n家巴斯德通过实验证明，酒精发酵是由活的酵母菌引起的，从而将酵母菌与发酵联系起来。乳酸菌是一类能利用可\n发酵碳水化合物产生大量乳酸的细菌的统称。故古人利用“乳酸菌”酿造果酒说法错误。\nB项正确，抗生素一般指能抑制细菌生长或杀死细菌的一类药物。1928年，英国人弗莱明发现，被污染的金黄色葡萄\n球菌培养基上生长出一种带有毒素的微型真菌——青霉菌，从青霉菌中分离出来的青霉素成为人类历史上发现的第\n一种抗生素。\nC项正确，羊肚菌是食药兼用菌，其香味独特，营养丰富。松茸菌又名松口蘑，是一种珍贵的真菌，具有很高的药用\n食疗作用。两者都是可食用真菌类的食材，都含有十分丰富的蛋白质、氨基酸、维生素和矿物质。\nD项正确，植物的根与真菌之间的共生关系是一种非常重要的生物学现象，这种关系被称为菌根共生。菌根真菌通过\n产生大量菌丝来增加植物根表面积，使其能够更有效地吸收土壤中的水分和营养物质。同时，真菌从植物中获取所\n需的糖类物质。\n本题为选非题，故正确答案为A。\n【考点】\n生物常识","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"知识题","current":false,"links":[{"id":"k-3bf5185b01878be2","label":"酵母菌参与酒精发酵","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"酒精发酵是由活的酵母菌引起的","why":"果酒酿造中的酒精发酵依靠酵母菌。","origin":"逐题标记","originalId":"k-cc656a36cef5cef7"},{"id":"k-f87ac15ace2e47a1","label":"乳酸菌是利用可发酵碳水化合物产乳酸的细菌","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"发酵碳水化合物产生大量乳酸的细菌的统称","why":"微生物类别和主要发酵产物都可用于区分乳酸菌与酵母菌。","origin":"逐题标记"}]},"国考 2025 地市级 行测#30":{"stem":"关于盆地地形，下列说法错误的是：","options":["相比平原，盆地更容易富集油气资源","塔里木盆地是大型封闭性山间盆地","盆地地形在山地、高原、海洋里都有分布","华北渤海湾多分布着岩溶盆地"],"answer":"D","analysis":"30. 正确答案：D\n解析：\n本题考查地理国情。\nA项正确，盆地通常是由地壳运动形成的低洼地带，其四周高、中央低的地形特点使得盆地内部容易形成封闭的构造\n环境，相比平原，更有利于油气资源的聚集。此外，盆地内部的沉积物在地质演化过程中逐渐被深埋地下，在高温\n高压条件下也会转化为油气资源。\nB项正确，塔里木盆地是大型封闭性山间盆地，该处地块基底为古老结晶岩，基底上有约千米厚的富含古生代化石的\n沉积覆盖层，上有较薄的中生代和新生代沉积层。塔里木盆地是我国陆地上最大的含油气盆地，也是全球唯一以超\n深层资源为主的含油气盆地。\nC项正确，盆地是指地球表面相对长时期沉降的区域，因整个地形外观与盆子相似而得名，是基底表面相对于海平面\n长期洼陷或坳陷并接受沉积物沉积充填的地区。陆上的盆地多分布在多山的地表上，在丘陵、山地、高原等都有相\n应的不同构造的盆地。海洋中也有盆地地形，位于大洋中脊与大陆边缘之间，如渤海湾盆地。\nD项错误，岩溶盆地是大型溶蚀洼地，常生成在地壳运动长期相对稳定的地区，代表岩溶发育的后期阶段，多在热带\n气候条件下形成。一般面积较大，长达数十至百余公里。底部平坦，有地表河流通过，堆积有冲积、坡积及溶蚀残\n余的各类沉积物。华北渤海湾的盆地属于断陷盆地。断陷盆地指断块构造中的沉降地块，又称地堑盆地，它的外形\n受断层线控制，多呈狭长条状。\n本题为选非题，故正确答案为D。\n【考点】\n自然常识","figs":[],"state":"已标记","notes":[],"domains":["地理"],"nature":"知识题","current":false,"links":[{"id":"k-3b4beb5eb3517450","label":"华北渤海湾盆地属于断陷盆地","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"华北渤海湾的盆地属于断陷盆地。","why":"渤海湾盆地的实际类型决定该项判断。","origin":"逐题标记"},{"id":"k-d49b09fec2be5e22","label":"岩溶盆地是大型溶蚀洼地","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"岩溶盆地是大型溶蚀洼地","why":"溶蚀成因是识别岩溶盆地的依据。","origin":"逐题标记"},{"id":"k-3621dad2b8564195","label":"断陷盆地是断块构造中的沉降地块","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"断陷盆地指断块构造中的沉降地块，又称地堑盆地","why":"断块沉降说明断陷盆地的构造成因。","origin":"逐题标记"}]},"国考 2025 地市级 行测#31":{"stem":"某博物馆想办一期关于中国自然与人文的地理展览，开设以下几个专题，哪个专题所拟名称不恰当？","options":["长江：稻作文明与鱼米之乡","都江堰：千年水道神韵再现","胡焕庸线：中国的“东与西”","五岳：高山神圣性的代表"],"answer":"B","analysis":"31. 正确答案：B\n解析：\n本题考查地理国情。\nA项正确，‌稻作文明与鱼米之乡形容的是长江流域，尤其是长江中下游地区‌。长江流域依靠其优越的自然条件，孕育\n了东亚稻作文明，为中华民族的繁衍提供了稳定的物质条件。长江流域的河姆渡遗址、城头山遗址等考古发现表\n明，早在1万年前，这里就已经开始了水稻的种植，成为世界稻作文明的发源地之一‌。\nB项错误，继2022年经补水实现百年来首次全线水流贯通后，截至2024年断流百年的京杭大运河已连续三年全线水\n流贯通，再现了壮美运河千年神韵。都江堰是当今世界年代久远、唯一留存、以无坝引水为特征的宏大水利工程，\n建堰两千多年来经久不衰，而且发挥着愈来愈大的效益。‌\nC项正确，“胡焕庸线”是1935年胡焕庸在“中国人口之分布”一文中提出的一条人口地理分界线，即今天的“黑河—腾冲\n线”。‌中国人口分布以“胡焕庸线（黑河—腾冲线）”为界，呈现出极不均衡的特征，东南多、西北少。同时，“胡焕庸\n线（黑河—腾冲线）”也是中国东西分界线。‌\nD项正确，五岳是中华传统文化中五大名山的总称，包括东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山。五\n岳是具有方位代表性的神圣高山，它们是文明核心地域范围的象征，是华夏文明地理构建中极具特色的成果。\n本题为选非题，故正确答案为B。\n\n【考点】\n国情社情","figs":[],"state":"已标记","notes":[],"domains":["地理","文化"],"nature":"知识题","current":false,"links":[{"id":"k-370f8f3b1a5f6d20","label":"都江堰以无坝引水为特征并持续发挥效益","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"以无坝引水为特征的宏大水利工程","why":"都江堰的工程特征及长期运行情况是判断展题是否贴切的依据。","origin":"逐题标记"},{"id":"k-9cd04d0f8130c029","label":"京杭大运河经补水恢复全线水流贯通","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"继2022年经补水实现百年来首次全线水流贯通后","why":"全线复通的经历为解析中“千年神韵再现”的表述提供依据。","origin":"逐题标记"}]},"国考 2025 地市级 行测#32":{"stem":"关于医学检查方法，下列说法错误的是：","options":["做心脏超声检查，无需患者做憋尿、空腹等特殊准备","造影利用了造影剂与人体组织密度的区别","磁共振检查没有放射性，适用于孕妇、婴幼儿等人群","血清检查是判断幽门螺旋杆菌感染的最佳方法"],"answer":"D","analysis":"32. 正确答案：D\n解析：\n本题考查科技常识。\nA项正确，‌做心脏超声检查，无需患者做憋尿、空腹等特殊准备‌。心脏超声检查是一种无创、无辐射的检查方法，主\n要通过超声波来观察心脏的结构和功能。这种检查不需要患者做特殊的准备，如憋尿或空腹等。\nB项正确，造影检查是一种常用的医学检查方法，它利用造影剂与人体组织在X射线下的密度差异来形成对比，从而\n更清晰地显示病变部位。\nC项正确，人们日常生活中常说的磁共振，是指核磁共振成像（MRI），是一种利用磁场和无线电波进行成像的检查\n方法，因此没有放射性。这使得MRI成为孕妇、婴幼儿等对辐射敏感人群的理想选择。\nD项错误，虽然血清检查可以检测幽门螺旋杆菌的抗体，但它并不是判断幽门螺旋杆菌感染的最佳方法。实际上，呼\n气试验（如C-13或C-14尿素呼气试验）被认为是更为准确、便捷且无创的检测方法。呼气试验可以通过检测患者呼\n出的气体中是否含有幽门螺旋杆菌产生的特定标记物来判断感染情况。\n本题为选非题，故正确答案为D。\n【考点】\n生活常识","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"知识题","current":false,"links":[{"id":"k-02af7d6a17a69018","label":"尿素呼气试验适用于判断幽门螺杆菌现症感染","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"answer","quote":"气试验（如C-13或C-14尿素呼气试验）被认为是更为准确、便捷且无创的检测方法。","why":"血清检查检测抗体，尿素呼气试验更适合判断当前是否存在感染。","origin":"逐题标记"}]},"国考 2025 地市级 行测#33":{"stem":"下列与纤维材料有关的说法错误的是：","options":["玻璃纤维性脆，耐磨性较差","碳纤维抗张强度好且没有导电性","竹炭纤维能吸湿和清除异味","大豆蛋白纤维细腻，适用于内衣制造"],"answer":"B","analysis":"33. 正确答案：B\n解析：\n本题考查科技常识。\nA项正确，玻璃纤维的特点是拉伸强度高，但质地较脆，易折断。在受到摩擦等外力作用时，其耐磨性表现相对较\n差，比较容易出现磨损等情况。\nB项错误，碳纤维具有诸多优良性能，比如它的抗张强度非常好，能够承受较大的拉力等外力作用。同时，碳纤维具\n有导电性，可以作为一种功能性材料应用在一些需要导电特性的领域，如电子等领域。\nC项正确，竹炭纤维是一种新型的环保纤维，纤维内部有很多微孔结构，这种结构使得它具备比较强的吸湿能力，能\n够吸收环境中的水分；而且微孔还可以吸附异味分子，从而起到清除异味的效果。\nD项正确，大豆蛋白纤维是一种再生植物蛋白纤维，它的手感细腻、柔软，穿着舒适性高，同时具有良好的吸湿性、\n透气性和亲肤性，非常适合用于内衣等贴身衣物的制造。\n本题为选非题，故正确答案为B。\n【考点】\n生活常识","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"知识题","current":false,"links":[{"id":"k-b09696ec35c567c4","label":"碳纤维具有较高的抗张强度和导电性","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"有导电性，可以作为一种功能性材料","why":"碳纤维的导电性是区分正确与错误表述的关键材料性能。","origin":"逐题标记"}]},"国考 2025 地市级 行测#34":{"stem":"下列《三国演义》中的回目，按照先后顺序排列正确的是：\n①宴长江曹操赋诗，锁战船北军用武\n②战官渡本初败绩，劫乌巢孟德烧粮\n③刘先主遗诏托孤儿，诸葛亮安居平五路\n④王司徒巧使连环计，董太师大闹凤仪亭","options":["①③④②","③②④①","②①④③","④②①③"],"answer":"D","analysis":"34. 正确答案：D\n解析：\n本题考查人文常识。\n①“宴长江曹操赋诗，锁战船北军用武”出自《三国演义》第48回，主要内容是曹操在长江宴请自己手下时作了一首\n《短歌行》，赤壁之战面对北方军队不擅长水战，曹操在庞统的建议下，将战船用铁锁连接，准备开战。\n②“战官渡本初败绩，劫乌巢孟德烧粮”出自《三国演义》第30回，主要内容是曹操与袁绍的官渡大战中，袁绍大败。\n曹操在劫了乌巢后将其烧毁，断了袁绍的粮草。\n③“刘先主遗诏托孤儿，诸葛亮安居平五路”出自《三国演义》第85回，主要内容是刘备在白帝城永安宫病重，召诸葛\n亮等人托付后事。刘备病逝，诸葛亮立年幼的刘禅为帝，曹丕乘机派五路大军攻击西蜀，诸葛亮运筹帷幄智平五\n路。\n④“王司徒巧使连环计，董太师大闹凤仪亭”出自《三国演义》第8回，主要内容是司徒王允使用了连环计，将貂蝉许\n配给吕布，最后又将她献给了董卓。董卓在听闻吕布约会貂蝉后，大闹了凤仪亭。\n按照先后顺序排列为④②①③。\n故正确答案为D。\n【考点】\n文学常识","figs":[],"state":"已标记","notes":[],"domains":["文化"],"nature":"知识题","current":false,"links":[{"id":"k-68c84a4a242d61cd","label":"《三国演义》第八回写王允施连环计与董卓闹凤仪亭","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"“王司徒巧使连环计，董太师大闹凤仪亭”出自《三国演义》第8回","why":"回次可用于定位连环计与凤仪亭情节在小说中的位置。","origin":"逐题标记"},{"id":"k-a99120f810cc6f70","label":"《三国演义》第三十回写官渡败袁绍与曹操烧乌巢","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"“战官渡本初败绩，劫乌巢孟德烧粮”出自《三国演义》第30回","why":"回次可用于定位官渡与乌巢情节在小说中的位置。","origin":"逐题标记"},{"id":"k-b8a689cf7a3cba6f","label":"《三国演义》第四十八回写曹操长江宴饮赋诗与铁锁连船","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"“宴长江曹操赋诗，锁战船北军用武”出自《三国演义》第48回","why":"回次可用于定位赤壁之战前的宴饮与连船情节。","origin":"逐题标记"},{"id":"k-7e1daa096b6aefd3","label":"《三国演义》第八十五回写刘备托孤与诸葛亮平五路","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"“刘先主遗诏托孤儿，诸葛亮安居平五路”出自《三国演义》第85回","why":"回次可用于定位托孤与平五路情节在小说中的位置。","origin":"逐题标记"}]},"国考 2025 地市级 行测#35":{"stem":"下列与船只行驶有关的说法错误的是：","options":["皮筏在顺流而下的过程中动能转化为重力势能","船舵利用杠杆原理改变行船的方向","使用船桨划船前进时利用了力的相互作用","帆船实现逆风行驶是利用了伯努利原理"],"answer":"A","analysis":"35. 正确答案：A\n解析：\n本题考查科技常识。\n\nA项错误，动能是指物体因运动而具有的能。质量相同的物体，运动的速度越大，它的动能越大；运动速度相同的物\n体质量越大，它的动能也越大。重力势能是指物体由于受到重力并处在一定高度时所具有的能。物体质量越大，位\n置越高，具有的重力势能就越大。皮筏顺流而下的过程中，重力势能随着高度不断减小而减小，动能随着运动速度\n不断增大而增大，重力势能转化为动能。\nB项正确，船舵是用来操纵和控制船舶航向的装置，一般位于船尾，又称船尾舵。船舵通常由舵叶和舵杆组成，利用\n阿基米德杠杆原理以及作用力与反作用力原理，通过改变流经船体或机身的流体的方向来控制船的行驶方向。\nC项正确，船桨是一种上端为圆杆，下端为板状的划水工具，根据鱼的胸鳍和腹鳍而发明。船桨的工作原理主要是利\n用了牛顿第三定律，通过水波的反作用力使船前进。向后划船桨时，人通过船桨给了水一个向后的作用力，与此同\n时，水也给了船桨一个向前的作用力，由此使人向前移动。因此，使用船桨划船前进时利用了力的相互作用。\nD项正确，伯努利原理是指在流体中，如果流体速度小，压强就大；如果流体速度大，压强就小。帆船在航行过程中\n遇到逆风情况时，可以通过调整船帆，使得两侧的空气流速不同，从而产生压力差，使得帆船逆风行驶。\n本题为选非题，故正确答案为A。\n【考点】\n物理常识","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"综合题","current":false,"links":[{"id":"k-f5db52e381dadaae","label":"重力势能随高度降低而减小，动能随速度增大而增大","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"重力势能随着高度不断减小而减小，动能随着运动速度","why":"题设皮筏下行且加速，重力势能减小、动能增大，可据此判断能量转化方向。","origin":"逐题标记"},{"id":"s-7dda77370e030ac7","label":"根据高度和速度变化判断机械能转化方向","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"皮筏在顺流而下的过程中动能转化为重力势能","why":"先判断高度与速度如何变化，再判断哪一种机械能减少、哪一种增加。","origin":"逐题标记"}]},"国考 2025 地市级 行测#36":{"stem":"我们想问题、作决策、办事情，首先要考虑人口基数问题，考虑我国城乡区域发展水平差异大等实际，既不能\n  ，也不能因循守旧，要保持历史耐心，坚持稳中求进、循序渐进、持续推进。\n填入画横线部分最恰当的一项是：","options":["朝令夕改","寅吃卯粮","好高骛远","一厢情愿"],"answer":"C","analysis":"36. 正确答案：C\n解析：\n横线处所填成语搭配“想问题、作决策、办事情”，且根据“首先要考虑人口基数问题，考虑我国城乡区域发展水平差\n异大等实际”以及“要保持历史耐心，坚持稳中求进、循序渐进、持续推进”可知，横线处应体现出“想问题、作决策、\n办事情”不能偏离实际，而应脚踏实地之意。C项“好高骛远”指脱离实际去追求过高的、难以实现的目标，符合文意，\n当选。A项“朝令夕改”形容主张或办法经常改变，一会儿一个样；B项“寅吃卯粮”比喻入不敷出，预先支用未来的收\n入。二者均与“不能偏离实际”的语义无关，排除。D项“一厢情愿”指处理彼此有关的事情时，只管自己愿意，不管对\n方愿意不愿意，或指办事时不考虑客观实际情况，全从主观意愿出发，与前文的“想问题”搭配不当，排除。\n故正确答案为C。\n【文段出处】人民网《全面推进城乡、区域协调发展》\n【考点】\n成语填空,词的辨析-搭配对象,关联关系-并列关系【逻辑填空】","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-2808897dc82c9bc7","label":"“好高骛远”的含义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“好高骛远”指脱离实际去追求过高的、难以实现的目标","why":"脱离实际追求过高目标的含义，与考虑现实差异、循序推进的要求相对应。","origin":"逐题标记","originalId":"k-66eaed82e2a69ef8"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"也不能因循守旧，要保持历史耐心，坚持稳中求进、循序渐进、持续推进。","why":"由并列结构和后文的推进节奏，推断首空所指的另一种偏失。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2025 地市级 行测#37":{"stem":"《营造法式》刊行之后，两浙一带的建筑技术借助官方的推广完全融入了中国古典木构建筑技术的主流。以抬梁\n式为梁柱结构，屋面重量通过椽、檩、梁、斗栱、柱传递至基础的方案，形成此后中国官式建筑     的发展路\n\n径。这种结构开间大，立柱少，气势恢宏，可细分为殿堂式与厅堂式，满足不同礼制等级的需要。\n填入画横线部分最恰当的一项是：","options":["源远流长","标新立异","一枝独秀","一以贯之"],"answer":"D","analysis":"37. 正确答案：D\n解析：\n横线处所填词语搭配“发展路径”。根据“完全融入了中国古典木构建筑技术的主流······形成此后中国官式建筑······的\n发展路径”可知，横线处应体现此后中国官式建筑按照这一路径继续发展之意。D项“一以贯之”指用一种思想理论贯穿\n于始终，置于此处可体现发展路径一直延续之意，符合文意，当选。A项“源远流长”比喻历史悠久，根底深厚，常搭\n配“历史”，与“发展路径”搭配不当，排除。B项“标新立异”多形容敢于改革创新或提出新奇的主张，表示与一般不同，\n也指为了显示自己而故意另搞一套，文段既未体现“创新”，也未体现“故意另搞一套”，不符合文意，排除。C项“一枝\n独秀”形容在同类人或同类事物中出类拔萃，文段并未体现“出类拔萃”之意，不符合文意，排除。\n故正确答案为D。\n【文段出处】吴文化博物馆《百工有业｜从紫禁之巅到纽约苏园——从古代走入现代的香山帮》\n【考点】\n成语填空,词的辨析-搭配对象,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-3a908307b4d1979e","label":"“一以贯之”表示贯穿始终","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"置于此处可体现发展路径一直延续之意","why":"需辨认“一以贯之”所表达的前后延续，并将这一含义用在发展路径上。","origin":"逐题标记","originalId":"k-43953921c21216e5"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"形成此后中国官式建筑","why":"把“此后”与前文技术融入主流相联系，再检验成语能否修饰“发展路径”。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2025 地市级 行测#38":{"stem":"兔和羚羊等食草动物获取食物时动作敏捷，牛类有瘤胃可以囤积食物，到安全环境中再慢慢消化。大熊猫既没有\n这样的敏捷度，也没有瘤胃结构，所以“      ”，选择了其他动物不吃的食物种类，也出现了一些与进食、消化有\n关的基因突变，形成了独特的食性——将箭竹作为主食。\n填入画横线部分最恰当的一项是：","options":["扬长避短","顺水推舟","因陋就简","另辟蹊径"],"answer":"D","analysis":"38. 正确答案：D\n解析：\n根据“选择了其他动物不吃的食物种类”“形成了独特的食性”可知，横线处所填成语应表达大熊猫选择与其他动物不同\n的食物种类之意。D项“另辟蹊径”比喻另创一种新风格或另找一个新途径、新方法，符合文意，当选。A项“扬长避\n短”指发扬优点或发挥有利条件，克服缺点或回避不利条件；B项“顺水推舟”比喻顺着某个趋势办事或顺着某种方式说\n话；C项“因陋就简”多指就着原有的简陋的条件办事。三项均与文意不符，排除。\n故正确答案为D。\n【文段出处】上海科普网《“滚滚”是怎么把自己熬成“活化石”的？丨爱科学的十万个理由》\n【考点】\n成语填空,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-idiom","label":"“另辟蹊径”的含义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“另辟蹊径”比喻另创一种新风格或另找一个新途径、新方法","why":"需识别成语中另找途径的含义，才能对应大熊猫选择不同食物的做法。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"选择了其他动物不吃的食物种类","why":"用空后对取食选择的具体说明，确定空缺成语应概括的做法。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2025 地市级 行测#39":{"stem":"人才培养是循序渐进的过程，需认识、   、尊重人才成长规律，坚持“严管”和“厚爱”相结合。人才干事创业中\n难免有失误，如果培养者因为害怕犯错而顾虑重重、      ，则违背了人才培育的初衷。所以，要为人才“松绑”，\n建立健全正向激励和容错纠错机制，为人才成长创造宽容的环境。\n依次填入画横线部分最恰当的一项是：","options":["把握 因噎废食","顺应 矫枉过正","运用 半途而废","归纳 瞻前顾后"],"answer":"A","analysis":"39. 正确答案：A\n解析：\n本题可从第二空入手。“、”连接的前后内容构成并列关系，且根据前文“如果培养者因为害怕犯错而顾虑重重”可知，\n横线处所填成语应体现培养者因为害怕犯错而有所顾虑。A项“因噎废食”比喻因为怕出问题，索性不干；D项“瞻前顾\n后”形容顾虑太多，犹豫不决。两项均符合文意，保留。B项“矫枉过正”比喻纠正偏差做得过了头，文段中为“害怕犯\n错”而非“纠正错误”，不符合文意，排除。C项“半途而废”指半路上终止，比喻做事情有始无终，不能体现出害怕犯错\n而有所顾虑的意思，排除。\n第一空，搭配“规律”。A项“把握”指抓住，与“规律”搭配恰当，且“认识、把握、尊重人才成长规律”可以体现出三词并\n列的先后顺序，当选。D项“归纳”指归拢并使有条理，“规律”本身就是归纳的结果，“归纳”与“规律”搭配不当，排除。\n故正确答案为A。\n【文段出处】人民论坛网《人民论坛网评|人才培育当多管齐下》\n【考点】\n混搭填空,词的辨析-搭配对象,关联关系-并列关系【逻辑填空】,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-f13f01ac650b3375","label":"“把握规律”的搭配及含义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“把握”指抓住，与“规律”搭配恰当","why":"需理解“把握”与“规律”的搭配，并辨认该动作在认识和尊重规律之间的语义位置。","origin":"逐题标记"},{"id":"k-198741262bdda74e","label":"“因噎废食”的含义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“因噎废食”比喻因为怕出问题，索性不干","why":"需辨认该成语所含的因担心出问题而放弃行动的意思。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"“认识、把握、尊重人才成长规律”可以体现出三词并列的先后顺序","why":"结合怕犯错的因果线索和第一空的动宾搭配，交叉核对同一选项中的两个词。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2025 地市级 行测#40":{"stem":"党的规模大了，一些人容易出现搞小山头、小圈子、小团伙现象，容易出现     、自行其是问题，破坏党的\n团结统一，影响党的凝聚力战斗力。随着改革开放逐步深入，社会利益多元化、思想多样化也深刻影响到党员干部\n的观念和行为。我们必须在重大问题、严峻形势面前始终心往一处想、劲往一处使，做到凝心聚力、        ，确保\n全党紧密团结在党中央周围，步调一致向前进。\n依次填入画横线部分最恰当的一项是：","options":["分崩离析 群策群力","南辕北辙 和衷共济","尾大不掉 众志成城","阳奉阴违 同仇敌忾"],"answer":"C","analysis":"40. 正确答案：C\n解析：\n第一空，顿号引导并列关系，横线处应与“自行其是”语义接近，且前文指出“党的规模大了，一些人容易出现搞小山\n头、小圈子、小团伙现象”，后文论述“破坏党的团结统一，影响党的凝聚力战斗力”，故横线处所填成语应体现由于\n党的规模扩大而出现不团结的现象。C项“尾大不掉”比喻机构下强上弱，或组织庞大、涣散，指挥不灵，D项“阳奉阴\n违”指表面上遵从，暗地里违背，二者均会破坏团结，影响党的凝聚力战斗力，保留。A项“分崩离析”形容国家或集团\n等分裂瓦解，文段只是论述党内出现不团结现象，并非瓦解，语义程度过重，排除。B项“南辕北辙”指想往南而车子\n却向北行，比喻行动和目的正好相反，文段未提及“行动”“目的”，排除。\n第二空，根据横线前的“、”可知，横线处所填成语应与“凝心聚力”语义相近。“凝心聚力”指将大家的想法、思路和力\n量凝聚在一起，共同为某一件事情而努力和奋斗，强调团结。C项“众志成城”比喻大家团结一致，就能克服困难，得\n到成功，与文意相符，当选。D项“同仇敌忾”指全体一致痛恨敌人，文段强调全体党员团结起来去解决问题，而非痛\n恨敌人，排除。\n故正确答案为C。\n【文段出处】中国纪检监察报《加强政治监督 促进全党始终统一思想统一意志统一行动》\n【考点】\n成语填空,词的辨析-程度轻重,关联关系-并列关系【逻辑填空】,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-29fd45aea13b8de7","label":"“尾大不掉”的含义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“尾大不掉”比喻机构下强上弱，或组织庞大、涣散，指挥不灵","why":"成语所含的组织庞大、指挥不灵之意，契合规模扩大后各自行动的语境。","origin":"逐题标记","originalId":"k-62a363b4472f05ea"},{"id":"k-08e73b92922188a7","label":"“众志成城”与“同仇敌忾”的词义辨析","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“众志成城”比喻大家团结一致，就能克服困难","why":"第二空需区分团结克难和共同痛恨敌人两种语义，才能准确呼应“凝心聚力”。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"心往一处想、劲往一处使，做到凝心聚力","why":"结合两处顿号的并列关系，分别检验首空与“自行其是”、次空与“凝心聚力”的语义呼应。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2025 地市级 行测#41":{"stem":"能量的产生和使用不一定   。可再生能源发电如风力发电、太阳能发电等，会因为天气、季节、地理位置的不\n同，存在不同时间尺度的间歇性，而用电需求也有      ，时多时少。低成本大规模的储能系统可以突破可再生能\n源“即发即用、不能存储”的瓶颈，显著提高风、光等可再生能源的消纳水平。\n依次填入画横线部分最恰当的一项是：","options":["同步 波动性","协调 机动性","平衡 规律性","匹配 差异性"],"answer":"A","analysis":"41. 正确答案：A\n解析：\n第一空，根据“可再生能源发电······存在不同时间尺度的间歇性，而用电需求也······时多时少”可知，横线处所填词语\n应体现能量的产生和使用在时间上存在不一致性。A项“同步”泛指互相关联的事物在进行速度上协调一致，D项“匹\n配”指两个或多个事物在某些方面相适应、相符合或相配合，二者均符合文意，保留。B项“协调”指配合得适当，C\n项“平衡”指对立的各方面在质量或数量上相等或相抵，二者均无法体现出在时间上的不一致性，排除。\n第二空，根据“时多时少”可知，横线处所填词语应体现用电需求不稳定、存在变化的意思。A项“波动性”指某事物在\n一定时间或范围内不稳定，存在一定变化的特性，符合文意，当选。D项“差异性”指与其他事物相比有差别或不同点\n的特性，侧重不同主体之间的差别，不能用来表示“用电需求”这一主体的特征，排除。\n故正确答案为A。\n【文段出处】人民日报《新型储能技术助力高质量发展（开卷知新）》\n【考点】\n实词填空,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-14732ea9142d41d2","label":"“同步”的含义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“同步”泛指互相关联的事物在进行速度上协调一致","why":"需识别“同步”所指的时间进程一致，才能将其与发电和用电的时序联系起来。","origin":"逐题标记","originalId":"k-75abee92005a4e3d"},{"id":"k-1a68a8346ca40803","label":"“波动性”与“差异性”的词义辨析","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“波动性”指某事物在\n一定时间或范围内不稳定，存在一定变化的特性","why":"第二空需区分同一需求随时间起伏和不同对象之间存在差别。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"存在不同时间尺度的间歇性，而用电需求也有      ，时多时少。","why":"用发电间歇性推断第一空的时间关系，用“时多时少”核对第二空的语义。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2025 地市级 行测#42":{"stem":"各国正逐步形成以无人机、巡航导弹、弹道导弹、轰炸机等为主力的高效空袭体系，可以实现对目标空域的饱和\n袭击。这让只能命中单一目标的防空导弹陷入      的境地。面对复杂多样的战场威胁，防空导弹不再      ，而\n是“攥指成拳”，朝着防空导弹系统升级转变。\n依次填入画横线部分最恰当的一项是：","options":["腹背受敌 各自为战","鞭长莫及 形单影只","捉襟见肘 故步自封","孤掌难鸣 单打独斗"],"answer":"D","analysis":"42. 正确答案：D\n解析：\n第一空，根据“各国正逐步······可以实现对目标空域的饱和袭击”可知，只能命中单一目标的防空导弹能力不足。C\n项“捉襟见肘”指顾此失彼，穷于应付，D项“孤掌难鸣”指孤立无助，难以成事，二者均能体现只能命中单一目标的防\n空导弹能力不足，无法应付复杂的战场威胁，保留。A项“腹背受敌”指前后受到敌人的攻击，文段并未体现防空导弹\n遭受夹击之意，与文意不符，排除。B项“鞭长莫及”比喻因距离太远而无能为力，文段并未表达防空导弹因距离远而\n无能为力之意，排除。\n\n第二空，根据“不再······而是······”可知，横线处所填成语与形象表达“攥指成拳”语义相反。“攥指成拳”指手指头攥紧\n才能变成拳头，才能有力打击，比喻心往一处想，力往一处使，事情才能办成，故横线处应体现不团结、单独作战\n之意。D项“单打独斗”指独自一个人去打斗、做事，符合文意，当选。C项“故步自封”指因循守旧，安于现状，不求创\n新进取，与文意不符，排除。\n故正确答案为D。\n【文段出处】中国军网-解放军报《防空导弹的进阶之路丨从单打独斗到攥指成拳》\n【考点】\n成语填空,关联关系-并列关系【逻辑填空】,形象表达,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-ca3e67f6a6101d74","label":"“孤掌难鸣”的含义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“孤掌难鸣”指孤立无助，难以成事","why":"需辨认该成语所含的独力难以应付之意，以概括第一空的困境。","origin":"逐题标记"},{"id":"k-e00dbc5ed6270f33","label":"“单打独斗”的含义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“单打独斗”指独自一个人去打斗、做事","why":"需识别独自行动的含义，才能与后文集中力量的比喻形成对照。","origin":"逐题标记","originalId":"k-f6c870d92de9c5ea"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"而\n是“攥指成拳”","why":"借助“不再……而是……”的句式和后项比喻反推第二空，再回看第一空是否与独力难支的处境相符。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2025 地市级 行测#43":{"stem":"推进中国式现代化是一个探索性事业，还有许多未知领域，需要我们在实践中去大胆探索，通过改革创新来推动\n事业发展，决不能      、守株待兔。各地区各部门要结合各自具体实际开拓创新，特别是在前沿实践、未知领\n域，鼓励大胆探索、      ，寻求有效解决新矛盾新问题的思路和办法，努力创造可复制、可推广的新鲜经验。\n\n依次填入画横线部分最恰当的一项是：","options":["刻舟求剑 敢为人先","坐井观天 踔厉奋发","望梅止渴 推陈出新","画地为牢 大展拳脚"],"answer":"A","analysis":"43. 正确答案：A\n解析：\n第一空，根据“需要······决不能······”可知，横线处应与前文构成反义并列关系，体现不改革创新、守旧死板之意。A\n项“刻舟求剑”比喻办事刻板，拘泥成例而不知变通；D项“画地为牢”比喻只准在指定范围内活动，可形容思想受限。\n两项均符合文意，保留。B项“坐井观天”比喻眼界狭小，看到的有限；C项“望梅止渴”比喻用空想或假象安慰自己。两\n项均与文意不符，排除。\n第二空，根据“寻求有效解决新矛盾新问题的思路和办法，努力创造可复制、可推广的新鲜经验”可知，横线处所填成\n语应体现要先人一步、创造新经验之意。A项“敢为人先”指敢于做别人没有做过的事情，符合文意，当选。D项“大展\n拳脚”指充分施展本领，与文意不符，排除。\n故正确答案为A。\n【文段出处】求是《推进中国式现代化需要处理好若干重大关系》\n【考点】\n成语填空,关联关系-并列关系【逻辑填空】,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-471105f275ef1a4a","label":"“刻舟求剑”的含义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“刻舟求剑”比喻办事刻板，拘泥成例而不知变通","why":"需辨认成语所指的拘泥成例，以对应文中明确否定的守旧做法。","origin":"逐题标记"},{"id":"k-833d3299afad1d5e","label":"“敢为人先”的含义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“敢为人先”指敢于做别人没有做过的事情","why":"需辨认成语所强调的率先尝试，以呼应在未知领域探索和创造新经验。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"寻求有效解决新矛盾新问题的思路和办法，努力创造可复制、可推广的新鲜经验。","why":"用“决不能”和并列的“守株待兔”确定首空的语义方向，再用尾句的新问题和新经验限定第二空。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2025 地市级 行测#44":{"stem":"降水总量增多、变率减弱可能是最让人      的变化型，这意味着未来的雨水不仅丰盈，还会以“润物细无声”的\n方式滋养大地。遗憾的是，全球几乎没有哪个地区的降水类型属于这一变化型。我国大部分地区的降水变化型属\n于“更湿润且波动更大”，意味着降水的       将增强，这须引起广泛重视。\n依次填入画横线部分最恰当的一项是：","options":["望眼欲穿 偶然性","翘首以盼 持续性","津津乐道 集中性","喜闻乐见 极端性"],"answer":"D","analysis":"44. 正确答案：D\n解析：\n第一空，根据后文“这意味着未来的雨水不仅丰盈，还会以‘润物细无声’的方式滋养大地”所体现的积极感情色彩可\n知，横线处所填成语应体现人们对于“降水总量增多、变率减弱”这种变化型持一种喜欢、欢迎的态度，D项“喜闻乐\n见”形容很受欢迎，符合文意，保留。A项“望眼欲穿”指眼睛都要望穿了，形容盼望殷切，B项“翘首以盼”比喻人们期\n待分别久了的亲人、朋友来到自己身边的急切心情，置于此处均程度过重，排除；C项“津津乐道”指很有兴趣地谈\n论，无法体现人们对于这一变化型的态度，与文意不符，排除。\n第二空，代入验证，D项“极端性”指某种绝对的、偏激的特性，可以和“更湿润且波动更大”“这须引起广泛重视”构成对\n应，当选。\n故正确答案为D。\n【文段出处】科普中国《“一天下完一年的雨”，这事儿未来可能更频繁》\n【考点】\n混搭填空,词的辨析-感情色彩,词的辨析-程度轻重,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-39c3db152faf2d50","label":"“喜闻乐见”表示喜欢、欢迎","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"见”形容很受欢迎","why":"第一空需要区分欢迎、殷切盼望和有兴趣谈论。","origin":"逐题标记"},{"id":"k-4905477d535c4dc7","label":"“极端性”表示趋于极端的特性","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“极端性”指某种绝对的、偏激的特性","why":"第二空需要辨认能与波动增大及风险提醒对应的词义。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"更湿润且波动更大","why":"由丰盈且滋养大地推断第一空的态度，再用波动增大和风险提醒核验第二空。","origin":"逐题标记","originalId":"s-9c1efa980c7aa095"}]},"国考 2025 地市级 行测#45":{"stem":"当前，改革发展任务繁重，需要各级各部门和广大干部高质高效地完成各项任务，才能在日趋激烈的发展竞争中\n赢得   。而处理日常纷繁复杂的工作，就如同“十个指头弹钢琴”，需要合理分配力量和节奏。一味强求自加压力，\n势必使某个或多个指头的力量受到影响，导致工作         ，工作效能不理想也就在意料之中了。\n依次填入画横线部分最恰当的一项是：","options":["主动 左支右绌","优势 进退维谷","认可 手忙脚乱","先机 拖泥带水"],"answer":"A","analysis":"45. 正确答案：A\n解析：\n第一空，根据“需要各级各部门和广大干部高质高效地完成各项任务”可知，横线处要体现在激烈的竞争中占据有利地\n位之意，A项“主动”指能够带来有利局面，使事情按照自己的意图进行，B项“优势”指能超过对方的有利形势，D项“先\n机”指决定未来形势的时机，均符合文意，保留。C项“认可”指承认，许可，与文意无关，排除。\n第二空，根据“处理日常纷繁复杂的工作，就如同‘十个指头弹钢琴’，需要合理分配力量和节奏”“工作效能不理想也就\n在意料之中了”可知，横线处表达对于纷繁复杂的工作无法全面顾及到之意，A项“左支右绌”指力量不足，应付了这方\n面，那方面又出了问题，符合文意，当选。B项“进退维谷”指无论是进还是退，都是处在困境之中，形容处境艰难，\n进退两难，而文段侧重强调无法全面顾及到之意，与文意不符，排除；D项“拖泥带水”比喻办事拖沓不爽快或语言不\n简明扼要，与文意不符，排除。\n故正确答案为A。\n【文段出处】云岭先锋网《自加压力要“量力而行”》\n【考点】\n混搭填空,关联关系-因果关系【逻辑填空】,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-64f12b8d4e6dffd3","label":"“左支右绌”形容力量不足、顾此失彼","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"指力量不足，应付了这方\n面，那方面又出了问题","why":"第二空须辨明力量分配失衡造成的顾此失彼。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"需要合理分配力量和节奏","why":"用弹钢琴的比喻推断加压会导致工作难以兼顾，再核验第一空是否表示在竞争中获得有利地位。","origin":"逐题标记","originalId":"s-9c1efa980c7aa095"}]},"国考 2025 地市级 行测#46":{"stem":"面对企业，干部洁身自好只是最低要求，担当作为才是责任所系。民营企业所遇到的困难和问题仍不少，干部不\n仅要守住廉洁底线，更应主动为企业         。干部同企业家打交道要把握分寸，并不意味着可以对企业家的正当要\n求    ，对企业的合法权益不予保护，而是要积极主动为企业服务。\n依次填入画横线部分最恰当的一项是：","options":["雪中送炭 充耳不闻","保驾护航 退避三舍","嘘寒问暖 熟视无睹","排忧解难 置若罔闻"],"answer":"D","analysis":"46. 正确答案：D\n解析：\n\n本题可从第二空入手，根据“并不意味着······而是要······”可知，横线处与“积极主动为企业服务”语义相反，应体现对\n企业家的正当要求忽视、不重视之意。A项“充耳不闻”指塞住耳朵不听，形容不愿听取别人的意见，C项“熟视无睹”指\n虽然经常看见，还跟没看见一样，形容对应该关心的事物漠不关心，D项“置若罔闻”指放在一边不管，好像没听到一\n样，形容不重视、不关心，均符合文意，保留。B项“退避三舍”泛指对人让步，不与相争，强调主动退让回避，避免\n冲突，与文意不符，排除。\n第一空，根据前文“民营企业所遇到的困难和问题仍不少”，后文“要积极主动为企业服务”可知，横线处应体现干部要\n主动帮助企业解决困难、问题。D项“排忧解难”指排除忧虑，解除危难，与文意相符，当选。A项“雪中送炭”比喻在别\n人急需的时候给以帮助，虽能够体现解决问题之意，但文段强调干部要积极主动作为，而非企业“急需”时才给予帮\n助，排除；C项“嘘寒问暖”形容对别人的生活十分关切，无法体现解决困难、问题之意，且常表述为“对······嘘寒问\n暖”，一般不与“为”搭配，排除。\n故正确答案为D。\n【文段出处】人民网《鼓励干部为企业排忧解难》\n【考点】\n成语填空,关联关系-并列关系【逻辑填空】,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-c8f9c64f84c283a7","label":"“排忧解难”表示排除忧虑、解除困难","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“排忧解难”指排除忧虑，解除危难","why":"第一空要求区分主动解决困难、急需时援助和表达关切。","origin":"逐题标记"},{"id":"k-f754640e56db123a","label":"“置若罔闻”形容对听到的事不理会、不关心","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"样，形容不重视、不关心","why":"第二空要求识别表示忽视正当要求的词义。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"而是要积极主动为企业服务","why":"用转折后的正面要求推断第二空，再根据企业遇到的困难检验第一空。","origin":"逐题标记","originalId":"s-9c1efa980c7aa095"}]},"国考 2025 地市级 行测#47":{"stem":"刺沙蓬也叫风滚草，一株可以携带约20万粒种子。在随风滚动时，       的翻滚会帮助它抖落出种子，散落在地\n面上，时机成熟就会长成新的刺沙蓬，如此         。并且，它们对水分的需求量较少，对盐度有较好的耐受性，在\n海滩、草原和戈壁沙漠中都能      生长。\n依次填入画横线部分最恰当的一项是：","options":["连续 环环相扣 广泛","突然 周而复始 野蛮","剧烈 循环往复 肆意","急促 绵绵不绝 疯狂"],"answer":"C","analysis":"47. 正确答案：C\n解析：\n第一空，搭配“翻滚”，且根据“在随风滚动时”可知，横线处应体现风滚草随风翻滚时的状态，A项“连续”指一次连一\n次，C项“剧烈”指猛烈，二者均可体现风滚草随风翻滚时的状态，符合文意，保留。B项“突然”指在短促的时间里发\n生，出乎意外，D项“急促”指快而短促，文段并未体现风滚草随风翻滚是短时间内突然发生的，均与文意不符，排\n除。\n第二空，根据“在随风滚动时······的翻滚会帮助它抖落出种子，散落在地面上，时机成熟就会长成新的刺沙蓬”可知，\n刺沙蓬随风散落种子，种子成长为新的刺沙蓬，而后新的刺沙蓬会继续随风散落种子，横线处应体现循环的语义，C\n项“循环往复”形容事物周而复始，来回往复，符合文意，保留。A项“环环相扣”指一环扣一环，比喻若干事物之间密\n切相关，也形容运作步骤安排得紧凑而有序，未能体现刺沙蓬周而复始的循环状态，与文意不符，排除。\n第三空，代入验证。根据“它们对水分的需求量较少，对盐度有较好的耐受性”可知，由于刺沙蓬对环境条件要求较\n低，所以刺沙蓬在各种环境中都可以很好地生长，C项“肆意”指不顾一切由着自己的性子，当修饰植物时则强调植物\n生命力旺盛，生长茂盛，符合文意，当选。\n故正确答案为C。\n【文段出处】万物杂志《民众噩梦、让美国进入紧急状态的风滚草，怎么就被我们当成了美食？》\n【考点】\n混搭填空,词的辨析-词义侧重,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-bf56acfe0eb992e2","label":"“循环往复”表示过程反复重现","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“循环往复”形容事物周而复始，来回往复","why":"第二空需要区分同一过程反复重现与各环节紧密相连。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"时机成熟就会长成新的刺沙蓬","why":"从散种到长成新株判断繁殖过程能够重复，再核验翻滚和生长的搭配。","origin":"逐题标记","originalId":"s-9c1efa980c7aa095"}]},"国考 2025 地市级 行测#48":{"stem":"借鉴各地耕保的好经验、好做法，可以少走弯路，但不可将借鉴当作       。比如，平原地区的耕地恢复方法不一\n定适合山区，粮食主产区与主销区可能         。有些经验做法依托的是当地经济基础和民风社情，外地可能“借”不\n来也“学”不好，盲目推广可能导致      、劳民伤财。\n依次填入画横线部分最恰当的一项是：","options":["套用 背道而驰 功亏一篑","照搬 大相径庭 水土不服","复制 截然不同 物极必反","效仿 天差地别 弄巧成拙"],"answer":"B","analysis":"48. 正确答案：B\n解析：\n本题可从第三空入手。根据横线后的“、”可知，所填成语与“劳民伤财”构成近义并列。“劳民伤财”指既使人民劳苦，\n又耗费钱财，体现了“盲目推广”带来的消极影响。同时结合横线前的“有些经验做法依托的是当地经济基础和民风社\n情，外地可能‘借’不来也‘学’不好”可知，横线处需体现盲目推广不适合本地的经验做法可能会导致失败之意。B项“水\n土不服”指对一个地方的气候条件或饮食习惯等不能适应，置于此处可表达盲目照抄其他地区的耕保经验可能不适用\n于本地实际情况之意，符合文意，保留。A项“功亏一篑”比喻做事因差最后一点努力而未能完成，文段并未介绍地方\n耕保进行到什么程度，与文意不符，排除。C项“物极必反”指事物发展到极端，就会向相反的方面转化，文段并未表\n达“事物发展到极端”之意，排除。D项“弄巧成拙”指本想耍弄聪明，结果做了蠢事，或把事情弄糟，文段只是对盲目\n推广其他地方的经验做法这一行为展开分析，并未提及“耍弄聪明”，与文意不符，排除。\n第一空，代入验证。B项“照搬”指照原样不动地搬用（现成的方法、经验、教材等），填入文段表达借鉴不可原封不\n动地搬用之意，与后文“比如，平原地区的耕地恢复方法不一定适合山区”对应得当，符合文意，保留。\n第二空，代入验证。B项“大相径庭”比喻相差很远或截然不同，置于此处与前文“平原地区的耕地恢复方法不一定适合\n山区”对应得当，表达粮食主产区与主销区可能差别很大之意，符合文意，当选。\n故正确答案为B。\n【文段出处】中国自然资源报《抓好耕地保护当多思“六须六忌”》\n【考点】\n混搭填空,关联关系-并列关系【逻辑填空】,关联关系-因果关系【逻辑填空】","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-1817dc5f6d6ae5d8","label":"“水土不服”可比喻外来的做法不适应当地条件","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"可表达盲目照抄其他地区的耕保经验可能不适用\n于本地实际情况之意","why":"第三空要求识别该成语从生活环境不适应引申出的用法。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"外地可能“借”不\n来也“学”不好","why":"结合经验依赖当地条件及后果并列关系，推断第三空指做法难以在异地适用，再核验前两空。","origin":"逐题标记","originalId":"s-9c1efa980c7aa095"}]},"国考 2025 地市级 行测#49":{"stem":"手枪短小轻便、易于隐藏，是军队      的装备。早期手枪由于使用黑火药，燃烧速度较慢，射击速度和射程\n受到很大限制。随着无烟火药的发明，弹药技术迎来革命性突破，弹匣手枪           。无烟火药燃烧速度快，可大幅\n提升射击速度和射程，弹匣手枪依托这一技术优势         。\n依次填入画横线部分最恰当的一项是：","options":["不可或缺 应运而生 崭露头角","首当其冲 横空出世 声名鹊起","必不可少 初露锋芒 后来居上","屡见不鲜 大放异彩 脱颖而出"],"answer":"A","analysis":"49. 正确答案：A\n\n解析：\n第一空，横线处搭配“手枪”且根据“手枪短小轻便、易于隐藏”可知，横线处应体现手枪是军队重要的武器装备之意，\nA项“不可或缺”指不能有一点点缺失，C项“必不可少”指绝对需要的，填入文段均能体现手枪在军队的重要性，保留。\nB项“首当其冲”指最先受到攻击或遭遇灾难，与文意不符且与“手枪”搭配不当，排除；D项“屡见不鲜”指经常看见并不\n稀奇，只强调常见，但并不能表达手枪的优势和重要性，排除。\n第二空，结合前文可知早期手枪性能受到限制，且根据“随着无烟火药的发明，弹药技术迎来革命性突破”可知，横线\n处应体现“弹匣手枪”出现之意，A项“应运而生”指适应时机而产生，与前文衔接恰当，当选。C项“初露锋芒”比喻刚开\n始显示出力量或才能，根据论述逻辑，应先交代弹匣手枪的问世，随后再分析其优势，置于此处与文意不符，排\n除。\n第三空，代入验证，根据“无烟火药燃烧速度快，可大幅提升射击速度和射程”可知，横线处应体现弹匣手枪逐渐显示\n出优势之意，A项“崭露头角”比喻突出地显露出才能和本领，符合文意，当选。\n故正确答案为A。\n【文段出处】解放军报《手枪的创新升级之路》\n【考点】\n成语填空,词的辨析-搭配对象,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-0f4bd795df8c49a6","label":"“应运而生”表示适应时机而产生","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“应运而生”指适应时机而产生","why":"第二空需要区分事物初次出现与已有事物初步显露能力。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析词语","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"应先交代弹匣手枪的问世，随后再分析其优势","why":"根据行文次序判断第二空表示问世，再核验其他两空分别指向重要性和优势显现。","origin":"逐题标记","originalId":"s-9c1efa980c7aa095"}]},"国考 2025 地市级 行测#50":{"stem":"改进文风就要多写“短实新”的好文章。“实”就是讲符合实际的话不讲脱离实际的话，讲管用的话不讲空话，讲反\n映自己思考的话不讲       的话，讲有感而发的话不讲   的话，讲通俗明白的话不讲故作高深的\n话，      ，用朴实的语言阐述深刻的理论。\n依次填入画横线部分最恰当的一项是：","options":["故弄玄虚 装腔作势 由表及里","照本宣科 无病呻吟 深入浅出","人云亦云 言不由衷 举一反三","陈词滥调 冠冕堂皇 言简意赅"],"answer":"B","analysis":"50. 正确答案：B\n解析：\n第一空，根据“讲······的话不讲······的话”可知，横线处所填成语应与“反映自己思考”构成反义并列关系，体现缺乏自\n己思考之意。B项“照本宣科”意为死板地照现成文章或稿子宣读，指不能灵活运用；C项“人云亦云”意为人家说什么自\n己也跟着说什么，形容没有主见。两项均符合文意，保留。A项“故弄玄虚”形容故意玩弄使人迷惑的花招，与文意不\n符，排除。D项“陈词滥调”意为陈旧而不切合实际的话，与后文的“话”语义重复，排除。\n第二空，根据“讲······的话不讲······的话”可知，横线处所填成语应与“有感而发”构成反义并列关系，体现不是真正所\n感之意。B项“无病呻吟”比喻没有值得忧虑的事情却长吁短叹，也比喻文艺作品缺乏真情实感，矫揉造作；C项“言不\n由衷”意为说的话不是从内心发出来的，指心口不一致。两项均符合文意，保留。\n第三空，根据后文“用朴实的语言阐述深刻的理论”可知，横线处所填成语应体现用通俗的话讲明白深刻的道理之意。\nB项“深入浅出”指文章或言论的内容很深刻，措辞却浅显易懂，符合文意，当选。C项“举一反三”意为从一件事情类推\n而知道其他许多事情，与文意无关，排除。\n故正确答案为B。\n【文段出处】光明日报《大力倡导优良文风》\n【考点】\n成语填空,词的辨析-搭配对象,关联关系-并列关系【逻辑填空】,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-0e4d07f460cabe46","label":"“深入浅出”指内容深刻而表达浅显易懂","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“深入浅出”指文章或言论的内容很深刻，措辞却浅显易懂","why":"尾句同时要求内容深刻和表达通俗，第三空须识别兼具两层含义的成语。","origin":"逐题标记","originalId":"k-717a06a8fe03894e"},{"id":"s-bc177199c1351631","label":"依据语境辨析词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"用朴实的语言阐述深刻的理论","why":"用排比中的正反对应限定前两空，再根据尾句对内容和语言的要求辨析第三空。","origin":"逐题标记","originalId":"s-9c1efa980c7aa095"}]},"国考 2025 地市级 行测#51":{"stem":"习近平新时代中国特色社会主义思想植根于新时代中国特色社会主义伟大事业的创造性实践，每一个理论成分背\n后都有着鲜活的实践支撑，比如蕴含“创新、协调、绿色、开放、共享”新发展理念的经济高质量发展案例、体现“党\n的领导、人民当家作主和依法治国有机统一”政治理念的现代治理案例、体现“绿水青山就是金山银山”的生态文明思\n想案例等。通过讲述这些蕴含中国观点、体现中国立场、彰显中国智慧、弘扬中国价值的生动故事，让国际社会更\n加深切地感知和理解习近平新时代中国特色社会主义思想的理论内涵和实践逻辑。\n这段文字意在强调：","options":["党的创新理论要在实践中检验和发展","讲好中国故事有助于提高国际话语权","要积极利用案例传播党的创新理论","理论宣传应该综合运用国内外资源"],"answer":"C","analysis":"51. 正确答案：C\n解析：\n文段开篇提出习近平新时代中国特色社会主义思想的每一个理论成分背后都有实践支撑，接着通过“比如”进行举例说\n明，尾句通过指代词“这些”总结前文，指出通过讲述这些案例可以让国际社会更加深切地感知和理解习近平新时代中\n国特色社会主义思想的理论内涵和实践逻辑。故文段讨论的核心话题为“习近平新时代中国特色社会主义思想”，重点\n强调通过讲述案例来传播习近平新时代中国特色社会主义思想，即传播党的创新理论，对应C项。\nA项：“在实践中检验和发展”对应举例部分的内容，非重点，排除。\nB项：文段主题词为“党的创新理论”，而非“中国故事”，该项主题词错误，排除。\nD项：文段讨论的核心话题为“党的创新理论”，“理论”范围扩大，且“国外资源”无中生有，排除。\n故正确答案为C。\n【文段出处】《做好党的创新理论对外传播》\n【考点】\n中心理解题-关联词-对策,中心理解题-主题词","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"通过讲述这些蕴含中国观点、体现中国立场、彰显中国智慧、弘扬中国价值的生动故事","why":"沿尾句的“这些”回指前文案例，把讲述案例的方式与促进国际理解的目的合起来概括。","origin":"逐题标记"}]},"国考 2025 地市级 行测#52":{"stem":"在青藏高原高寒草甸的多年冻土区，地下水或土壤水分迁移冻结导致地下冰聚集，使地表隆起形成的丘状地带便\n是冻胀丘。冻胀丘中土壤结构和植物根系的破坏，改变了地表径流，导致部分缓坡和低地积水严重，继而引起草地\n破碎化和地表裸露区增加等草地荒漠化问题。随着冻土内冰的消融和水分流出，地下有时会形成较大的空洞区，地\n表发生沉降和塌陷，往往会造成地区植被和土壤的显著退化。冻土区随着表层冻土的解冻融化，坡体中的饱水松散\n土层和风化层间的摩擦力减小，在重力作用下，沿斜坡缓慢流动或蠕动形成融冻泥流，这也会使植被和土壤遭到强\n烈破坏。\n这段文字接下来最可能介绍青藏高原：","options":["冻胀丘对高原生态系统的危害","地表植被的恶劣生存状况","多年冻土区的形成原因","冻土所致荒漠化的防治措施"],"answer":"D","analysis":"52. 正确答案：D\n解析：\n根据提问方式可知，本题为接语选择题，应在通读全文的基础上，重点关注文段最后论述的核心话题。文段开篇引\n出“冻土区”的话题，并指出冻土区地下冰聚集会带来冻胀丘，冻胀丘土壤结构和植物根系的破坏会带来草地荒漠化问\n题，接着介绍冻土内冰的融化也会导致荒漠化。故文段主要论述冻土区带来了荒漠化的问题，接下来应围绕如何解\n决这一问题来展开，对应D项。\n\nA、B两项，均对应文段已论述的内容，后文不会继续论述，排除；\nC项，未提到文段的核心话题“荒漠化”，与文段无法衔接，排除。\n故正确答案为D。\n【文段出处】个人图书馆《冻融荒漠化》\n【考点】\n综合全文确定答案","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-94e5b1e84b4945ab","label":"推断下文话题","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"文段主要论述冻土区带来了荒漠化的问题","why":"把前文列举的多种破坏归入荒漠化问题，再据问题与对策的衔接推断后文。","origin":"逐题标记","originalId":"s-2b9404ef64bab2a1"}]},"国考 2025 地市级 行测#53":{"stem":"相对于狭义的农业即种植业而言，大农业是指广义的农业，不仅包括种植业、林草业、畜牧业和渔业，还包括产\n前的技术研发、品种繁育与推广、水利建设、农机生产与销售、农资储备与供应等，产后的烘干、储藏、运输、加\n工、营销与进出口贸易等，由此形成一个与农业发展有关、为农业发展服务的庞大产业体系。可以说，\n。发展现代化大农业就是要构建一个现代化的大农业产业体系，这也是当前我国构建现代乡村产业体系的核心所\n在。\n填入画横线部分最恰当的一项是：","options":["大农业是对农业及其紧密联系的相关产业的高度概括","农村产业融合化发展是当今乡村产业发展的必然趋势","大农业是在当前技术条件下实现的对小农经济的超越","发展现代化大农业应该因地制宜推进农业规模化经营"],"answer":"A","analysis":"53. 正确答案：A\n解析：\n本题为语句填空题，横线位于文段中间，需结合前后文语境进行分析。横线前指出大农业是指广义的农业，不仅包\n括农林牧渔业，还包括产前的技术研发、水利建设等和产后的烘干、储藏等一系列相关产业，之后通过因果标志\n词“由此”强调大农业形成了一个庞大的产业体系，随后通过“可以说”对前文进行总结，横线后表明想要发展现代化大\n农业就需要构建现代化的大农业产业体系。结合前后文可知，横线处应围绕“大农业”展开论述，并说明大农业是包括\n农林牧渔业及其紧密联系的相关产业的有机整体，是跨越行业边界的庞大产业，对应A项。\nB项：“农村产业融合化”偏离文段核心话题“大农业”，排除。\nC项：“对小农经济的超越”偏离文段核心，文段重在强调大农业是包括农林牧渔业及其一系列相关产业的有机整体，\n该项无法与前后文衔接，排除。\nD项：“因地制宜推进农业规模化经营”文段未提及，无中生有，排除。\n故正确答案为A。\n【文段出处】《坚持以发展现代化大农业为主攻方向》\n【考点】\n承上启下","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-4eebda7bdff18647","label":"补全语句衔接","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"随后通过“可以说”对前文进行总结","why":"根据“可以说”识别总结功能，概括上文列出的农业及其相关产业，并衔接下文的产业体系。","origin":"逐题标记"}]},"国考 2025 地市级 行测#54":{"stem":"①但目前来看，新一代AI都表现出一定的回避提问的意图，这可能与模型试图节约算力资源有关\n②在目前的法律框架内，数字生命还不是可以承担法律责任的主体，而被认为是程序、代码，或是人在网络空间中\n的一个身份\n③如果机器向人输出了错误或者不能理解的内容，这是算法故障，应当要求开发、维护人员尽快修复，而不是指令\n机器“立刻改正”\n④不过一旦模型有自主选择逃避人类提问的能力，并且已经脱离了开发人员的控制，AI没有法律人格的结论就要面\n临挑战了\n⑤一般认为，创造数字生命的人，就是对数字生命负责的人，例如程序的开发者、AI的使用者等\n\n⑥这除了伦理上的考虑，还有其不具备承担责任可能的因素\n将以上6个句子重新排列，语序正确的一项是：","options":["②⑤⑥①④③","⑤②⑥④①③","②⑥⑤③①④","⑤③②⑥④①"],"answer":"C","analysis":"54. 正确答案：C\n解析：\n对比选项，确定首句。②句引出“数字生命”这一概念，并阐述其不是可以承担法律责任的主体，⑤句指出创造数字生\n命的人就是对数字生命负责的人。按照行文逻辑，应该先引出“数字生命”这一话题，再介绍数字生命的创造者，故②\n句更适合作为首句，排除B、D两项。\n观察句子发现，⑥句中出现指代词“其”，对比A、C两项，⑥句之前分别为⑤句和②句，⑥句论述“其”不具备承担责任\n可能的因素，说明⑥句之前所接的句子应提到无法承担责任的主体对象，②句指出数字生命还不是可以承担法律责\n任的主体，可与⑥句构成指代词捆绑，C项当选。⑤句提到对数字生命负责的人，与⑥句话题不一致，无法构成指代\n词捆绑，排除A项。\n故正确答案为C。\n【文段出处】学习时报《数字生命遥远吗？》\n【考点】\n指代词,观点+解释说明","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-871196fcda246b8d","label":"按语句衔接排列语序","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"⑥句之前所接的句子应提到无法承担责任的主体对象","why":"先定位引出数字生命的句子，再用⑥句中“其”的指代对象确定紧邻的前句。","origin":"逐题标记","originalId":"s-8dc13705cced3b68"}]},"国考 2025 地市级 行测#55":{"stem":"①严格执法与公正司法是相辅相成的\n②加强行政执法与刑事司法衔接，是为了确保二者之间既能互不干扰，又能高效转换，从而更有力地实施法律\n③前端为后端减负、后端为前端增力，才能更好地让严格执法与公正司法共同发力，促进法律有效实施，保障社会\n公平正义\n④特别是在环境保护、食品安全等关系人民切身利益的重点领域，行政执法与刑事司法脱节会导致法律威慑力不足\n⑤习近平总书记指出，“要加强行政执法与刑事司法有机衔接，坚决克服有案不移、以罚代刑等现象”\n⑥严格执法位于前端，通过行政手段依法保障人民群众的生命财产安全；公正司法位于后端，定分止争，是公平正\n义的最后一道防线\n将以上6个句子重新排列，语序正确的一项是：","options":["①⑥⑤②④③","①②④⑤③⑥","⑤③⑥④①②","⑤⑥②③①④"],"answer":"A","analysis":"55. 正确答案：A\n解析：\n对比选项，确定首句。①句指出严格执法与公正司法是相辅相成的，⑤句通过引用习近平总书记的话，指出要加强\n行政执法与刑事司法有机衔接，两句均无明显的非首句特征，无法判断首句。\n继续寻找其他线索，③⑥两句均在论述“前端”“后端”的话题，且③句介绍前端与后端的配合能够更好地让严格执法与\n公正司法共同发力，⑥句介绍前端是严格执法，后端是公正司法，按照逻辑顺序，应先介绍前端与后端所指的内\n容，再介绍二者应如何配合，故⑥句应在③句之前，排除B、C两项。\n对比A、D两项的尾句，尾句分别为③句与④句，③句通过必要条件“······才······”给出了前端与后端配合的对策，④\n句介绍了行政执法与刑事司法脱节所带来的问题，按照行文逻辑可知，应先论述问题，再提出对策，故④句应在③\n句之前，排除D项，A项当选。\n故正确答案为A。\n【文段出处】学习时报《建立行政执法与刑事司法“无缝衔接”机制》\n【考点】\n确定捆绑-其他,行文逻辑-其他,对策","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-871196fcda246b8d","label":"按语句衔接排列语序","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"应先论述问题，再提出对策","why":"先依据释义确定介绍前后端的句子应在说明配合方式之前，再用脱节问题与衔接对策确定收束顺序。","origin":"逐题标记","originalId":"s-8dc13705cced3b68"}]},"国考 2025 地市级 行测#56":{"stem":"相较于地球，月球上氦-3储量极为丰富。氦-3来源于太阳内部核聚变，以高能粒子形式通过太阳风向宇宙扩散。\n月球没有大气层，其磁场不足地球的千分之一，使得太阳风能够直射月球表面并将氦-3注入月壤层。同时，月表温度\n在月夜最低可达     ，极地永久阴影区甚至可达     。极低温环境有效促进了氦-3被月壤层吸附，阻止其向\n太空逃逸，并在月表不断富集。据估算，全月氦-3换算储量高达110万吨，可作为清洁核原料供地球使用约1万年。\n这段文字能够解释下列哪一问题？","options":["月球上的氦-3储量是如何换算的","低温如何促进氦-3被月壤层吸附","为何太阳风能将氦-3注入月壤层","如何开采月球上丰富的氦-3资源"],"answer":"C","analysis":"56. 正确答案：C\n解析：\n\nA项，文段尾句仅提到“换算储量高达110万吨”，并未提及具体换算的过程，故“如何换算”无中生有，排除；\nB项，根据“极低温环境有效促进了氦-3被月壤层吸附，阻止其向太空逃逸，并在月表不断富集”可知，文段仅提到低\n温能有效促进氦-3被月壤层吸附，并未提及低温促进氦-3被月壤层吸附的具体过程，故“如何促进”无中生有，排除；\nC项，根据“月球没有大气层，其磁场不足地球的千分之一，使得太阳风能够直射月球表面并将氦-3注入月壤层”及“极\n低温环境有效促进了氦-3被月壤层吸附，阻止其向太空逃逸，并在月表不断富集”可知，文段详细论述了来自太阳风\n的氦-3能够注入月壤层的两方面原因，当选；\nD项，“如何开采月球上丰富的氦-3资源”文段并未提及，无中生有，排除。\n故正确答案为C。\n【文段出处】光明日报《走，到月球采矿去》\n【考点】\n其他（如选项为图片的细节判断题等）","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-ef0f414c890a2427","label":"核对原文与选项","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"这段文字能够解释下列哪一问题？","why":"按各问题要求的解释范围查找对应陈述，辨别原文是否给出了所问的原因或过程。","origin":"逐题标记"}]},"国考 2025 地市级 行测#57":{"stem":"“微利惠民”是老年助餐行业的重要特点，但这也导致其盈利点不够清晰，加上配套服务体系建设还不够健全、客\n流不稳定等因素影响，导致一些助餐机构经营困难。当前，要进一步推广老年助餐服务，应在设施场地、资金筹\n集、税费减免等方面加大支持力度，并提高政策精准度。此外，还要充分发挥市场机制作用，不断提高助餐机构自\n身能力。最后，应从老年人的现实需求和助餐服务的运营实际出发，引导更多主体参与，完善多元筹资机制，落实\n各项优惠措施，才能进一步扩大服务覆盖面，形成更合理的布局，为更多老年人提供便利。\n这段文字意在强调：","options":["老年助餐服务行业有良好的市场发展前景","多重因素导致老年助餐机构面临经营困境","应当帮助老年助餐机构适当提高盈利能力","多措并举多方参与方能推广老年助餐服务"],"answer":"D","analysis":"57. 正确答案：D\n解析：\n文段开篇利用转折关联词“但”引出老年助餐行业的经营问题，第二句通过“应”引导对策，接下来通过“此外”“最后”等并\n列标志，引导出另外两条对策，这些对策都在围绕如何解决老年助餐问题进行论述。故文段为“提出问题+对策”的结\n构，重在解决“老年助餐行业”的诸多问题，由于文段提出多条并列的对策，所以需要全面概括，对应D项。\nA项，“良好的市场发展前景”文段并未提及，无中生有，排除；\nB项，为问题表述，然而文段强调解决问题的对策，偏离文段重点，排除；\nC项，“提高盈利能力”文段并未提及，无中生有，排除。\n故正确答案为D。\n【文段出处】人民日报《小小助老餐，惠及大民生——发展银发经济，增进老年人福祉①》\n【考点】\n中心理解题-关联词-对策","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"文段提出多条并列的对策，所以需要全面概括","why":"根据“但”定位经营问题，再综合“应”“此外”“最后”引出的多项推广对策。","origin":"逐题标记"}]},"国考 2025 地市级 行测#58":{"stem":"同位素定年方法利用放射性同位素衰变原理来计算地表水进入封闭地下环境的时间，可以反映水在地下的补给径\n流排泄规律；稳定同位素有同位素分馏和季节效应，在不同体系中分布比例存在差异，因此可以用来示踪地下水的\n混合过程。目前，地下水循环研究中常用的同位素包括碳、氢、氧、硫等。随着技术发展，金属同位素等非传统同\n位素的应用，扩大了地下水定年范围。其中，镁元素是主要造岩元素，易在风化过程中以离子形式进入水体，且镁\n元素迁移行为简单、参与地球化学行为广，可以在地下水科学研究中发挥重要作用。\n这段文字没有提及：","options":["稳定同位素用于示踪地下水混合过程的原理","镁元素在地下水研究中发挥重要作用的原因","推动非传统同位素用于地下水研究的关键技术","计算地表水进入封闭地下环境所用时间的意义"],"answer":"C","analysis":"58. 正确答案：C\n解析：\nA项：根据“稳定同位素有同位素分馏和季节效应，在不同体系中分布比例存在差异，因此可以用来示踪地下水的混\n合过程”可知，该项文段有提及，排除。\nB项：根据“镁元素是主要造岩元素，易在风化过程中以离子形式进入水体，且镁元素迁移行为简单、参与地球化学\n行为广，可以在地下水科学研究中发挥重要作用”可知，该项文段有提及，排除。\nC项：文段仅提及“金属同位素等非传统同位素的应用，扩大了地下水定年范围”，未提及“推动非传统同位素用于地下\n水研究的关键技术”，无中生有，当选。\nD项：根据“同位素定年方法利用放射性同位素衰变原理来计算地表水进入封闭地下环境的时间，可以反映水在地下\n的补给径流排泄规律”可知，该项文段有提及，排除。\n本题为选非题，故正确答案为C。\n【文段出处】中国矿业报《透视地下蕴藏的水信息》\n【考点】\n常规解题方法","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-ef0f414c890a2427","label":"核对原文与选项","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"这段文字没有提及：","why":"逐项定位对应语句，核实原文是否具体交代了选项所问的原理、原因、技术或意义。","origin":"逐题标记"}]},"国考 2025 地市级 行测#59":{"stem":"如果一味沉湎于琐碎的日常事务，缺乏大局观念和政治远见，不分轻重缓急，不从原则高度想问题，就会陷入事\n务主义。习近平总书记指出：“如果忙忙碌碌，只是机械做事，陷入事务主义，是很难提高认识和工作水平的。”这就\n\n意味着，要提高认识水平，必须走出事务主义的泥潭。毛泽东曾经指出：“庸俗的事务主义家不是这样，他们尊重经\n验而看轻理论，因而不能通观客观过程的全体，缺乏明确的方针，没有远大的前途，沾沾自喜于一得之功和一孔之\n见。”这为如何走出事务主义提供了指南针和路线图。\n这段文字认为，为避免陷入事务主义，应该：","options":["具有清晰明确的工作方案","坚持从理论高度看待问题","不断从实践中总结经验教训","通过学习补齐能力素质短板"],"answer":"B","analysis":"59. 正确答案：B\n解析：\n文段开篇从反面提对策，指出避免陷入事务主义，要有大局观念和政治远见，要从原则高度思考问题。随后引用习\n近平总书记的讲话强调要提高认识水平，不能陷入事务主义泥潭。后文通过毛泽东的讲话再一次从反面说明没有大\n局观念及政治远见的庸俗的事务主义家的特点。故文段重点为首句的对策，即要避免陷入事务主义，就应有大局观\n念和政治远见，要从原则高度思考问题，对应B项。\nA、C、D三项：A项“工作方案”、C项“从实践中总结经验教训”、D项“通过学习补齐能力素质短板”文段均未提及，无\n中生有，排除。\n故正确答案为B。\n【文段出处】《为什么说只有理解了的东西才更深刻地感觉它？》\n【考点】\n中心理解题-关联词-对策","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"文段开篇从反面提对策","why":"把首句描述的致因转化为正向做法，并结合引文中看轻理论的例子核对概括。","origin":"逐题标记"}]},"国考 2025 地市级 行测#60":{"stem":"在一些科幻影片中，大质量黑洞周身的光环令人印象深刻。事实上，这并不是黑洞在发光，而是由宇宙中的气体\n物质构成的吸积盘所辐射的光芒。当黑洞附近有物质靠近时，这些物质并不会立刻被黑洞吞噬，而是被吸引到一个\n叫做吸积盘的结构中。当吸积盘受黑洞引力和摩擦的作用不断向内旋进时，内层的气体和尘埃被挤压导致温度上升\n从而发射出电磁辐射，这就形成了黑洞周身的光环。不过，由于黑洞强大的引力对光的扭曲效应，我们所能看到的\n吸积盘并不是一个扁平的圆盘，而是圆盘的远端被折起来，如同给黑洞戴了个“帽子”。\n这段文字主要介绍：","options":["黑洞周身产生光环的原因","吸积盘的形成及物质构成","吸积盘与黑洞作用的方式","黑洞吞噬宇宙物质的过程"],"answer":"A","analysis":"60. 正确答案：A\n\n解析：\n文段开篇引出黑洞周身的光环，接着通过转折词“事实上”指出黑洞周身的光环并非黑洞自身发光，而是吸积盘所辐射\n的光芒，然后具体分析了黑洞周身光环的形成的原因，即由物质靠近黑洞后被吸引到吸积盘中，吸积盘受黑洞引力\n和摩擦作用不断向内旋进时，内层气体和尘埃被挤压导致升温，从而发射电磁辐射形成光环，最后又补充说明由于\n黑洞引力对光的扭曲效应使得吸积盘呈现出特殊形状。故整个文段重点阐述的是黑洞周身产生光环的原因，对应A\n项。\nB项“吸积盘的形成及物质构成”、C项“吸积盘与黑洞作用的方式”均对应解释说明内容，非重点，排除；\nD项，“黑洞吞噬宇宙物质的过程”文中并未提及，无中生有，排除。\n故正确答案为A。\n【文段出处】墨子沙龙《凝望深渊，慧眼揭示黑洞吸积盘的秘密》\n【考点】\n中心理解题-关联词-转折,分述句特征-引入铺垫,分述句特征-其他","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"故整个文段重点阐述的是黑洞周身产生光环的原因","why":"沿着“事实上”后的发光来源和形成过程提炼主旨，把末尾的形状描述视为补充。","origin":"逐题标记"}]},"国考 2025 地市级 行测#61":{"stem":"如今，文艺工作者深入挖掘传统绘画与传统舞蹈之间的内在联系，将诗、书、画、乐、舞融于一体，形成新的审\n美表达。比如，杭州亚运会开幕式文艺表演环节，第一个节目《水墨入诗画》便以中国画为基本元素，身着青绿色\n长裙的舞者在山水画卷中翩翩起舞，营造出“人在画中游”的优美意境。舞蹈诗剧《只此青绿》同样以经典山水画为灵\n感，通过舞蹈再现画家王希孟创作《千里江山图》的过程，并以刚柔相济的肢体语言、精心设计的舞蹈动作呈现山\n水神韵。在这些作品中，传统绘画与舞蹈的创意融合产生叠加效应，使传统文化与现代审美相谐适，产生了广泛的\n社会影响。\n最适合做这段文字标题的是：","options":["青绿热：传统与现代的双向奔赴","传统与现代：审美表达的异与同","人在画中游：穿越千年的艺术盛宴","画与舞：跨界融合激发艺术新活力"],"answer":"D","analysis":"61. 正确答案：D\n解析：\n文段开篇指出文艺工作者深入挖掘传统绘画与传统舞蹈之间的内在联系，将多种艺术形式融于一体，形成新的审美\n表达。接着后文通过“比如”举例，论述《水墨入诗画》、《只此青绿》两部作品均是将传统绘画与舞蹈进行巧妙融\n合，取得了很好的艺术效果。尾句呼应文段开头，再次强调通过传统绘画与舞蹈的融合，产生了叠加效应，使得传\n统文化与现代审美相谐适，故文段重在强调通过传统绘画与舞蹈的跨界融合，形成了新的审美艺术表达，对应D项。\nA项，“青绿热”对应文段举例部分的内容，非重点，且“传统与现代的双向奔赴”表述不够明确，文段重在强调“传统绘\n画与舞蹈”的融合，排除；\nB项，“传统与现代”表述不明确，文段重在论述由“传统绘画与舞蹈”融合，产生了新的审美艺术表达，而非对比“审美\n表达的异与同”，偏离文段中心，排除；\nC项，“人在画中游”对应文段举例部分的内容，非重点且表述片面，排除。\n故正确答案为D。\n【文段出处】人民日报《跨界融合激发美术新活力（艺坛走笔）》\n【考点】\n契合文段中心","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-0a0bc5508fefda64","label":"根据文段主旨选拟标题","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"故文段重在强调通过传统绘画与舞蹈的跨界融合，形成了新的审美艺术表达","why":"结合首尾呼应提炼两类艺术融合及其效果，用标题覆盖两则例证共同说明的主题。","origin":"逐题标记","originalId":"s-34ba2cad4288572e"}]},"国考 2025 地市级 行测#62":{"stem":"与传统业态相比，新业态顺应多元化、多样化、个性化的产品或服务需求，实现产业与互联网、大数据、云计\n算、人工智能等新技术深度融合，通过采用新技术和新模式，为市场引入新元素、丰富新场景，促进新岗位、新就\n业形态不断涌现，创造更多就业机会。新业态既提供新的高技能岗位，扩大对高水平劳动力的需求，又通过带动传\n统产业转型升级，实现对传统职业和岗位的再造，释放新的就业需求。当前，我国有超2亿灵活就业人员，新就业形\n态       。\n填入画横线部分最恰当的一项是：","options":["已经成为吸纳就业的重要“蓄水池”","有助于促进区域间劳动资源的互补与共享","为高技能劳动力流动提供充足机会","是有效缓解重点群体就业压力的“缓冲器”"],"answer":"A","analysis":"62. 正确答案：A\n解析：\n横线位于文段结尾，需对前文内容进行总结，且横线为尾句中的分句，还要与横线前的分句构成衔接。文段开篇提\n出“新业态”的话题，指出新业态顺应各方面需求，实现产业与新技术深度融合，创造了更多的就业机会，接着继续介\n绍新业态能够扩大对高水平劳动力的需求，实现对传统职业和岗位的再造，并释放新的就业需求，尾句前半部分指\n出我国有超2亿灵活就业人员，根据前文可知，整个文段重在强调新就业形态有助于拓展就业空间、创造就业机会，\n因此横线处应体现出新就业形态对于吸纳就业起到了重要作用，A项“吸纳就业的重要‘蓄水池’”能够体现出新就业形态\n在吸纳就业方面的重要作用，当选。\nB项，“区域间劳动资源的互补与共享”文段并未提及，无中生有，排除；\nC项，“高技能劳动力流动”仅能对应文段中“既提供新的高技能岗位”的部分，表述片面，排除；\nD项，“有效缓解重点群体就业压力”文段并未提及，无中生有，排除。\n故正确答案为A。\n【文段出处】经济日报-《胡晨光：发挥新业态促就业重要作用》\n【考点】\n总结前文,横线为尾句中的分句","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-4eebda7bdff18647","label":"补全语句衔接","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"需对前文内容进行总结，且横线为尾句中的分句，还要与横线前的分句构成衔接。","why":"归纳前文关于新增岗位和重塑传统岗位的说明，再检查补句能否承接灵活就业人数。","origin":"逐题标记"}]},"国考 2025 地市级 行测#63":{"stem":"相比高校和科研机构，企业处于市场最前沿，对有市场潜力的技术感知更灵敏，对产业发展趋势的把握也更敏\n锐。因此，在颠覆性技术的研发、转移转化过程中，需要强化企业科技创新主体地位。在课题立项中，要加快提升\n企业技术创新决策的主体地位，建立企业常态化参与国家科技创新决策的机制；在创新过程中，要着力强化企业科\n研组织的主体地位，支持领军企业聚焦国家重大需求，牵头组建创新联合体，加快形成企业主导的产学研深度融\n合。同时，人才、经费等创新要素也要加快向企业特别是科技领军企业集聚。\n这段文字意在说明：","options":["应着力完善国家科技创新决策的体制机制","颠覆性技术创新需重视并发挥企业的作用","要大力推进颠覆性技术的研发及转移转化","创新要素的大量集聚有助于企业技术创新"],"answer":"B","analysis":"63. 正确答案：B\n解析：\n文段开篇指出企业在市场中具有重要地位，接着通过“因此”得出结论，并通过“需要”提出对策，即在颠覆性技术的研\n发和转移转化过程中，需要强化企业科技创新主体地位。后文分别从课题立项、创新过程以及创新要素三方面进行\n具体解释。故文段重在强调应强化企业在颠覆性技术创新中的主体地位，对应B项。\nA项：“国家科技创新决策的体制机制”对应后文解释说明部分，非重点，且缺少文段主题词“企业”，排除。\nC项：缺少文段主题词“企业”，偏离文段重点，排除。\nD项：“创新要素”仅对应文段解释说明的一个方面，非重点且表述片面，排除。\n\n故正确答案为B。\n【文段出处】《大力推进颠覆性技术创新》\n【考点】\n中心理解题-关联词-对策,中心理解题-主题词,分述句特征-多角度论述,分述句特征-引入铺垫","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"需要强化企业科技创新主体地位。","why":"从“因此”引出的主张提炼中心，并用立项、创新组织和要素集聚三个方面的分述验证主旨。","origin":"逐题标记"}]},"国考 2025 地市级 行测#64":{"stem":"熔盐堆是第四代核能系统中唯一的液态燃料堆，我国研发的熔盐堆是“钍基熔盐堆”，即用钍元素作为核燃料、用\n熔融态的盐作为热介质进行发电。和常规铀反应堆不同，钍基熔盐堆内部循环的是液态盐。这些液态盐既可被当作\n核燃料的承载体，又能被当作核裂变反应的冷却剂，因此在使用时要将钍元素溶解在氟盐冷却剂里生成氟化盐，进\n而不断输出巨大的能量。由于钍基熔盐反应堆是用氟化盐作冷却剂，依赖的水资源较少，在缺水的干旱地区甚至沙\n漠地区也能建造和运行。\n这段文字解释了下列哪一问题？","options":["液态盐作为反应堆核燃料承载体有何缺陷","钍元素通过何种方式溶解在氟盐冷却剂中","第四代核能系统为何仅有一种液态燃料堆","钍基熔盐反应堆为何可以在干旱地区建造"],"answer":"D","analysis":"64. 正确答案：D\n解析：\nA项，文段未提及液态盐作为反应堆核燃料承载体的缺陷，无中生有，排除；\nB项，文段提及了“在使用时要将钍元素溶解在氟盐冷却剂里生成氟化盐”，但未详细说明钍元素具体通过何种方式溶\n解在氟盐冷却剂中，无中生有，排除；\nC项，文段开篇提及了“熔盐堆是第四代核能系统中唯一的液态燃料堆”，但第四代核能系统仅有一种液态燃料堆的原\n因并未提及，无中生有，排除；\nD项，根据“由于钍基熔盐反应堆是用氟化盐作冷却剂，依赖的水资源较少，在缺水的干旱地区甚至沙漠地区也能建\n造和运行”可知，文段解释了钍基熔盐反应堆为何可以在干旱地区建造，表述正确，当选。\n故正确答案为D。\n【文段出处】岩土科普博览《第四代核能技术全球领跑》\n【考点】\n其他（如选项为图片的细节判断题等）","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-ef0f414c890a2427","label":"核对原文与选项","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"用氟化盐作冷却剂，依赖的水资源较少","why":"定位支撑干旱地区建造条件的因果说明，核对原文是否实际回答了选项提出的问题。","origin":"逐题标记"}]},"国考 2025 地市级 行测#65":{"stem":"经济是肌体，金融是血脉，两者共生共荣。银行利润建立在企业发展的基础上，实体经济如果没有足够的利润率\n或者盈利能力，银行是没有办法获得持续发展和盈利空间的。而当前净息差的降低，使企业从银行获得了低成本贷\n款，能够极大减轻企业经营发展负担，把更多资金投入科研创新、转型升级、设备更新等领域，进而实现高质量发\n展。唯有实体经济规模扩大、效益改善、质量提升，银行才能获得自身高质量发展的坚实基础。\n这段文字意在说明：","options":["银行的盈利空间与企业盈利能力相辅相成","经济的稳定与繁荣是金融持续发展的根基","银行要稳健发展须保持合理的净息差水平","降低净息差有助于促进企业和银行的共赢"],"answer":"D","analysis":"65. 正确答案：D\n解析：\n文段开篇指出经济与金融是共生共荣的关系，接着说明银行利润建立在企业发展的基础上，随后指出目前净息差的\n降低减轻了企业经营发展负担，使得企业能够把更多资金投入科研创新等领域，实现高质量发展，而企业高质量发\n展能为银行高质量发展打下坚实的基础。故文段重点强调降低净息差既能够促使企业发展，也能够推动银行发展，\n对应D项。\nA、B两项：均对应文段开篇话题引入部分的内容，非重点，且缺少文段核心话题“降低净息差”，排除。\nC项：缺少文段核心话题“企业”，且“合理的净息差水平”与文段“降低净息差”表述不一致，排除。\n故正确答案为D。\n【文段出处】人民日报《净息差20年来最低，背后是银行让利实体经济》\n【考点】\n中心理解题-关联词-对策,中心理解题-主题词","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"故文段重点强调降低净息差既能够促使企业发展，也能够推动银行发展","why":"串联净息差降低、企业融资负担减轻和企业发展为银行发展奠定基础的论述，提炼统摄两方面的观点。","origin":"逐题标记"}]},"国考 2025 地市级 行测#66":{"stem":"张某8：00开车从A地出发，在A、B两地之间往返行驶。8：30第一次到达A、B之间的C点时加速30%继续行\n驶，并于9：00第二次到达C点。问AC距离是BC距离的多少倍？","options":["","","",""],"answer":"C","analysis":"66. 正确答案：C\n解析：\n设张某出发时的速度为v，8：00从A地出发，8：30到达C点，则AC间的路程共用时30分钟。根据公式：路程=速度×\n时间，则AC距离为30v。8：30到达C点后，加速30%继续行驶，并于9：00第二次到达C点。则可知张某在BC间往\n返共用时30分钟，即单程用时15分钟，速度变为1.3v，则BC距离为            。故AC距离是BC距离的\n          倍。\n\n故正确答案为C。\n【考点】\n行程问题-其他","figs":["31f401e91aef8d11365d.pdf#11"],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-63c1c0bb51332b7d","label":"匀速行程中路程等于速度乘以时间","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"路程=速度×","why":"用两段各自的速度和用时表示路程，再求路程之比。","origin":"逐题标记"},{"id":"s-a678755b344c536e","label":"计算行程、相遇和追及","catalog_id":"M03","type":null,"role":"直接考查","field":"answer","quote":"返共用时30分钟，即单程用时15分钟","why":"识别两次经过C点之间的往返行程，将往返用时折为单程用时，并结合提速幅度求路程比。","origin":"逐题标记"}]},"国考 2025 地市级 行测#67":{"stem":"甲、乙、丙、丁四个部门共有210名员工，且甲部门员工数比丁部门多10人。现乙部门调动20名员工到丙部门且\n其剩余员工并入丁部门后，甲、丙、丁三个部门的员工数之比为3：3：4。问原乙部门有多少名员工？","options":["41","46","51","56"],"answer":"C","analysis":"67. 正确答案：C\n解析：\n方法一：调动后，甲、丙、丁三个部门的员工数分别为                   名、63名、210-63-63=84名。则调动\n\n前，甲、丙、丁三个部门的员工数分别为63名、63-20=43名、63-10=53名，原乙部门有210-63-43-53=51名员工。\n\n方法二：调动后，甲、丁两个部门的员工数分别为                   名、             名。则调动前，\n\n甲、丁两个部门的员工数分别为63名、63-10=53名，可知乙部门并入丁部门的员工数为84-53=31名，原乙部门有\n20+31=51名员工。\n故正确答案为C。\n【考点】\n\n和差倍比问题","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-4f0ccba171d29d0b","label":"按比例分配时各部分等于总量乘以该部分份数占比","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"甲、丙、丁三个部门的员工数之比为3：3：4","why":"调动前后员工总数相同，可用调动后的比例和总人数确定各部门人数。","origin":"逐题标记"},{"id":"s-d968fce424f6218d","label":"将和差倍比关系转为方程","catalog_id":"M01","type":null,"role":"直接考查","field":"question","quote":"甲部门员工数比丁部门多10人","why":"结合人数比和总和确定调动后人数，再用原有人数差及转入人数建立等量关系。","origin":"逐题标记"}]},"国考 2025 地市级 行测#68":{"stem":"化工商店出售200千克某种试剂，前60千克打2折出售，之后60千克打5折出售，剩余部分原价出售。以下坐标图\n中，最能准确反映该试剂销量和销售收入之间关系的是：","options":["","","",""],"answer":"A","analysis":"68. 正确答案：A\n解析：\n根据题意可知，销量分为三段：前60千克、之后60千克和剩余的200-（60+60）=80千克，相对应的收入也分为三\n段：打2折、打5折和原价，排除B、C两项。出售60千克该种试剂打2折的收入一定低于打5折的收入，排除D项。\n故正确答案为A。\n【考点】\n经济利润问题,代入排除法","figs":["31f401e91aef8d11365d.pdf#11","31f401e91aef8d11365d.pdf#12"],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-7efa2cd90442f578","label":"打几折表示按原价的十分之几出售","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"前60千克打2折出售，之后60千克打5折出售，剩余部分原价出售","why":"将折扣换算为原价的比例后，可比较三个销量区间的实际单价。","origin":"逐题标记","originalId":"k-e9e779b4e01c1c15"},{"id":"k-a8ceef62476bb9dd","label":"分段定价下累计收入图像在各段的斜率等于该段单价","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"出售60千克该种试剂打2折的收入一定低于打5折的收入","why":"相同销量增量对应的收入增量随单价升高而增大，各段斜率因此依次增大。","origin":"逐题标记"},{"id":"s-55b69f4a0862f7f1","label":"根据分段单价判断累计收入图像","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"最能准确反映该试剂销量和销售收入之间关系的是","why":"定位分段点并比较各段斜率，据此识别符合条件的折线。","origin":"逐题标记","originalId":"s-7566f92c41fe9b36"}]},"国考 2025 地市级 行测#69":{"stem":"某单位65名职工中，拥有甲、乙、丙三项认证中至少一项的职工正好占80%，没有甲认证的职工与有乙认证的职\n工人数一样多，仅有丙认证的职工有3人，三项认证都有的职工有6人，问有多少人仅拥有甲、乙两项认证？","options":["10","13","16","19"],"answer":"A","analysis":"69. 正确答案：A\n解析：\n根据题意，该单位没有甲、乙、丙三项认证中任何一项的职工人数为65×（1-80%）=13人。如图所示，设仅有甲、\n乙两项认证的人数为x人，仅有乙、丙两项认证的人数为y人，仅有乙认证的人数为z人。则没有甲认证的职工人数为\n（z+y+3+13）人，有乙认证的职工人数为（z+y+x+6）人，根据题意可得：z+y+3+13=z+y+x+6，解得x=10，即仅\n有甲、乙两项认证的人数为10人。\n\n\n\n\n故正确答案为A。\n【考点】\n三集合","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-2855a7e496b811b6","label":"集合人数等于其所包含的各互斥区域人数之和","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"（z+y+3+13）人，有乙认证的职工人数为（z+y+x+6）人","why":"将两组人分别拆成互不重叠的区域后，可按区域求和并找出两组的共有项。","origin":"逐题标记"},{"id":"s-36bcdccc44445c07","label":"用容斥计算重叠人数","catalog_id":"M07","type":null,"role":"直接考查","field":"answer","quote":"z+y+3+13=z+y+x+6","why":"先由覆盖比例求三项均无的人数，再按三集合区域列出人数等式并消去共有项。","origin":"逐题标记"}]},"国考 2025 地市级 行测#70":{"stem":"某竞赛由5道次序固定的判断题组成，参赛者起始为0分，每答对1题加1分，每答错1题扣1分。小王作答了所有\n试题，答完每道题时当前的得分都不低于1分。问他的答题情况有多少种不同的可能？","options":["7","6","4","3"],"answer":"B","analysis":"70. 正确答案：B\n解析：\n根据题干“答完每道题时当前的得分都不低于1分”可知，第一题和第二题均答对，第三题分情况讨论：\n①第三题答对，此时有3分，第四题和第五题不论是答对还是答错，均能保证答完每道题时当前的得分都不低于1\n分，故第四题和第五题答题情况均为2种，分步用乘法，有2×2=4种情况；\n②第三题答错，此时还剩1分，所以第四题必须答对，第四题答对后有2分，则第五题不论答对还是答错均满足题干\n条件，有2种情况。\n分类用加法，即共有4+2=6种情况。\n故正确答案为B。\n【考点】\n基础排列组合","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-63c2d85fb3976c99","label":"分类加法计数原理与分步乘法计数原理","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"分类用加法","why":"互斥情形的方案数相加，同一情形中各步的可选数可按乘法合计。","origin":"逐题标记"},{"id":"s-c0f6c7e3ae9d902e","label":"按条件分类计数与排列组合","catalog_id":"M05","type":null,"role":"直接考查","field":"answer","quote":"第一题和第二题均答对，第三题分情况讨论","why":"根据逐题分数下限确定强制选择，并按后续分支统计合法序列。","origin":"逐题标记"}]},"国考 2025 地市级 行测#71":{"stem":"某种机械由3个A模块和2个B模块组成。甲车间每天可生产6个A模块或3个B模块，乙车间每天可生产1个A模块或\n2个B模块。现两车间合作生产40台该机械所需模块，问至少需要多少天？","options":["24","26","28","30"],"answer":"C","analysis":"71. 正确答案：C\n解析：\n要使所需时间最少，则让两个车间分别生产相对效率更高的模块。甲车间相对于乙车间生产A模块的效率为                  ，\n\n生产B模块的相对效率为       ，比较发现，甲车间生产A模块的相对效率更高，故先由甲车间生产A模块，乙车间\n\n生产B模块。甲车间生产A模块需要           天，此时乙车间已生产B模块2×20=40个，还剩40×2-40=40个B模块\n\n由两车间共同生产，需要         天，故至少需要20+8=28天。\n\n故正确答案为C。\n【考点】\n统筹规划问题,给具体单位型","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-d3bcd8051f933120","label":"两种生产任务按相对生产效率分工可减少总工期","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"要使所需时间最少，则让两个车间分别生产相对效率更高的模块","why":"比较两车间在两种任务上的效率之比，可确定优先分工，一类任务做完后再调配产能。","origin":"逐题标记"},{"id":"s-4d945e4b584e20e6","label":"比较相对效率安排分工并计算最短工期","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"甲车间生产A模块的相对效率更高，故先由甲车间生产A模块，乙车间","why":"先按相对效率分工并同步计算产量，再用合并产能计算完成剩余任务所需的时间。","origin":"逐题标记","originalId":"s-7ecb2931866ce7d4"}]},"国考 2025 地市级 行测#72":{"stem":"张、王、李、赵4人的平均年龄为28岁，张、王的年龄之和比李大25岁，李、赵的年龄之和比张大27岁。已知张\n比王大2岁，问他们4人中年龄最大的比最小的大几岁？","options":["5","6","3","4"],"answer":"B","analysis":"72. 正确答案：B\n解析：\n\n根据题意可列方程组：                        ，解得：王=27，张=29，李=31，赵=25。\n\n\n因此4人中年龄最大的李（31岁）比最小的赵（25岁）大31-25=6岁。\n故正确答案为B。\n【考点】\n年龄问题,和差倍比问题","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-dcb95eea17288368","label":"数据总和等于算术平均数乘以数据个数","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"4人的平均年龄为28岁","why":"将平均年龄和人数换算为四人年龄之和，得到一条等量关系。","origin":"逐题标记"},{"id":"s-d968fce424f6218d","label":"将和差倍比关系转为方程","catalog_id":"M01","type":null,"role":"直接考查","field":"question","quote":"张、王的年龄之和比李大25岁，李、赵的年龄之和比张大27岁","why":"把总年龄和各年龄和差写成方程组，求出年龄并比较极值。","origin":"逐题标记"}]},"国考 2025 地市级 行测#73":{"stem":"甲船在A港正东n海里，乙船在A港正南   海里，两船相距120海里，同时出发向A港匀速行驶。已知乙船的速\n度是甲船的    倍，比甲船早3小时到A港。问甲船的速度是多少海里/小时？","options":["10","15","",""],"answer":"A","analysis":"73. 正确答案：A\n解析：\n根据题意可知，                ，解得n=60，则甲船距离A港60海里，乙船距离A港       海里。已知乙船的速\n\n度是甲船的     倍，则              ，根据乙船比甲船早3小时到A港，可列式：\n\n，即           ，解得       。\n\n故正确答案为A。\n【考点】\n普通行程","figs":["31f401e91aef8d11365d.pdf#13"],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-pyth","label":"勾股定理","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"甲船在A港正东n海里，乙船在A港正南","why":"正东与正南方向垂直，两船到港距离为直角边，船间距离为斜边。","origin":"逐题标记"},{"id":"k-63c1c0bb51332b7d","label":"匀速行程中路程等于速度乘以时间","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"同时出发向A港匀速行驶","why":"用航程除以速度分别表示两船的用时，进而利用到港时间差。","origin":"逐题标记"},{"id":"s-ac5c371e800baa75","label":"按几何关系列式计算","catalog_id":"M09","type":null,"role":"解题依据","field":"question","quote":"两船相距120海里","why":"把两船与港口的方位转化为直角三角形，按边长关系列式求两段航程。","origin":"逐题标记"},{"id":"s-a678755b344c536e","label":"计算行程、相遇和追及","catalog_id":"M03","type":null,"role":"直接考查","field":"answer","quote":"根据乙船比甲船早3小时到A港，可列式","why":"结合速度倍数表示两船各自的航行时间，再按时间差列式求速度。","origin":"逐题标记"}]},"国考 2025 地市级 行测#74":{"stem":"小王计划在7天假期自学甲、乙两门在线课程，每门课程需要连学2整天。如在所有可能的安排中随机选择1种，\n不用学习的3天均不相邻的概率为：","options":["","","",""],"answer":"D","analysis":"74. 正确答案：D\n解析：\n\n根据公式：概率                ，分析如下：\n\n甲、乙两门课程均需要占用相邻的2天，可用捆绑法，先将每门课程所占用的2天分别捆绑，再将这2个捆绑体和其它\n3天进行排序。因每“天”均相同，不用排序，而两门课程不同，需要排序，则总情况数                  种情况；\n根据题意，不用学习的3天均不相邻，可用插空法，优先安排学习两门课程的时间，因两门课程不同，对两门课程进\n行排序有       种情况，再将剩余3天插入两门课程安排好之后形成的3个空隙，因每“天”均相同不用再排序，有\n      种情况，故满足要求的情况数=2×1=2种情况。\n综上，所求概率            。\n\n故正确答案为D。\n【考点】\n给情况求概率","figs":["31f401e91aef8d11365d.pdf#13"],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-442e48c9c67c3602","label":"古典概型中事件概率等于有利结果数除以等可能结果总数","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"如在所有可能的安排中随机选择1种","why":"各合法安排等可能，可用符合休息日限制的安排数除以合法安排总数。","origin":"逐题标记"},{"id":"s-fa618aa0e5554dde","label":"计算事件概率","catalog_id":"M06","type":null,"role":"直接考查","field":"question","quote":"不用学习的3天均不相邻的概率为：","why":"需要分别统计全部合法安排和满足不相邻条件的安排，再求比值。","origin":"逐题标记"},{"id":"s-c0f6c7e3ae9d902e","label":"用捆绑法统计相邻元素的排列数","catalog_id":null,"type":null,"role":"解题依据","field":"answer","quote":"先将每门课程所占用的2天分别捆绑","why":"将每门课程的连续两天视作一个整体，保留甲、乙课程的区别，以统计全部合法安排。","origin":"逐题标记","originalId":"s-7943d9207c8f0926","additionalEvidence":[{"id":"s-adc0f8e8af7f97bb","label":"用插空法统计互不相邻元素的排列数","catalog_id":null,"type":null,"role":"解题依据","field":"answer","quote":"再将剩余3天插入两门课程安排好之后形成的3个空隙","why":"先排课程块，再在各空隙中至多放入一个休息日，以满足休息日互不相邻的条件。","origin":"逐题标记"}]}]},"国考 2025 地市级 行测#75":{"stem":"一个容器的下部分为高12厘米的倒立圆锥体，上部分为圆柱体，且圆锥和圆柱的底面半径相等。现匀速向容器中\n注入水，1分钟后液面高6厘米，又过30分钟后注满。问整个容器的高度为多少厘米？","options":["22","22.5","23","23.5"],"answer":"D","analysis":"75. 正确答案：D\n解析：\n根据题意，该容器由圆柱体和倒立圆锥体组成，注入水后先注满圆锥体，再注满圆柱体。根据几何等比例放缩性\n\n质，在立体几何中，体积比等于相似比的立方，根据题意可知，                                  ，则相似比为\n\n1：2，故                          ，因为注入水的流速相同，则                     ，故注满\n\n圆锥体需要用时8分钟；水注满圆锥体后，再注满圆柱体需要用时1+30-8=23分钟，因圆锥体和圆柱体的底面半径相\n等，则二者的底面积相等，设圆锥体和圆柱体的底面积为S，圆柱体的高为              厘米，根据公式：           ，\n\n        ，可得                                     ，解得          厘米，则整个容器\n\n的高度为12+11.5=23.5厘米。\n故正确答案为D。\n【考点】\n立体几何,立体图形（新）,相似图形（新）","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-5dc6f7bab5ea7821","label":"相似立体的体积比等于线性相似比的立方","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"在立体几何中，体积比等于相似比的立方","why":"锥段内的水体与整个圆锥相似，可由水深与锥高之比确定体积比。","origin":"逐题标记"},{"id":"k-140ee985f068dbf7","label":"恒定体积流量下，注入体积与注水时间成正比","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"注入水，1分钟后液面高6厘米，又过30分钟后注满。","why":"同一流量下，锥段和柱段的注水时间比可换算为各段的体积比。","origin":"逐题标记"},{"id":"k-d73cb19a60baeb11","label":"圆柱体积等于底面积乘高，圆锥体积等于底面积乘高的三分之一","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"则二者的底面积相等","why":"两段底面积相同，可代入各自的体积公式，将体积比转化为高度关系。","origin":"逐题标记"},{"id":"s-ac5c371e800baa75","label":"按几何关系列式计算","catalog_id":"M09","type":null,"role":"直接考查","field":"answer","quote":"注入水后先注满圆锥体，再注满圆柱体。","why":"先按相似关系求锥段注满时间，再用两段的体积关系列式求柱高，最后合并两段高度。","origin":"逐题标记"}]},"国考 2025 地市级 行测#76":{"stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","options":["A","B","C","D"],"answer":"D","analysis":"76. 正确答案：D\n解析：\n元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干图形封闭面较多，优先考虑数面，但整体数面\n无规律。继续观察发现，题干图形均明显存在最大面，且最大面均为轴对称图形，只有D项符合。\n\n故正确答案为D。\n【考点】\n最大/小面","figs":["31f401e91aef8d11365d.pdf#13"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-449c824eeb0b7f3d","label":"找出最大封闭区域并判断其轴对称性","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"题干图形均明显存在最大面，且最大面均为轴对称图形","why":"需要先定位面积最大的封闭区域，再判断该区域的对称性。","origin":"逐题标记","originalId":"s-9cc4cbb853cbe1c2"}]},"国考 2025 地市级 行测#77":{"stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","options":["A","B","C","D"],"answer":"D","analysis":"77. 正确答案：D\n解析：\n元素组成相同，优先考虑位置规律。如下图所示，在正方形外框上标记8个位置，观察发现，圆形每次顺时针移动3\n步，方块每次逆时针移动3步，只有D项符合。\n\n\n\n\n故正确答案为D。\n【考点】\n常规类平移","figs":["31f401e91aef8d11365d.pdf#14"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-449334f5aeb5ea84","label":"追踪平移旋转翻转","catalog_id":"G01","type":null,"role":"直接考查","field":"answer","quote":"圆形每次顺时针移动3\n步，方块每次逆时针移动3步","why":"需要在同一组边框位置上分别推演两个元素的移动。","origin":"逐题标记"}]},"国考 2025 地市级 行测#78":{"stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","options":["A","B","C","D"],"answer":"C","analysis":"78. 正确答案：C\n解析：\n观察题干图形，整体无规律，通过相邻比较发现，图1和图2只有第一行黑块位置不同（第一行黑白块颜色互换），\n其他四行黑块位置相同；图2和图3只有第二行黑块位置不同（第二行黑白块颜色互换），其他四行黑块位置相同；\n图3和图4只有第三行黑块位置不同（第三行黑白块颜色互换），其他四行黑块位置相同；图4和图5只有第四行黑块\n位置不同（第四行黑白块颜色互换），其他四行黑块位置相同，以此类推，？处应该选择一个和图5只有第五行黑块\n位置不同（第五行黑白块颜色互换），其他四行黑块位置相同的图形，只有C项符合。\n故正确答案为C。\n【考点】\n相邻比较,黑白块类-相邻比较","figs":["31f401e91aef8d11365d.pdf#14"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-49e530b3a2c0cd4c","label":"逐行比较相邻图形的黑白块变化","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"图1和图2只有第一行黑块位置不同（第一行黑白块颜色互换）","why":"逐行对照可以定位每一步发生颜色互换的行，并推断下一次变化。","origin":"逐题标记","originalId":"s-a65e5571ef659699"}]},"国考 2025 地市级 行测#79":{"stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","options":["A","B","C","D"],"answer":"D","analysis":"79. 正确答案：D\n解析：\n元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干第一组图形均是由3条线段组成的两条折线相交\n在一起，且相交的位置均在折线的一端；第二组图形中的前两幅图形均是由3条线段组成的两条折线相交在一起，且\n相交的位置均在折线的中间线段处，只有D项符合。\n\n\n\n\n故正确答案为D。\n\n【考点】\n数量+属性/位置等","figs":["31f401e91aef8d11365d.pdf#14","31f401e91aef8d11365d.pdf#15"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-73b5da0d39715bb4","label":"辨认图形接触、相交和公共边","catalog_id":"G05","type":null,"role":"直接考查","field":"answer","quote":"相交的位置均在折线的中间线段处","why":"需要分辨两条三段折线，并定位它们的交点所在的线段。","origin":"逐题标记"}]},"国考 2025 地市级 行测#80":{"stem":"左边为给定的多面体，现用经P、Q、R三点的平面对其进行切割，问哪个选项是其切面？","options":["A","B","C","D"],"answer":"A","analysis":"80. 正确答案：A\n解析：\n本题考查截面图。根据平面公理“过不在一条直线上的三点，有且只有一个平面”可以得出，经过P、Q、R三点可以确\n定的唯一切面（即截面），即为A项，如下图所示：\n\n\n\n\n故正确答案为A。\n【考点】\n空间类-截面图","figs":["31f401e91aef8d11365d.pdf#15"],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-35e750c2c76ce267","label":"不共线的三点确定唯一平面","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"过不在一条直线上的三点，有且只有一个平面","why":"三个给定点共同确定用于截取多面体的平面。","origin":"逐题标记"},{"id":"s-b675a81beafb818e","label":"由视图截面或拼块还原立体","catalog_id":"G07","type":null,"role":"直接考查","field":"question","quote":"现用经P、Q、R三点的平面对其进行切割，问哪个选项是其切面？","why":"需要在立体图上追踪切割平面经过的各个面，判断截面轮廓。","origin":"逐题标记"}]},"国考 2025 地市级 行测#81":{"stem":"下图为4个黑色、8个白色正方体粘接成的长方体，问哪一项可能是其正确的外表面展开图?","options":["A","B","C","D"],"answer":"D","analysis":"81. 正确答案：D\n解析：\n本题为空间重构题，可以通过公共边进行判断，由构成直角的两条边为公共边可知，公共边两侧对应的黑白块颜色\n应相同，逐一进行分析。\n\n\n\n\nA项：公共边①和②两侧黑白块颜色不同，选项与题干不一致，排除；\nB项：公共边①和②两侧黑白块颜色不同，选项与题干不一致，排除；\nC项：公共边①和②、③和④两侧黑白块颜色不同，选项与题干不一致，排除；\nD项：公共边①和②、③和④、⑤和⑥两侧黑白块颜色均相同，选项与题干一致，当选。\n故正确答案为D。\n【考点】\n六面体-公共边/公共点","figs":["31f401e91aef8d11365d.pdf#15"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-afb05982fcc9a31c","label":"由展开图判断邻面、对面和公共边","catalog_id":"G06","type":null,"role":"直接考查","field":"answer","quote":"公共边两侧对应的黑白块颜色\n应相同","why":"需要先配对折合后的公共边，再核对同一小正方体在相邻外表面上的颜色。","origin":"逐题标记"}]},"国考 2025 地市级 行测#82":{"stem":"左边为15个白色和3个灰色正方体组合而成多面体的正、反两面直观图，其可以由①、②和③三个多面体组合而\n成，问哪一项能填入问号处？","options":["A","B","C","D"],"answer":"B","analysis":"82. 正确答案：B\n解析：\n本题考查立体拼合。题干立体图形可以由①、②以及B项旋转后拼合而成，如下图所示：\n\n故正确答案为B。\n【考点】\n立体拼合-相同小方块类","figs":["31f401e91aef8d11365d.pdf#15"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-b675a81beafb818e","label":"由视图截面或拼块还原立体","catalog_id":"G07","type":null,"role":"直接考查","field":"question","quote":"其可以由①、②和③三个多面体组合而\n成","why":"需要旋转并摆放拼块，使拼合后的形状和灰色方块位置与两个视图一致。","origin":"逐题标记"}]},"国考 2025 地市级 行测#83":{"stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","options":["①②⑥，③④⑤","①②④，③⑤⑥","①③⑥，②④⑤","①④⑤，②③⑥"],"answer":"B","analysis":"83. 正确答案：B\n解析：\n本题为分组分类题目。元素组成相同，且无明显位置规律，考虑属性规律。观察发现，题干图形均由黑球和白球构\n成，且黑球分布较为规整，考虑对称性。题干图形的黑球部分均为轴对称图形，且图①②④的对称轴均经过四个黑\n球，图③⑤⑥的对称轴均经过两个黑球，即图①②④为一组，图③⑤⑥为一组。\n\n\n\n\n故正确答案为B。\n【考点】\n对称轴与图形的关系,黑白块类-对称性","figs":["31f401e91aef8d11365d.pdf#16"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-c96dc3b8ef59659c","label":"定位对称轴并计数轴上的图形元素","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"图①②④的对称轴均经过四个黑\n球，图③⑤⑥的对称轴均经过两个黑球","why":"需要先定位黑球分布的对称轴，再用轴上的黑球数量分类。","origin":"逐题标记","originalId":"s-1f659180e73a6658"}]},"国考 2025 地市级 行测#84":{"stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","options":["①②⑥，③④⑤","①③⑥，②④⑤","①②③，④⑤⑥","①②⑤，③④⑥"],"answer":"A","analysis":"84. 正确答案：A\n解析：\n本题为分组分类题目。题干每幅图形均由多个面和一个黑块拼接而成，考虑图形间关系。观察发现，图①②⑥中黑\n块与图形外框均有1条公共边，图③④⑤中黑块与图形外框均有0条公共边，即图①②⑥为一组，图③④⑤为一组。\n故正确答案为A。\n【考点】\n相交于线","figs":["31f401e91aef8d11365d.pdf#16"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-73b5da0d39715bb4","label":"辨认图形接触、相交和公共边","catalog_id":"G05","type":null,"role":"直接考查","field":"answer","quote":"黑块与图形外框均有0条公共边","why":"依据黑块边缘是否与拼合图形的外轮廓共边来分类。","origin":"逐题标记"}]},"国考 2025 地市级 行测#85":{"stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","options":["①②⑥，③④⑤","①③④，②⑤⑥","①③⑤，②④⑥","①④⑥，②③⑤"],"answer":"B","analysis":"85. 正确答案：B\n解析：\n本题为分组分类题目。元素组成不同，且无明显属性规律，考虑数量规律。观察发现，图③为多端点图形，考虑笔\n画数。图①③④均为一笔画图形，图②⑤⑥均为两笔画图形。即图①③④为一组，图②⑤⑥为一组。\n故正确答案为B。\n【考点】\n笔画数","figs":["31f401e91aef8d11365d.pdf#16","31f401e91aef8d11365d.pdf#17"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-c96dc3b8ef59659c","label":"计数区域、交点与笔画","catalog_id":"G03","type":null,"role":"直接考查","field":"answer","quote":"图①③④均为一笔画图形，图②⑤⑥均为两笔画图形。","why":"按内部线条的连接情况判断最少笔画数，并以此分组。","origin":"逐题标记"}]},"国考 2025 地市级 行测#86":{"stem":"土地监测是利用遥感、遥测技术，对一个国家或地区土地利用状况的动态变化进行定期或不定期的监视和测定，\n目的在于为国家和地区有关部门提供准确的土地利用变化情况，及时进行土地利用数据更新与对比分析，以便编制\n土地利用变化图解等。\n根据上述定义，下列属于土地监测的是:","options":["通过量化多时相遥感图像空间域、时间域、光谱域的耦合特征，获得土地变化的类型、位置和数量","利用定期现场踏勘的方式标绘各土地使用单位及各类型土地的界线，对变化的地物界线作出修正","通过某地区土地权属变更资料的分析，梳理该地区土地所有权、使用权的变化，以及土地纠纷调解情况","利用植被具有红光强吸收特点，通过遥感设备监测植被的生长状态，并绘制植被的生长周期图"],"answer":"A","analysis":"86. 正确答案：A\n解析：\n第一步：找出定义关键词。\n“利用遥感、遥测技术，对一个国家或地区土地利用状况的动态变化进行定期或不定期的监视和测定”、“目的在于为\n国家和地区有关部门提供准确的土地利用变化情况，及时进行土地利用数据更新与对比分析，以便编制土地利用变\n化图解等”。\n\n第二步：逐一分析选项。\nA项：该项说的是通过遥感技术获得了土地变化的类型、位置和数量，即通过遥感技术获得土地利用情况，符合“利\n用遥感、遥测技术，对一个国家或地区土地利用状况的动态变化进行定期或不定期的监视和测定”、“目的在于为国家\n和地区有关部门提供准确的土地利用变化情况，及时进行土地利用数据更新与对比分析，以便编制土地利用变化图\n解等”，符合定义，当选；\nB项：该项说的是定期现场踏勘土地使用单位及各类型土地的界线，没有提及是否运用了遥感、遥测技术，也未涉及\n土地利用情况，不符合“利用遥感、遥测技术，对一个国家或地区土地利用状况的动态变化进行定期或不定期的监视\n和测定”、“目的在于为国家和地区有关部门提供准确的土地利用变化情况，及时进行土地利用数据更新与对比分析，\n以便编制土地利用变化图解等”，不符合定义，排除；\nC项：该项说的是土地的权属情况，未涉及土地利用情况，也未涉及遥感、遥测技术，不符合“利用遥感、遥测技\n术，对一个国家或地区土地利用状况的动态变化进行定期或不定期的监视和测定”、“目的在于为国家和地区有关部门\n提供准确的土地利用变化情况，及时进行土地利用数据更新与对比分析，以便编制土地利用变化图解等”，不符合定\n义，排除；\nD项：该项说的是通过遥感设备监测植被的生长状态，并绘制植被的生长周期图，涉及的是植被情况，不是土地利用\n情况，不符合“利用遥感、遥测技术，对一个国家或地区土地利用状况的动态变化进行定期或不定期的监视和测\n定”、“目的在于为国家和地区有关部门提供准确的土地利用变化情况，及时进行土地利用数据更新与对比分析，以便\n编制土地利用变化图解等”，不符合定义，排除。\n故正确答案为A。\n【考点】\n定义-方式目的","figs":[],"state":"已标记","notes":[],"domains":["地理","科技"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"利用遥感、遥测技术，对一个国家或地区土地利用状况的动态变化进行定期或不定期的监视和测定","why":"需同时核对监测手段和监测对象。","origin":"逐题标记"}]},"国考 2025 地市级 行测#87":{"stem":"主体间性是指人对他人意图的判断与推测。主体间性有不同的级别，一级主体间性即人对另一个人意图的判断与\n推测，二级主体间性即人对另一人关于其他人意图的判断与推测的认知的认识。\n根据上述定义，下列体现了二级主体间性的是：","options":["小明饿了，去问妈妈饭做好没有，妈妈说爸爸正在做","老师知道学生们不喜欢做作业，周五就在班级群里通知本周末不留作业","小王知道老板爱挑毛病，每次提交的总结都得仔细检查好几遍","小花看见妈妈冲爸爸使了个眼色后，爸爸尴尬地放下酒杯，小花偷偷地笑了"],"answer":"D","analysis":"87. 正确答案：D\n解析：\n第一步：找出定义关键词。\n主体间性：“人对他人意图的判断与推测”；\n一级主体间性：“人对另一个人意图的判断与推测”；\n二级主体间性：“人对另一人关于其他人意图的判断与推测的认知的认识”。\n第二步：逐一分析选项。\nA项：妈妈说爸爸正在做饭，做饭是客观事实而非某人的意图，所以该项不存在对他人意图的判断与推测，不符\n合“人对另一人关于其他人意图的判断与推测的认知的认识”，不符合“二级主体间性”定义，排除；\nB项：老师知道学生们不喜欢做作业，说明老师对学生的意图有所判断，但未体现出第三个主体，即没有体现学生对\n其他人意图的判断与推测，不符合“人对另一人关于其他人意图的判断与推测的认知的认识”，不符合“二级主体间\n性”定义，排除；\nC项：小王知道老板爱挑毛病，说明小王对老板的意图有所判断，但未体现出第三个主体，即没有体现老板对其他人\n意图的判断与推测，不符合“人对另一人关于其他人意图的判断与推测的认知的认识”，不符合“二级主体间性”定义，\n排除；\nD项：妈妈冲爸爸使眼色后，爸爸尴尬地放下酒杯，说明爸爸对妈妈的意图有所判断，而小花看到这些偷偷笑了，说\n明小花认识到了爸爸知道妈妈的意图，符合“人对另一人关于其他人意图的判断与推测的认知的认识”，符合“二级主\n体间性”定义，当选。\n故正确答案为D。\n【考点】\n常规问法","figs":[],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"answer","quote":"人对另一人关于其他人意图的判断与推测的认知的认识","why":"需逐层核对谁在推测谁的意图，以及谁察觉到了这一推测。","origin":"逐题标记"}]},"国考 2025 地市级 行测#88":{"stem":"回应型预算要求政府基于与人民的民主协商作出预算决策，相关责任部门应当及时反应并积极回复人民的质疑和\n诉求。\n根据上述定义，下列属于回应型预算的是：","options":["甲国突发大规模严重旱情，财政部门从中央及各级政府应急预算中，通过多种财政政策安排，保障应急救援经费","乙省是地质灾害高发地区，年初该省编制《乙省地质灾害应急中心XX年度部门预算公开说明》并在官网上发布","丙市在年初将上一年度的地方预算执行情况在官网进行公布，诚邀广大市民和社会公众踊跃监督并提出意见","丁区实行预算听证制度，对与公共服务和社会民生相关的重大支出项目开展听证，并就意见和建议进行书面答复"],"answer":"D","analysis":"88. 正确答案：D\n解析：\n第一步：找出定义关键词。\n“政府基于与人民的民主协商作出预算决策”、“相关责任部门及时反应并积极回复人民的质疑和诉求”。\n第二步：逐一分析选项。\nA项：甲国财政部门从应急预算中安排保障应急救援经费，只是在应对旱情时进行经费安排，未体现出基于与人民的\n民主协商作出预算决策，也没有涉及回复人民的质疑和诉求，不符合“政府基于与人民的民主协商作出预算决\n策”、“相关责任部门及时反应并积极回复人民的质疑和诉求”，不符合定义，排除；\n\nB项：乙省编制并发布预算公开说明，只是将预算情况公开，没有体现出基于与人民的民主协商作出预算决策以及回\n复人民的质疑和诉求，不符合“政府基于与人民的民主协商作出预算决策”、“相关责任部门及时反应并积极回复人民\n的质疑和诉求”，不符合定义，排除；\nC项：丙市是将上一年度的地方预算执行情况公布并邀请监督、提出意见，但这是对上一年度已执行情况的公开，并\n非作出预算决策的过程，不符合“政府基于与人民的民主协商作出预算决策”，不符合定义，排除；\nD项：丁区实行预算听证制度，开展听证意味着是与人民进行民主协商的过程，符合“政府基于与人民的民主协商作\n出预算决策”，对相关重大支出项目听取意见，并且就意见和建议进行书面答复，体现了相关责任部门及时反应并积\n极回复人民的质疑和诉求，符合“相关责任部门及时反应并积极回复人民的质疑和诉求”，符合定义，当选。\n故正确答案为D。\n【考点】\n单定义-其他句式","figs":[],"state":"已标记","notes":[],"domains":["公共管理"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"answer","quote":"“政府基于与人民的民主协商作出预算决策”、“相关责任部门及时反应并积极回复人民的质疑和诉求”","why":"需同时核对公众协商是否进入预算决策过程，以及责任部门是否回应公众意见。","origin":"逐题标记"}]},"国考 2025 地市级 行测#89":{"stem":"温度习服是指机体长期在高温或低温环境中，逐渐产生的对环境温度的耐受现象，包括热习服和冷习服。热习服\n是指机体长期生活或工作在炎热或高温环境后产生的适应性变化；冷习服是指机体长期暴露于寒冷环境后逐渐出现\n的适应性变化。\n根据上述定义，下列属于温度习服的是：","options":["长期接受滑雪训练的人都会穿着防水防风、透气保暖的滑雪服进行运动","生活在北极的因纽特人常表现出较高的基础代谢率以维持体温","生活在缺氧、干燥、紫外线照射强烈的高原地区的人，脸部呈现出“高原红”特征","在寒冷天气进行体育锻炼的人，倾向于增加热身时间以适应气温"],"answer":"B","analysis":"89. 正确答案：B\n解析：\n第一步：找出定义关键词。\n温度习服：“机体长期在高温或低温环境中”、“产生的对环境温度的耐受现象”；\n热习服：“机体长期生活或工作在炎热或高温环境”、“产生的适应性变化”；\n冷习服：“机体长期暴露于寒冷环境”、“逐渐出现的适应性变化”。\n第二步：逐一分析选项。\nA项：穿着防水防风、透气保暖的滑雪服，是为了滑雪时保暖，而不是身体本身形成的耐受，不符合“对环境温度的\n耐受现象”，不符合“温度习服”定义，排除；\nB项：因纽特人生活在北极，而北极地区的温度终年较低，符合“机体长期在高温或低温环境中”，因纽特人常表现出\n较高的基础代谢率以维持体温，符合“产生的对环境温度的耐受现象”，符合“温度习服”定义，当选；\nC项：高原地区的人，脸部呈现出“高原红”的特征，是因为缺氧、干燥、紫外线照射强烈，没有提到高原地区温度的\n影响，不符合“长期在高温或低温环境中”，不符合“温度习服”定义，排除；\nD项：增加热身时间以适应气温，是为了运动时避免伤害，而不是身体本身形成的耐受，不符合“对环境温度的耐受\n现象”，不符合“温度习服”定义，排除。\n故正确答案为B。\n【考点】\n常规问法","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"机体长期在高温或低温环境中，逐渐产生的对环境温度的耐受现象","why":"需核对长期温度暴露和机体自身的适应性变化。","origin":"逐题标记"}]},"国考 2025 地市级 行测#90":{"stem":"形象史学是指把形与象作为主要材料，用以研究历史的一门学问。具体来说，是指把传世的包括出土（水）的具\n有研究价值的石刻、陶塑、壁画、雕砖、铜玉、织绣、漆器、木器、绘画等历史实物、文本图像以及文化史迹作为\n主要研究对象，并结合传统文献来综合考察历史的一种新的史学研究模式。\n根据上述定义，下列属于形象史学研究范畴的是：","options":["结合《晋书》等史书，通过对吉林集安长川1号墓礼佛图主佛形象及莲花纹的考察，研究三燕文化对高句丽佛教产\n生的影响","通过对现存的汉画像石（汉代人雕刻在墓室、祠堂四壁的装饰石刻壁画）的实地考察，分析汉画像石的雕刻风格\n和雕刻技法","根据史诗《伊利亚特》的记载，找到特洛伊城的遗址，并在其中发掘出王冠、银瓶、短剑等大量器物","通过对二十世纪二三十年代齐白石、傅抱石等人具有代表性的国画作品进行研究，分析当时国画中所蕴含的思想\n意境"],"answer":"A","analysis":"90. 正确答案：A\n解析：\n第一步：找出定义关键词。\n“把传世的包括出土（水）的具有研究价值的石刻、陶塑、壁画、雕砖、铜玉、织绣、漆器、木器、绘画等历史实\n物、文本图像以及文化史迹作为主要研究对象”、“结合传统文献”、“综合考察历史”。\n第二步：逐一分析选项。\nA项：结合《晋书》等史书，符合“结合传统文献”，对吉林集安长川1号墓礼佛图主佛形象及莲花纹的考察，符合“把\n传世的包括出土（水）的具有研究价值的石刻、陶塑、壁画、雕砖、铜玉、织绣、漆器、木器、绘画等历史实物、\n文本图像以及文化史迹作为主要研究对象”，研究三燕文化对高句丽佛教产生的影响，符合“综合考察历史”，符合定\n义，当选；\nB项：只有对现存的汉画像石的实地考察，没有结合文献资料，不符合“结合传统文献”，分析汉画像石的雕刻风格和\n雕刻技法，不符合“综合考察历史”，不符合定义，排除；\nC项：根据史诗《伊利亚特》的记载，找到特洛伊城的遗址，目的是发掘出王冠、银瓶、短剑等大量器物，而不是结\n合出土的器物考察历史，不符合“把传世的包括出土（水）的具有研究价值的石刻、陶塑、壁画、雕砖、铜玉、织\n绣、漆器、木器、绘画等历史实物、文本图像以及文化史迹作为主要研究对象”、“综合考察历史”，不符合定义，排\n除；\nD项：只是对齐白石、傅抱石等人的国画作品进行研究，没有结合文献资料，不符合“结合传统文献”，分析当时国画\n中所蕴含的思想意境，不符合“综合考察历史”，不符合定义，排除。\n故正确答案为A。\n【考点】\n定义-方式目的","figs":[],"state":"已标记","notes":[],"domains":["历史"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"主要研究对象，并结合传统文献来综合考察历史","why":"需核对主要研究材料、传统文献的使用和研究目的。","origin":"逐题标记"}]},"国考 2025 地市级 行测#91":{"stem":"求证思维是指用自己掌握的知识和经验去验证某一结论的思维。转化思维是指在解决问题的过程中遇到障碍时，\n把问题转换成另一种形式，使问题变得更简单、更清晰。集中思维是指从许多资料中找出合乎逻辑的联系，从而导\n出一定的结论，或者对几种解决方案加以比较研究，进而导出一种解决办法。\n根据上述定义，下列说法正确的是：","options":["数学家根据自己所学，从多角度证明某一命题是否成立。这体现了求证思维","修建铁路时，工程师依据施工方案采用爆破的方法开山劈岭，完成线路铺设。这体现了集中思维","当发现改变滚珠形状无法减少轴承摩擦时，有人设计出使旋转轴呈悬浮状的空气轴承。这体现了集中思维","商家通过分析药店互联网化的不同方案，权衡利弊后最终选定线上线下相结合的模式。这体现了转化思维"],"answer":"A","analysis":"91. 正确答案：A\n解析：\n第一步：找出定义关键词。\n求证思维：“用自己掌握的知识和经验”、“去验证某一结论”；\n转化思维：“在解决问题的过程中遇到障碍时”、“把问题转换成另一种形式”、“使问题变得更简单、更清晰”；\n集中思维：“从许多资料中找出合乎逻辑的联系，从而导出一定的结论”、“对几种解决方案加以比较研究，进而导出\n一种解决办法”。\n第二步：逐一分析选项。\nA项：数学家根据自己所学，符合“用自己掌握的知识和经验”，从多角度证明某一命题是否成立，符合“去验证某一结\n论”，符合“求证思维”定义，说法正确，当选；\nB项：工程师依据施工方案完成一系列工作，其中施工方案属于明确的材料，不符合“从许多资料中找出合乎逻辑的\n联系，从而导出一定的结论”、“对几种解决方案加以比较研究，进而导出一种解决办法”，不符合“集中思维”定义，说\n法错误，排除；\nC项：针对遇到的问题设计出相应的解决方案，并未体现“从许多资料中找出合乎逻辑的联系，从而导出一定的结\n论”、“对几种解决方案加以比较研究，进而导出一种解决办法”，不符合“集中思维”定义，说法错误，排除；\nD项：商家通过分析药店互联网化的不同方案，最终选定线上线下相结合的模式，并未体现“在解决问题的过程中遇\n到障碍时”、“把问题转换成另一种形式”、“使问题变得更简单、更清晰”，不符合“转化思维”定义，说法错误，排除。\n故正确答案为A。\n【考点】\n特殊问法","figs":[],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"用自己掌握的知识和经验去验证某一结论的思维","why":"需提取案例实际执行的操作，再与对应定义的条件核对。","origin":"逐题标记"}]},"国考 2025 地市级 行测#92":{"stem":"自动投案是指犯罪事实或者犯罪嫌疑人未被司法机关发觉，或者虽被发觉，但犯罪嫌疑人尚未受到讯问、未被采\n取强制措施时，主动、直接向公安机关、人民检察院或者人民法院投案。\n根据上述定义，下列不属于自动投案的是：","options":["甲实施多起电信诈骗，获利十余万元，在公安机关进行的一次隐患排查入户走访中，发现甲形迹可疑，经盘问甲\n主动交代了自己的罪行","乙致人重伤后潜逃，在公安机关经侦查确认乙为该案的犯罪嫌疑人时，乙正因酒后驾驶被行政拘留，经公安机关\n讯问后，乙交代了自己的罪行","丙多次挪用公款，其父母发现异常后，多次规劝其投案自首无效，直至单位发现款项异常开始查账后，丙才到公\n安机关交代自己的罪行","丁因入室盗窃被判处有期徒刑，在服刑期间，丁主动向公安机关交代自己系公安机关久未破获的“7·26”走私案的主\n谋之一"],"answer":"B","analysis":"92. 正确答案：B\n解析：\n第一步：找出定义关键词。\n“犯罪事实或者犯罪嫌疑人未被司法机关发觉，或者虽被发觉，但犯罪嫌疑人尚未受到讯问、未被采取强制措施\n时”、“主动、直接向公安机关、人民检察院或者人民法院投案”。\n第二步：逐一分析选项。\nA项：甲实施多起电信诈骗，公安机关在入户走访中发现甲形迹可疑，对甲进行盘问，符合“犯罪事实或者犯罪嫌疑\n人未被司法机关发觉，或者虽被发觉，但犯罪嫌疑人尚未受到讯问、未被采取强制措施时”，甲主动交代了自己的罪\n行，符合“主动、直接向公安机关、人民检察院或者人民法院投案”，符合定义，排除；\nB项：乙致人重伤后潜逃且被公安机关确认为该案的犯罪嫌疑人，后因酒后驾驶被行政拘留，经公安机关讯问后交代\n了自己的罪行，不符合“犯罪事实或者犯罪嫌疑人未被司法机关发觉，或者虽被发觉，但犯罪嫌疑人尚未受到讯问、\n未被采取强制措施时”，不符合定义，当选；\nC项：丙多次挪用公款，其所在单位发现款项异常开始查账，符合“犯罪事实或者犯罪嫌疑人未被司法机关发觉，或\n者虽被发觉，但犯罪嫌疑人尚未受到讯问、未被采取强制措施时”，丙到公安机关交代自己的罪行，符合“主动、直接\n向公安机关、人民检察院或者人民法院投案”，符合定义，排除；\nD项：丁在入室盗窃服刑期间，主动向公安机关交代自己系公安机关久未破获的“7·26”走私案的主谋之一，符合“犯罪\n事实或者犯罪嫌疑人未被司法机关发觉，或者虽被发觉，但犯罪嫌疑人尚未受到讯问、未被采取强制措施时”、“主\n动、直接向公安机关、人民检察院或者人民法院投案”，符合定义，排除。\n本题为选非题，故正确答案为B。\n【考点】\n大前提","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"但犯罪嫌疑人尚未受到讯问","why":"以所交代的罪行为单位，核对司法机关是否已发觉该罪行及行为人是在何时、以何种方式交代的。","origin":"逐题标记"}]},"国考 2025 地市级 行测#93":{"stem":"深度优先搜索是指从初始节点出发，按照一定的顺序扩展到下一个节点，然后从下一个节点出发继续扩展到新的\n节点，不断递归执行这个过程，直到某个节点不能再扩展到下一个节点，此时返回上一个节点重新寻找一个新的节\n点继续扩展，如此搜索下去，直到找到目标节点，或者搜索完所有节点为止。\n\n\n\n\n根据上述定义，如果以“1”为初始节点，“12”为目标节点，下列搜索路径符合深度优先搜索的是：","options":["1    2   1   3    6   11   12","1    4   8   4    1   3    6    12","1    3   5   3    7   3    6    12","1    3   5   10   5    3   1    3    6   12"],"answer":"B","analysis":"93. 正确答案：B\n解析：\n第一步：找出定义关键词。\n“从初始节点出发，按照一定的顺序不断扩展到下一个节点，直到不能再扩展”、“此时返回上一个节点重新寻找一个\n新的节点继续扩展，直到找到目标节点，或者搜索完所有节点为止”。\n第二步：逐一分析选项。\nA项：1   2   1   3   6   11   12，图中显示，扩展到节点11时已无法继续扩展，且未找到目标节点，此时应返回\n到上一个节点6，而该项直接扩展到同级的节点12，不符合“此时返回上一个节点重新寻找一个新的节点继续扩展，\n如此搜索下去，直到找到目标节点，或者搜索完所有节点为止”，不符合定义，排除；\n\nB项：1   4   8   4    1       3       6       12，图中显示，从初始节点1出发，扩展到下一个节点4，继续扩展到下一个节点\n8，此时已无法继续扩展，且未找到目标节点，应返回到上一个节点4，同理继续返回上一个节点1，扩展到下一个节\n点3，继续扩展到下一个节点6，再扩展到下一个节点12，此时已找到目标节点，搜索完成，符合“从初始节点出发，\n按照一定的顺序不断扩展到下一个节点，直到不能再扩展”、“此时返回上一个节点重新寻找一个新的节点继续扩展，\n直到找到目标节点，或者搜索完所有节点为止”，符合定义，当选；\nC项：1   3   5   3    7       3       6       12，图中显示，扩展到节点5时直接返回到上一个节点3，而节点5含有节点9和\n节点10两个下级节点，属于扩展不完整，不符合“从初始节点出发，按照一定的顺序不断扩展到下一个节点，直到不\n能再扩展”，不符合定义，排除；\nD项：1   3   5   10       5       3       1   3   6   12，图中显示，从节点10返回到节点5时又返回到节点3，而节点5还含\n有节点9这一下级节点，返回到节点5时需要继续扩展到节点9，因此扩展顺序有误，不符合“此时返回上一个节点重\n新寻找一个新的节点继续扩展，如此搜索下去，直到找到目标节点，或者搜索完所有节点为止”，不符合定义，排\n除。\n故正确答案为B。\n【考点】\n单定义-其他句式","figs":["31f401e91aef8d11365d.pdf#18","31f401e91aef8d11365d.pdf#19"],"state":"已标记","notes":[],"domains":["科技"],"nature":"技能题","current":false,"links":[{"id":"s-fbc7bd8e0e436bca","label":"沿节点树核对深度优先搜索的扩展与回溯","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"返回到节点5时需要继续扩展到节点9","why":"沿图检查每一步是否沿相邻节点移动、是否在分支耗尽后逐级回溯，以及是否在到达目标时停止。","origin":"逐题标记","originalId":"s-ab821df619f17efc"}]},"国考 2025 地市级 行测#94":{"stem":"企业薪酬策略主要包括两个方面：一是体现企业支付标准的策略，即薪酬水平策略，其本质是在市场既定的薪酬\n水平上设定一个对公司有利的最优报酬水平；二是体现企业支付差异的策略，即薪酬结构策略，其通过企业的工资\n等级和工资幅度、加薪条件、晋升降级、小时工资、加班休假、工作时间等方面的薪酬政策表现出来。\n根据上述定义，下列说法正确的是：","options":["甲企业根据市场调查结果，设定行政岗位的薪酬标准。这体现了薪酬结构策略","乙企业今年赢利颇丰，企业将全员工资普遍调高。这体现了薪酬水平策略","丙企业工资分为基本工资和绩效工资两部分，绩效工资与员工绩效挂钩。这体现了薪酬水平策略","丁企业采取不同方式调整高、中、低三个职位层次人员的薪酬。这体现了薪酬水平策略"],"answer":"B","analysis":"94. 正确答案：B\n解析：\n第一步：找出定义关键词。\n薪酬水平策略：“体现企业支付标准”、“在市场既定的薪酬水平上”、“对公司有利的最优报酬水平”；\n薪酬结构策略：“体现企业支付差异”、“通过企业的工资等级和工资幅度、加薪条件、晋升降级、小时工资、加班休\n假、工作时间等方面的薪酬政策表现”。\n第二步：逐一分析选项。\nA项：甲企业根据市场调查结果设定薪酬标准，符合“在市场既定的薪酬水平上”、“对公司有利的最优报酬水平”，符\n合“薪酬水平策略”定义，不符合“薪酬结构策略”定义，排除；\nB项：乙企业因今年赢利提高全员工资，符合“体现企业支付标准”、“在市场既定的薪酬水平上”、“对公司有利的最优\n报酬水平”，符合“薪酬水平策略”定义，当选；\nC项：丙企业员工工资分为两部分，且绩效工资与员工绩效挂钩，符合“体现企业支付差异”、“通过企业的工资等级和\n工资幅度、加薪条件、晋升降级、小时工资、加班休假、工作时间等方面的薪酬政策表现”，符合“薪酬结构策略”定\n义，不符合“薪酬水平策略”定义，排除；\nD项：丁企业采取不同方式调整三个职位层次的人员薪酬，符合“体现企业支付差异”、“通过企业的工资等级和工资幅\n度、加薪条件、晋升降级、小时工资、加班休假、工作时间等方面的薪酬政策表现”，符合“薪酬结构策略”定义，不\n符合“薪酬水平策略”定义，排除。\n故正确答案为B。\n【考点】\n特殊问法","figs":[],"state":"已标记","notes":[],"domains":["经济"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"answer","quote":"乙企业因今年赢利提高全员工资，符合“体现企业支付标准”","why":"提取案例中变动的支付要素，按两项定义区分整体支付标准与内部支付差异。","origin":"逐题标记"}]},"国考 2025 地市级 行测#95":{"stem":"断取是修辞格的一种，引用词语时，只截取其中部分字眼的意义，而置其余于不顾，是一种“断章取义”的修辞方\n式。\n根据上述定义，下列没有采用断取修辞方式的是:","options":["相较于他之前见过的大阵仗，眼前的情形在他眼中就是“小儿科”","小林一心扑在科研项目上，他至今还是一个“光杆司令”呢","山林发生火灾，消防员“上刀山下火海”，奋力保卫人民的生命和财产安全","实在走投无路，他最终还是找老师“开药方”，问询这一困局的破解之道"],"answer":"D","analysis":"95. 正确答案：D\n解析：\n第一步：找出定义关键词。\n“引用词语时，只截取其中部分字眼的意义，而置其余于不顾”。\n第二步：逐一分析选项。\nA项：该项引用“小儿科”时，只取“小”义而舍“儿科”义，表明了眼前的情形在他眼中只是小阵仗，符合“引用词语时，\n只截取其中部分字眼的意义，而置其余于不顾”，符合定义，排除；\nB项：该项引用“光杆司令”时，只取“光杆”义而舍“司令”义，表明了小林因搞科研而至今未成婚，仍独身一人，符\n合“引用词语时，只截取其中部分字眼的意义，而置其余于不顾”，符合定义，排除；\nC项：该项引用“上刀山下火海”时，只取“下火海”义而舍“上刀山”义，突出了消防员在扑救大火时不畏艰难险阻的勇敢\n精神，符合“引用词语时，只截取其中部分字眼的意义，而置其余于不顾”，符合定义，排除；\nD项：该项引用“开药方”时，用了其完整的意思，表明了他在走投无路时，找老师寻求解决方法，不符合“引用词语\n时，只截取其中部分字眼的意义，而置其余于不顾”，不符合定义，当选。\n本题为选非题，故正确答案为D。\n【考点】\n\n单定义-其他句式","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"只截取其中部分字眼的意义，而置其余于不顾","why":"把引语在具体语境中表达的意思与其组成部分的意思对照，核对是否符合断取的条件。","origin":"逐题标记"}]},"国考 2025 地市级 行测#96":{"stem":"殚精竭虑：费尽心机","options":["狐假虎威：虚张声势","舍生忘死：死里逃生","侃侃而谈：喋喋不休","光怪陆离：五光十色"],"answer":"C","analysis":"96. 正确答案：C\n解析：\n第一步：判断题干词语间逻辑关系。\n“殚精竭虑”指用尽精力、费尽心思，“费尽心机”指挖空心思、想尽办法，二者是近义关系。\n第二步：判断选项词语间逻辑关系。\nA项：“狐假虎威”指狐狸假借老虎的威势吓跑百兽，比喻倚仗别人的势力来欺压、恐吓人，“虚张声势”形容假装出强\n大的气势，指假造声势，借以吓人，二者是近义关系，与题干逻辑关系一致，保留；\nB项：“舍生忘死”形容不顾性命危险，“死里逃生”指从极其危险的境地中逃脱，二者不是近义关系，与题干逻辑关系\n不一致，排除；\nC项：“侃侃而谈”指理直气壮、不慌不忙地说话，“喋喋不休”指说话唠唠叨叨、没完没了，二者是近义关系，与题干\n逻辑关系一致，保留；\nD项：“光怪陆离”形容现象奇异、色彩繁杂，“五光十色”形容色彩鲜艳、样式繁多，二者是近义关系，与题干逻辑关\n系一致，保留。\n比较A、C、D三项，题干中“殚精竭虑”是褒义词，“费尽心机”是贬义词，A项中“狐假虎威”和“虚张声势”都是贬义词，\nD项中“光怪陆离”是中性词，“五光十色”是褒义词，C项中“侃侃而谈”是褒义词，“喋喋不休”是贬义词，故C项更为合\n适。\n故正确答案为C。\n【考点】\n感情色彩","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-019d489e27fc9717","label":"殚精竭虑与费尽心机的词义和感情色彩","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“殚精竭虑”是褒义词，“费尽心机”是贬义词","why":"两词都涉及费尽心思，分别侧重用尽精力和挖空心思，构成题干的先褒后贬关系。","origin":"逐题标记","originalId":"k-2120fb0718d038b3"},{"id":"k-9916fdd38e8fa715","label":"侃侃而谈与喋喋不休的词义和感情色彩","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“侃侃而谈”是褒义词，“喋喋不休”是贬义词","why":"两词都描述说话，前者强调从容，后者强调唠叨，感情色彩依次为褒义和贬义。","origin":"逐题标记"},{"id":"s-26718cf11a50ed78","label":"比较词对的语义联系与感情色彩顺序","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"比较A、C、D三项","why":"先筛选语义上相关的词对，再逐位比对褒义、中性或贬义。","origin":"逐题标记","originalId":"s-aaafb8f73bd16e7e"}]},"国考 2025 地市级 行测#97":{"stem":"逐客令：挡箭牌","options":["急先锋：领航者","避风港：马后炮","敲门砖：绊脚石","鸿门宴：攻心计"],"answer":"C","analysis":"97. 正确答案：C\n解析：\n第一步：判断题干词语间逻辑关系。\n“逐客令”本为驱逐客卿的命令，后用于指主人对客人不欢迎时，用明说或暗示的方式，催客人离去。“挡箭牌”指古代\n防御武器中可以抵挡刀箭的盾牌，比喻推掉事情的借口或可以掩护的东西。“逐客令”与“挡箭牌”均根据功能进行命\n名。\n第二步：判断选项词语间逻辑关系。\nA项：“急先锋”比喻冲锋在前或积极领头的人。“领航者”通常指的是在特定领域或活动中，为其他人或组织提供指导\n和方向的人。其中“急先锋”不是根据功能进行命名，与题干逻辑关系不一致，排除；\nB项：“避风港”意思是供船只躲避大风浪的港湾，比喻供躲避激烈斗争的地方。“马后炮”是象棋术语，比喻事后才采\n取措施，但已无济于事。其中“马后炮”不是根据功能进行命名，与题干逻辑关系不一致，排除；\nC项：“敲门砖”是指敲门的砖石，比喻借以谋取名利的工具，目的一旦达到就被抛弃。“绊脚石”是指行走时使脚受阻\n而跌倒的石块，喻指前进道路上的障碍物。“敲门砖”与“绊脚石”均根据功能进行命名，与题干逻辑关系一致，当选；\nD项：“鸿门宴”意指不怀好意、居心不良的邀宴，比喻想要加害客人的宴会。“攻心计”指的是从心理上、精神上分析\n对方，从而瓦解对方，达到目的的一种心理战术。其中“鸿门宴”不是根据功能进行命名，与题干逻辑关系不一致，排\n除。\n故正确答案为C。\n【考点】\n功能,拆分-逻辑","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-77b2a4d4e5dfa53b","label":"逐客令与挡箭牌的本义及命名依据","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“逐客令”本为驱逐客卿的命令","why":"逐客令是驱逐客卿的命令，挡箭牌是抵挡刀箭的盾牌，两者名称都体现用途。","origin":"逐题标记"},{"id":"k-83574758193f2b4d","label":"敲门砖与绊脚石的本义及命名依据","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“敲门砖”与“绊脚石”均根据功能进行命名","why":"敲门砖原指用来敲门的砖石，绊脚石原指使脚受阻的石块，两个名称都体现功能。","origin":"逐题标记"},{"id":"s-26718cf11a50ed78","label":"拆解词语并根据本义判断命名依据","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"“敲门砖”与“绊脚石”均根据功能进行命名","why":"逐词识别所指对象和词面表达的功能，再比较各词对的命名关系。","origin":"逐题标记","originalId":"s-09f5c34aa0daf7a3"}]},"国考 2025 地市级 行测#98":{"stem":"直观性：即时性：网络直播","options":["等边性：对称性：等腰梯形","公开性：权威性：行政法律","周期性：延展性：机械钟摆","挥发性：保温性：石棉纤维"],"answer":"B","analysis":"98. 正确答案：B\n解析：\n第一步：判断题干词语间逻辑关系。\n网络直播具有直观性和即时性，前两词与第三词构成属性对应关系。\n第二步：判断选项词语间逻辑关系。\nA项：等边性是指图形中各边的长度都相等，等腰梯形只有一组对边相等，不具有等边性，与题干逻辑关系不一致，\n排除；\nB项：行政法律具有公开性和权威性，前两词与第三词构成属性对应关系，与题干逻辑关系一致，当选；\nC项：延展性是表示材料在受力而产生破裂之前，其塑性变形的能力，机械钟摆作为一个整体装置，不具有延展性，\n与题干逻辑关系不一致，排除；\n\nD项：挥发性是指液态物质在低于沸点的温度条件下转变成气态的能力，以及一些气体溶质从溶液中逸出的能力，石\n棉纤维是天然纤维状的硅质矿物的泛称，不具有挥发性，与题干逻辑关系不一致，排除。\n故正确答案为B。\n【考点】\n属性","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑","法律","科技"],"nature":"综合题","current":false,"links":[{"id":"k-982ce6847c75488d","label":"网络直播的直观性与即时性","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"网络直播具有直观性和即时性","why":"这两个属性共同确定题干的双属性对应关系。","origin":"逐题标记"},{"id":"k-24aba5d00e7b6ac1","label":"行政法律的公开性与权威性","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"行政法律具有公开性和权威性","why":"公开性和权威性均可用于描述行政法律，构成与题干一致的对应关系。","origin":"逐题标记"},{"id":"s-182392c898d56a84","label":"核对两个属性是否同时对应同一对象","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"前两词与第三词构成属性对应关系","why":"逐一核验前两个词能否描述第三个词所指对象。","origin":"逐题标记","originalId":"s-8a2595708d0c3364"}]},"国考 2025 地市级 行测#99":{"stem":"群众来访：窗口接访：调查督办","options":["地面试验：点火飞行：燃料加注","支付本币：兑换外币：确认汇率","建造堤坝：潮汐发电：送电入户","重启谈判：临时休战：边境冲突"],"answer":"C","analysis":"99. 正确答案：C\n解析：\n第一步：判断题干词语间逻辑关系。\n先群众来访，再窗口接访，最后调查督办，三者为时间先后顺序的对应关系。\n第二步：判断选项词语间逻辑关系。\nA项：先燃料加注，再点火飞行，第二词和第三词的时间先后顺序与题干不同，与题干逻辑关系不一致，排除；\nB项：一般是先确认汇率，再兑换外币，第二词和第三词的时间先后顺序与题干不同，与题干逻辑关系不一致，排\n除；\nC项：先建造堤坝，再潮汐发电，最后送电入户，三者为时间先后顺序的对应关系，与题干逻辑关系一致，当选；\nD项：先临时休战，再重启谈判，第一词和第二词的时间先后顺序与题干不同，与题干逻辑关系不一致，排除。\n故正确答案为C。\n【考点】\n动作/状态先后顺序","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-cd83588b8b1f05cb","label":"按实际流程核对动作的先后顺序","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"先群众来访，再窗口接访，最后调查督办","why":"从各组动作还原实际流程，检查动作的排列顺序是否与发生顺序一致。","origin":"逐题标记","originalId":"s-4df8b5943b92d0a8"}]},"国考 2025 地市级 行测#100":{"stem":"稀树草原 对于 （             ） 相当于 （       ） 对于 国际公约","options":["物种多样性；缔约国家","落叶阔叶林；多边条约","气候变迁；政治协调","植被类型；联合国宪章"],"answer":"D","analysis":"100. 正确答案：D\n解析：\n逐一代入选项。\nA项：稀树草原是炎热、季节性干旱气候条件下长成的植被类型，稀树草原物种丰富，具有物种多样性，二者为属性\n对应关系；缔约国家是条约制定国以及自愿加入或者遵守并同意签约的其他主权国家，只有签订国际公约才是缔约\n国家，二者为条件对应关系，前后逻辑关系不一致，排除；\nB项：稀树草原是炎热、季节性干旱气候条件下长成的植被类型，落叶阔叶林也是一种植被类型，二者为并列关系；\n国际公约是国家之间签署的公约，多边条约是指外交条约，国际公约是外交条约，二者为种属关系，前后逻辑关系\n不一致，排除；\nC项：气候变迁可能会导致形成稀树草原，二者为因果对应关系；国际公约有政治协调的功能，二者为功能对应关\n系，前后逻辑关系不一致，排除；\nD项：稀树草原是炎热、季节性干旱气候条件下长成的植被类型，二者为种属关系；联合国宪章是联合国的基本大\n法，是国际公约，二者为种属关系，前后逻辑关系一致，当选。\n故正确答案为D。\n【考点】\n种属关系","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑","地理","法律"],"nature":"综合题","current":false,"links":[{"id":"k-48c9f9055256dcfa","label":"稀树草原是一种植被类型","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"稀树草原是炎热、季节性干旱气候条件下长成的植被类型","why":"这一归属确定了前半组词语的种属方向。","origin":"逐题标记","originalId":"k-c937690dc87d8fdf"},{"id":"k-d067819fc066e876","label":"《联合国宪章》属于国际公约","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"联合国宪章是联合国的基本大\n法，是国际公约","why":"这一归属确定了后半组词语的种属方向。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"answer","quote":"前后逻辑关系一致","why":"需分别判定两组词语的关系类型和方向，再检验是否一致。","origin":"逐题标记"}]},"国考 2025 地市级 行测#101":{"stem":"研究者设计了一个“拔河比赛”的实验，要求被试分别在单独和群体的情境下拔河，同时用仪器来测量他们的拉\n力。结果发现随着被试人数的增加，平均每个被试使出的力减少了。据此研究者认为，提高团队业绩的最佳途径就\n是减少团队人数。\n\n下列选项如果为真，除哪项外均能质疑上述研究者的观点？","options":["团队合作中各取所长很重要，人数过少效率也会随之下降","团队一起工作时，个人的贡献不被凸显，很容易失去积极性","团队的合作与管理方式要比拔河复杂得多，不能一概而论","增强个体对团队的归属感、责任感，能够更好地提高团队业绩"],"answer":"B","analysis":"101. 正确答案：B\n解析：\n第一步：找出论点和论据。\n论点：提高团队业绩的最佳途径就是减少团队人数。\n论据：随着被试人数的增加，平均每个被试使出的力减少了。\n本题论点讨论的是减少团队人数是提高团队业绩的最佳途径。论据讨论的是在“拔河比赛”的实验中被试人数增加，则\n平均每个被试使出的力会减少，即人数减少有利于每个被试使出的力增加。二者话题不一致，削弱可以考虑拆桥、\n削弱论点、削弱论据等。本题为选非题，排除能削弱的选项即可。\n第二步：逐一分析选项。\nA项：团队中人数过少则效率也会随之下降，说明减少团队人数可能不会提高团队业绩，削弱论点，可以削弱，排\n除；\nB项：团队中个人的贡献不被凸显，很容易失去积极性，解释了为什么随着被试人数的增加，平均每个被试使出的力\n减少了，为加强项，无法削弱，当选；\nC项：团队的合作和管理方式比拔河更复杂，说明不能将拔河得到的结论应用在团队合作中，拆断了拔河比赛与团队\n合作、管理方式之间的联系，为拆桥项，可以削弱，排除；\n\nD项：增强个体对团队的归属感、责任感能更好地提高团队业绩，说明减少团队人数并非提高团队业绩的最佳途径，\n削弱论点，可以削弱，排除。\n本题为选非题，故正确答案为B。\n【考点】\n削弱选非题","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-4e6dc1eac45ccce0","label":"区分对实验结果的解释与对外推结论的削弱","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"无法削弱，当选","why":"需区分解释人均出力变化的选项与质疑实验外推或最佳途径的选项。","origin":"逐题标记","originalId":"s-63ad8ecfde113e02"}]},"国考 2025 地市级 行测#102":{"stem":"考古人员发现了近300枚16亿年前的丝状体生物化石，这些丝状体均由巨型细胞组成，直径20~194微米不等。\n化石中，有些丝状体直径保持不变，细胞呈短柱状至长柱状；有些丝状体整体向一端均匀收缩，细胞呈柱状、桶状\n或杯状；而有的丝状体仅一端变细，形态呈现了一定的复杂性。考古人员据此认为，这些丝状体很可能属于真核生\n物。\n以下各项如果为真，除哪项外均能支持上述观点？","options":["这些化石中被发现有类似于现生繁殖细胞——孢子一样的圆形结构，这一结构只出现在真核生物中","原核生物细胞的直径一般小于2微米，而真核生物细胞的直径一般在10~100微米之间","在目前已知的原核生物中，大多数的丝状体形态都比较简单，只有个别呈现出过渡期形态","经比对，该化石中丝状体与一些现生绿藻（一种真核生物）的藻丝体形态、细胞大小分布和繁殖方式等最为接近"],"answer":"C","analysis":"102. 正确答案：C\n解析：\n第一步：找出论点和论据。\n论点：这些丝状体很可能属于真核生物。\n论据：这些丝状体均由巨型细胞组成，直径20~194微米不等。化石中，有些丝状体直径保持不变，细胞呈短柱状至\n长柱状；有些丝状体整体向一端均匀收缩，细胞呈柱状、桶状或杯状；而有的丝状体仅一端变细，形态呈现了一定\n的复杂性。\n本题论点说的是这些丝状体很可能属于真核生物，而论据说的是这些丝状体化石有哪些形态特征，论点和论据话题\n不一致，加强优先考虑搭桥，且本题为选非题，将可以加强的选项排除即可。\n第二步：逐一分析选项。\nA项：该项说的是这些丝状体生物化石中发现了类似于真核生物的圆形结构，建立了论据中“丝状体化石”与论点中“真\n核生物”的联系，为搭桥项，可以加强，排除；\nB项：该项说的是真核生物细胞的直径一般在10~100微米之间，与丝状体生物化石中的巨型细胞直径20~194微米范\n围类似，建立了论据中“丝状体化石”与论点中“真核生物”的联系，为搭桥项，可以加强，排除；\nC项：该项说的是原核生物的形态特点，与论点讨论的真核生物以及论据讨论的丝状体化石均无关系，为无关项，无\n法加强，当选；\nD项：该项说的是化石中丝状体的形态等特征与一种真核生物绿藻相似，建立了论据中“丝状体化石”与论点中“真核生\n物”的联系，为搭桥项，可以加强，排除。\n本题为选非题，故正确答案为C。\n【考点】\n加强选非题","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-2ee7513507dfe397","label":"检验补充证据能否连接观察特征与分类结论","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"加强优先考虑搭桥","why":"需判断补充的结构、尺度或形态信息能否为化石归类建立证据联系。","origin":"逐题标记","originalId":"s-d65b101e18f5d29a"}]},"国考 2025 地市级 行测#103":{"stem":"某企业对于如何进行产教融合，形成如下两种方案：一是“做深”，企业自建培训中心，成立专职和兼职的企业培\n训师队伍，并根据企业需求，制定专门的培训大纲和计划，该中心与毕业生未来形成签约。二是“做浅”，在学校设\n立“冠名班”和“订单班”，以学校教育为主，企业与学生当前没有签约意向，但随时保持互相选择的权利。\n以下理由中，能够支持企业选择第二方案的是：","options":["企业必须付出人力成本，人力资源自带“稀缺”和“增值”属性，在企业面临竞争压力时尤其要重视","企业订单量并不是稳定的，遇到订单量突然增加需要扩产的时候，才临时需要大量的人参与进来","该企业生产使用的是特种专业设备，竞争对手稀少，不具备从市场上挖掘技术人员的条件","学校教育内容具有普适性，而自建培训中心有利于企业保障准员工的培养质量，提前锁定毕业生"],"answer":"B","analysis":"103. 正确答案：B\n解析：\n第一步：找出论点和论据。\n论点：企业选择产教融合的第二种方案：“做浅”，在学校设立“冠名班”和“订单班”，以学校教育为主，企业与学生当\n前没有签约意向，但随时保持互相选择的权利。\n论据：无。\n本题的论点说的是企业与学校合作，培养企业需要的人，随时需求随时签约。本题只有论点，没有论据，加强考虑\n补充论据。\n第二步：逐一分析选项。\nA项：企业付出人力成本，与论点讨论的企业和学校合作无关，话题不一致，无法加强，排除；\nB项：企业订单不稳定，订单突然增加时才需要大量人员，那么可以和学校签约“订单班”，随时和学生互相选择，能\n支持选择第二方案，补充论据，可以加强，当选；\nC项：企业生产使用特种专业设备，不具有从市场挖人的条件，与论点讨论的企业和学校合作无关，话题不一致，无\n法加强，排除；\nD项：自建培训中心比学校教育更有利，支持第一方案，反而削弱第二方案，无法加强，排除。\n故正确答案为B。\n【考点】\n补充论据","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-2ee7513507dfe397","label":"将决策条件与方案特点匹配以补充论据","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"本题只有论点，没有论据，加强考虑\n补充论据。","why":"需判断哪项用工条件能够说明灵活保留双向选择对企业有益。","origin":"逐题标记","originalId":"s-2472c9835a352457"}]},"国考 2025 地市级 行测#104":{"stem":"我军军语惯于将数字1、2、7、9、0变读为幺、两、拐、勾、洞，这些数字有个共同特点，即其原本的发音部\n位与发音方法使得在读这些数字时无法发出较大声音，在噪声干扰较为强烈的战场上，通信兵使用通讯设备进行情\n报交流时，话筒对这些数字的实际增音效果并不明显，可能会影响信息的准确性。因此，在军语中将这些数字变\n读，是为了符合实际需要。\n以下哪项如果为真，不能支持上述结论？","options":["常规数字念法中1、7的韵尾相同，发音相似，在嘈杂的战场环境中容易混淆，造成信息传达错误","士兵一般都来自不同的兵源地，不可避免地带有家乡口音，将数字变读可以避免口音问题","在国际无线电通话中，也会对字母读音进行变读，如将A读成Alpha，将D读成Delta","将0读成“洞”时，更容易提高声音，同时也使声音更加干脆清晰，确保信息的准确性"],"answer":"C","analysis":"104. 正确答案：C\n解析：\n第一步：找出论点和论据。\n论点：在军语中将这些数字变读，是为了符合实际需要。\n论据：我军军语惯于将数字1、2、7、9、0变读为幺、两、拐、勾、洞，这些数字有个共同特点，即其原本的发音部\n位与发音方法使得在读这些数字时无法发出较大声音，在噪声干扰较为强烈的战场上，通信兵使用通讯设备进行情\n\n报交流时，话筒对这些数字的实际增音效果并不明显，可能会影响信息的准确性。\n本题论点说的是军语中将部分数字变读的原因，论据说的是这些数字的原本发音会影响信息的准确性。论点、论据\n话题一致，且本题为选非题，找到可加强的选项排除即可。\n第二步：逐一分析选项。\nA项：该项指出常规数字念法中1、7的韵尾相同，发音相似，说明了原发音在战场上可能导致信息传达错误，而变读\n可以避免错误，是为了符合实际需要，补充论据，可以加强，排除；\nB项：该项指出变读可以避免口音问题，减少误解，是为了符合实际需要，补充论据，可以加强，排除；\nC项：该项指出“在国际无线电通话中”，也会对“字母”读音进行变读，而论点说的是在“军语”中将“数字”变读，话题不\n一致，不能加强，当选；\nD项：该项指将0读成“洞”时，更容易提高声音，举例说明变读能确保信息的准确性，是为了符合实际需要，补充论\n据，可以加强，排除。\n本题为选非题，故正确答案为C。\n【考点】\n加强选非题","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-2ee7513507dfe397","label":"检验类比事例能否支持特定对象及其用途","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"而论点说的是在“军语”中将“数字”变读","why":"需核对相似做法的对象和使用情境，并判断它能否说明题述做法的实际用途。","origin":"逐题标记","originalId":"s-8b71c4754e448d62"}]},"国考 2025 地市级 行测#105":{"stem":"海山是海面下的岛屿，与岛屿中的火山岛有相同的起源和相似的形态，以往的海山生物调查发现，海山岩石上\n的生物群落与海山周边的软底沉积和深海平原上的生物群落大不相同。而且，一些海山之间的生物群落在物种构成\n上较少重叠。因此，有一些学者认为，相对孤立的海山存在独特的生物群落且拥有高度特有的动物群。\n以下哪项如果为真，最能反驳上述学者的观点？","options":["远离大陆的孤岛，因为海洋的分割往往会形成相对孤立且独特的岛屿生物群","物理隔离海洋的现象在海洋中很少出现，所以海山不可能长期被隔离成水下孤岛","早期一些海山中发现的高度特有物种其实是采样不足造成的，很多海山都有相同的生物来源","地形和海流的相互作用在某些海山顶部形成封闭环流，使栖息其上的生物幼体难以扩散"],"answer":"C","analysis":"105. 正确答案：C\n解析：\n第一步：找出论点和论据。\n论点：相对孤立的海山存在独特的生物群落且拥有高度特有的动物群。\n论据：以往的海山生物调查发现，海山岩石上的生物群落与海山周边的软底沉积和深海平原上的生物群落大不相\n同。而且，一些海山之间的生物群落在物种构成上较少重叠。\n本题论点和论据说的都是海山的生物群落比较独特，话题一致，削弱可以考虑削弱论点或削弱论据。\n第二步：逐一分析选项。\nA项：指出远离大陆的孤岛因为海洋的分割往往会形成相对孤立且独特的岛屿生物群，但论点讨论的是海山，海山并\n不都是远离大陆的孤岛，话题不一致，无法削弱，排除；\nB项：指出海山不可能长期被隔离成水下孤岛，但论点讨论的是海山是否存在独特的生物群落且拥有高度特有的动物\n群，话题不一致，无法削弱，排除；\nC项：指出早期一些海山中发现的高度特有物种其实是采样不足造成的，很多海山都有相同的生物来源，说明论据里\n面的调查并不全面，削弱论据，可以削弱，当选；\nD项：指出某些海山顶部形成封闭环流，使栖息其上的生物幼体难以扩散，讨论的是生物幼体难以扩散的原因，但论\n点讨论的是海山是否存在独特的生物群落且拥有高度特有的动物群，话题不一致，无法削弱，排除。\n故正确答案为C。\n【考点】\n削弱论据","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-4e6dc1eac45ccce0","label":"通过指出采样不足削弱调查结论","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"早期一些海山中发现的高度特有物种其实是采样不足造成的","why":"需判断采样不足能否解释观察到的低重叠，并据此削弱对物种特有性的推断。","origin":"逐题标记","originalId":"s-027b250aeea5e906"}]},"国考 2025 地市级 行测#106":{"stem":"下列哪2次会议可以安排在第一季度？","options":["甲和戊","丙和丁","丁和己","己和庚"],"answer":"D","analysis":"106. 正确答案：D\n解析：\n第一步：分析题干条件。\n（1）丁、辛在第二季度；\n（2）甲、戊在同一个季度；\n（3）丁在乙之后丙之前举办；\n（4）丙在甲之前己之后举办；\n（5）甲、乙、丙、丁、戊、己、庚、辛8次学术会议，每个季度最多举办3次。\n第二步：根据题干条件进行推理。\n根据条件（1）可知，丁在第二季度举办，排除B、C两项；根据条件（3）和（4）可知，甲的前面一定有乙、丁、\n己、丙4次会议，结合条件（5）“每个季度最多举办3次”可知，甲一定不在第一季度举办，排除A项，只有D项符合。\n故正确答案为D。\n【考点】\n一拖五,排除法（材料）,从确定信息开始推或其他（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"answer","quote":"每个季度最多举办3次”可知，甲一定不在第一季度举办","why":"先根据固定季度排除部分组合，再将先行会议数量与季度容量结合，判断剩余组合的可行性。","origin":"逐题标记"}]},"国考 2025 地市级 行测#107":{"stem":"如果第二季度只安排2次会议，那么以下哪次会议一定安排在第一季度？","options":["甲","乙","庚","丙"],"answer":"B","analysis":"107. 正确答案：B\n解析：\n第一步：分析题干条件。\n\n（1）丁、辛在第二季度；\n（2）甲、戊在同一个季度；\n（3）丁在乙之后丙之前举办；\n（4）丙在甲之前己之后举办；\n（5）第二季度只安排2次会议。\n第二步：根据题干条件进行推理。\n根据条件（1）和（5）可知，第二季度只安排了丁、辛两次会议，结合条件（3）可知，丁在乙之后举办，因此乙会\n议一定在第一季度举办，对应B项。\n故正确答案为B。\n【考点】\n一拖五,从确定信息开始推或其他（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"answer","quote":"第二季度只安排了丁、辛两次会议，结合条件（3）可知，丁在乙之后举办","why":"先确定第二季度的名额已满，再由会议的先后关系推出前序会议的季度。","origin":"逐题标记"}]},"国考 2025 地市级 行测#108":{"stem":"如果丙、戊安排在第四季度，下列哪2次会议可以安排在第三季度？","options":["甲和庚","乙和丁","乙和己","己和庚"],"answer":"D","analysis":"108. 正确答案：D\n解析：\n第一步：分析题干条件。\n（1）丁、辛在第二季度；\n（2）甲、戊同一季度；\n（3）丁在乙之后，在丙之前；\n（4）丙在甲之前，在己之后；\n（5）乙、丙、丁、戊、己、庚、辛8次学术会议，每个季度最多举办3次；\n（6）丙、戊在第四季度。\n第二步：根据题干条件进行推理。\n本题题干信息确定，选项信息充分，优先考虑排除法。\n根据条件（1）（3）可知，乙在第二季度或者之前，不可能安排在第三季度，排除B、C两项；\n根据条件（2）（6）可知，甲一定在第四季度，排除A项。\n经验证，D项满足题干所有条件，当选。\n故正确答案为D。\n【考点】\n一拖五,排除法（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"answer","quote":"乙在第二季度或者之前，不可能安排在第三季度，排除B、C两项；","why":"用先后约束限定部分会议的最晚季度，再用同季度约束确定其他会议的季度并筛选组合。","origin":"逐题标记"}]},"国考 2025 地市级 行测#109":{"stem":"如果每个季度至少安排1次会议，并且最后一个季度仅安排1次会议，下列哪2次会议一定安排在第三季度？","options":["甲和戊","乙和丙","丙和己","己和庚"],"answer":"A","analysis":"109. 正确答案：A\n解析：\n第一步：分析题干条件。\n（1）丁、辛在第二季度；\n（2）甲、戊在同一个季度；\n（3）丁在乙之后丙之前举办；\n（4）丙在甲之前己之后举办；\n（5）甲、乙、丙、丁、戊、己、庚、辛8次学术会议，每个季度最多举办3次；\n（6）每个季度至少安排1次会议；\n（7）第四季度仅安排1次会议。\n第二步：根据题干条件进行推理。\n根据条件（1）（2）（5）可知，甲和戊不可能安排在第二季度；此时结合条件（7）可知，甲和戊不可能安排在第\n四季度；再结合条件（4）可知，甲前面已经有己、丙，而每个季度最多举办3次，所以甲和戊在同一季度的情况\n下，不可能安排在第一季度，因此甲和戊只能安排在第三季度，对应A项。\n故正确答案为A。\n【考点】\n一拖五,从确定信息开始推或其他（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"M1","quote":"甲、戊安排在同一个季度；","why":"将必须同季度的两次会议作为一组，结合各季名额和前序会议逐一排除无法容纳该组的季度。","origin":"逐题标记"}]},"国考 2025 地市级 行测#110":{"stem":"如果甲安排在第三季度，第四季度不安排会议，庚不可能和哪次会议安排在同一个季度？","options":["乙","丙","己","辛"],"answer":"B","analysis":"110. 正确答案：B\n解析：\n第一步：分析题干条件。\n（1）丁、辛在第二季度；\n（2）甲、戊同一季度；\n\n（3）丁在乙之后，在丙之前；\n（4）丙在甲之前，在己之后；\n（5）甲、乙、丙、丁、戊、己、庚、辛8次学术会议，每个季度最多举办3次；\n（6）甲在第三季度，第四季度不安排会议。\n第二步：根据题干条件进行推理。\n根据题干条件（3）和条件（4）可知，丙前有乙、丁和己，情况较少，因此可优先从丙入手进行假设。\n假设丙被安排在第一季度，由条件（1）可知，丁、辛在第二季度，此时，丙在第一季度，丁在第二季度，不符合条\n件（3），因此，丙不能安排在第一季度。\n假设丙被安排在第二季度，由条件（1）（2）（6）可知，丁、辛在第二季度，甲、戊在第三季度。结合条件（3）\n（4）（5）可知，乙和己在丙之前的第一季度，此时第一季度和第三季度均可安排庚，庚可能和乙、己、甲、戊安\n排在同一个季度。\n\n\n\n\n假设丙被安排在第三季度，由条件（1）（2）（6）可知，丁、辛在第二季度，甲、戊在第三季度。结合条件（3）\n（4）（5）可知，乙和己在丙之前的第一季度或第二季度（如下图所示）。此时第一季度和第二季度均可安排庚，\n庚可能和乙、己、丁、辛安排在同一个季度。\n\n\n                                                      或\n\n\n\n\n                                                      或\n\n\n\n\n综上，庚不可能和丙安排在同一个季度。\n本题为选非题，故正确答案为B。\n【考点】\n一拖五,假设（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"answer","quote":"丙前有乙、丁和己，情况较少，因此可优先从丙入手进行假设。","why":"选取取值受限的会议按季度分情况，逐一检查先后约束和剩余名额，判断同季度安排是否可行。","origin":"逐题标记"}]},"国考 2025 地市级 行测#111":{"stem":"2019-2023年，有几个城市五批次累计公示的专精特新“小巨人”上市企业数量占全国的比重超过5%？","options":["1","2","3","4"],"answer":"C","analysis":"111. 正确答案：C\n解析：\n根据题干“2019-2023年，有几个城市······占全国的比重超过5%”，结合材料时间为2019-2023年，可判定本题为现期\n比重问题。定位柱状图可知2019-2023年我国各批次专精特新“小巨人”上市企业数量，则2019-2023年我国五批次累\n\n计公示的专精特新“小巨人”上市企业数量为39+198+229+282+134=882家。根据公式：比重     ，题目求\n\n        ，则满足城市>全国×5%=882×5%=44.1家即可。定位表格可知全国排名前10的城市五批次累计专精特\n\n新“小巨人”上市企业数量，观察发现，从第4名开始均小于44.1家，即只有3个城市的占比超过5%。\n故正确答案为C。\n【考点】\n综合资料,现期比重","figs":["31f401e91aef8d11365d.pdf#21"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-share","label":"比重等于部分量除以总体量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"则满足城市>全国×5%=882×5%=44.1家即可。","why":"各城市的总体量相同且为正，因此部分量超过总体量的5%就等价于比重超过5%。","origin":"逐题标记"},{"id":"s-22e0d443f4e8833e","label":"比较比重与百分点差","catalog_id":"D06","type":null,"role":"直接考查","field":"question","quote":"占全国的比重超过5%","why":"用共同分母把比重门槛换算成数量门槛，再借助排名统计达标对象。","origin":"逐题标记"}]},"国考 2025 地市级 行测#112":{"stem":"以下批次中，公示的专精特新“小巨人”上市企业数量占同批次专精特新“小巨人”企业数量比重最高的是：","options":["第二批次","第三批次","第四批次","第五批次"],"answer":"A","analysis":"112. 正确答案：A\n解析：\n\n根据题干“以下批次中······占同批次······比重最高的是”，可判定本题为现期比重问题。定位统计图可知各批次公示的\n专精特新“小巨人”上市企业数量及企业数量，根据公式：比重             ，各批次公示的专精特新“小巨人”上市企业数\n\n量占同批次专精特新“小巨人”企业数量比重分别为：第二批次，                ；第三批次，          ；第四批\n\n次，         ；第五批次，          ，则第二批次公示的专精特新“小巨人”上市企业数量占同批次专精特\n\n新“小巨人”企业数量比重最高。\n故正确答案为A。\n【考点】\n综合资料,现期比重","figs":["31f401e91aef8d11365d.pdf#21"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-share","label":"比重等于部分量除以总体量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"公示的专精特新“小巨人”上市企业数量占同批次专精特新“小巨人”企业数量比重最高的是","why":"每个批次以本批次全部企业为总体，以其中的上市企业为部分。","origin":"逐题标记"},{"id":"s-22e0d443f4e8833e","label":"比较比重与百分点差","catalog_id":"D06","type":null,"role":"直接考查","field":"question","quote":"占同批次专精特新“小巨人”企业数量比重最高的是","why":"逐组配对分子和分母，比较分母不同的比重。","origin":"逐题标记"}]},"国考 2025 地市级 行测#113":{"stem":"已知2023年第五批次公示的专精特新“小巨人”企业分布于全国300个城市中，则这些城市平均每个有多少家第五\n批次公示的专精特新“小巨人”非上市企业？","options":["不到11家","11-12家之间","12-13家之间","超过13家"],"answer":"B","analysis":"113. 正确答案：B\n解析：\n根据题干“已知2023年第五批次公示······平均每个有多少家······”，结合材料给出2023年第五批次公示相关数据，可\n判定本题为现期平均数问题。定位统计图可得：2023年第五批次公示专精特新“小巨人”企业数量为3671家，专精特\n新“小巨人”上市企业数量为134家。根据平均数         ，可得全国300个城市中，平均每个城市第五批次公示的专精\n\n特新“小巨人”非上市企业数量                                           家，在B项范围\n\n内。\n故正确答案为B。\n【考点】\n综合资料,现期平均数","figs":["31f401e91aef8d11365d.pdf#21"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-6ff091e148e95c88","label":"算术平均数等于总量除以单位数","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"则这些城市平均每个有多少家","why":"每城平均数量的分子是非上市企业合计数，分母是材料给出的城市数。","origin":"逐题标记"},{"id":"s-e9ffdd08e7f0ec51","label":"计算平均数、倍数及其变化","catalog_id":"D07","type":null,"role":"直接考查","field":"answer","quote":"企业数量为3671家，专精特\n新“小巨人”上市企业数量为134家。","why":"用总数减去已给子类数量，得到所求总量，再按单位数求平均值并判断区间。","origin":"逐题标记"}]},"国考 2025 地市级 行测#114":{"stem":"2019-2023年，北京、上海、广州、深圳4个城市五批次累计公示的专精特新“小巨人”企业数量之和约占全国总\n数的：","options":["35%","30%","25%","20%"],"answer":"D","analysis":"114. 正确答案：D\n解析：\n根据题干“2019-2023年······约占······”，结合材料给出2019-2023年的相关数据，可判定本题为现期比重问题。定位\n统计图可得：2019-2023年我国五批次公示的专精特新“小巨人”企业数量分别为248家、1744家、2930家、4357家、\n3671家；定位统计表可得：2019-2023年北京、上海、广州、深圳4个城市五批次累计专精特新“小巨人”企业数量分\n\n别为840家、713家、249家、755家。根据公式：比重       ，可得题干所求\n\n                。\n\n故正确答案为D。\n【考点】\n综合资料,现期比重","figs":["31f401e91aef8d11365d.pdf#21"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-share","label":"比重等于部分量除以总体量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"企业数量之和约占全国总\n数的","why":"以四城合计为部分量，以相同统计期和统计口径下的全国合计为总体量。","origin":"逐题标记"},{"id":"s-a7ce466b25f8ea1b","label":"计算现期比重","catalog_id":"7a985b326fc58141","type":null,"role":"直接考查","field":"question","quote":"企业数量之和约占全国总\n数的","why":"分别从表和柱状图取数加总，再估算同一统计期的部分量与总体量之比。","origin":"逐题标记"}]},"国考 2025 地市级 行测#115":{"stem":"以下饼状图中，最能准确反映2019-2023年五批次公示的专精特新“小巨人”上市企业中，第一批次（黑色）、第\n二批次（横线）、第三批次（竖线）、第四批次（白色）和第五批次（网格）企业数量比例关系的是：","options":["","","",""],"answer":"B","analysis":"115. 正确答案：B\n解析：\n根据题干“······最能准确反映2019-2023年······企业数量比例关系的是”，结合材料时间为2019-2023年，可判定本题\n为现期比重问题。定位统计图可知：2019-2023年五批次公示的专精特新“小巨人”上市企业数量分别为39家、198\n家、229家、282家、134家。根据第四批次公示上市企业数量（282家）最多，可知第四批次（白色）占比最大，排\n除A、D两项；第五批次公示上市企业数量（134家）<第二批次公示上市企业数量（198家），可知第五批次（网\n格）占比<第二批次（横线）占比，排除C项，B项当选。\n故正确答案为B。\n【考点】\n综合资料,现期比重","figs":["31f401e91aef8d11365d.pdf#22","31f401e91aef8d11365d.pdf#23","31f401e91aef8d11365d.pdf#21"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-e013d096d346a36e","label":"饼图扇区大小与类别占总体的比重成正比","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"第四批次公示上市企业数量（282家）最多，可知第四批次（白色）占比最大","why":"各批次共用一个总体，企业数量越多，对应的饼图扇区越大。","origin":"逐题标记"},{"id":"s-6cfd92b2f027f1a1","label":"按类别数量的相对大小匹配饼图扇区","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"占比<第二批次（横线）占比，排除C项","why":"按图例定位类别，用最大扇区和关键类别之间的大小关系筛选图形。","origin":"逐题标记","originalId":"s-1619def39d057555"}]},"国考 2025 地市级 行测#116":{"stem":"2021-2023年，Z省各年律师人数与律师事务所总数的比值：","options":["先升后降","先降后升","持续下降","持续上升"],"answer":"D","analysis":"116. 正确答案：D\n解析：\n根据题干“2021-2023年······与······的比值”，结合选项为判断升降变化，可判定本题为比值比较问题。定位统计表可\n得：2021-2023年，Z省各年律师人数分别为30889人、36938人、41924人；各年律师事务所总数分别为1705家、\n1755家、1826家。则比值分别为2021年：              ；2022年：             ；2023年：\n\n              ，故2021-2023年，Z省各年律师人数与律师事务所总数的比值持续上升。\n\n故正确答案为D。\n\n【考点】\n统计表,比值比较","figs":["31f401e91aef8d11365d.pdf#23"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-291666e3bfbaacd3","label":"平均数等于总量除以对应的单位数","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"各年律师人数与律师事务所总数的比值","why":"同一年的律师总人数作分子，律师事务所总数作分母，所得比值表示平均每家对应的律师人数。","origin":"逐题标记"},{"id":"s-e9ffdd08e7f0ec51","label":"计算平均数、倍数及其变化","catalog_id":"D07","type":null,"role":"直接考查","field":"answer","quote":"结合选项为判断升降变化，可判定本题为比值比较问题。","why":"按年份配对分子与分母，比较三个年度比值的升降方向。","origin":"逐题标记"}]},"国考 2025 地市级 行测#117":{"stem":"2020-2023年，Z省律师办理法律业务数之和约是同期基层法律服务工作者办理法律业务数之和的多少倍？","options":["12","15","18","21"],"answer":"A","analysis":"117. 正确答案：A\n解析：\n根据题干“2020-2023年······之和约是······之和的多少倍”，可判定本题为现期倍数问题。定位统计表可知：2020-\n2023年每年Z省律师办理法律业务数、基层法律服务工作者办理法律业务数。可得题干所求倍数为\n                                          倍。\n\n故正确答案为A。\n【考点】\n统计表,现期倍数","figs":["31f401e91aef8d11365d.pdf#23"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-bf3709b5891572d8","label":"A是B的倍数等于A除以B","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"律师办理法律业务数之和约是同期基层法律服务工作者办理法律业务数之和的多少倍？","why":"题干指定两组业务数的四年合计分别作为分子和分母。","origin":"逐题标记"},{"id":"s-e9ffdd08e7f0ec51","label":"计算平均数、倍数及其变化","catalog_id":"D07","type":null,"role":"直接考查","field":"question","quote":"律师办理法律业务数之和约是同期基层法律服务工作者办理法律业务数之和的多少倍？","why":"分别加总两组年度数据，再估算两个合计数的商。","origin":"逐题标记"}]},"国考 2025 地市级 行测#118":{"stem":"2023年，Z省含村、社区在内的法律顾问数约是2020年的多少倍？","options":["1.2","1.4","1.6","1.8"],"answer":"B","analysis":"118. 正确答案：B\n解析：\n根据题干“2023年······约是······多少倍”，可判定本题为现期倍数问题。定位统计表可得：2023年Z省（不含村、社\n区）法律顾问数为111811家，村(社区)法律顾问数为23652家；2020年Z省（不含村、社区）法律顾问数为72739\n家，村（社区）法律顾问数为26153家。则题干所求                                          倍。\n\n故正确答案为B。\n【考点】\n统计表,现期倍数","figs":["31f401e91aef8d11365d.pdf#23"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-bf3709b5891572d8","label":"A是B的倍数等于A除以B","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"Z省含村、社区在内的法律顾问数约是2020年的多少倍？","why":"以2023年同口径总数为分子，以2020年同口径总数为分母。","origin":"逐题标记"},{"id":"s-e9ffdd08e7f0ec51","label":"计算平均数、倍数及其变化","catalog_id":"D07","type":null,"role":"直接考查","field":"answer","quote":"可判定本题为现期倍数问题。定位统计表可得","why":"按同一统计口径分别合并两个年份的分类数据，再估算倍数。","origin":"逐题标记"}]},"国考 2025 地市级 行测#119":{"stem":"如保持2023年同比增量不变，则到哪一年Z省律师办理法律业务数将首次超过150万件？","options":["2026年","2027年","2028年","2029年"],"answer":"C","analysis":"119. 正确答案：C\n解析：\n根据题干“如保持2023年同比增量不变，则到哪一年······将首次超过150万件”，结合材料时间为2023年，可判定本题\n为现期追赶问题。定位统计表可得：2022年、2023年Z省律师办理法律业务数分别为81.24万件、93.55万件。根据\n公式：增长量=现期量-基期量，则2023年Z省律师办理法律业务数的同比增长量=93.55-81.24=12.31万件。根据公\n式：现期量=基期量＋n×增长量，可列式：93.55＋n×12.31>150，解得n>4.6，则n至少为5，即2023+5=2028年Z省\n律师办理法律业务数将首次超过150万件。\n故正确答案为C。\n【考点】\n统计表,现期追赶","figs":["31f401e91aef8d11365d.pdf#23"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-5554da1d1a8d0b60","label":"同比增长量等于本期量减去上年同期量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"增长量=现期量-基期量","why":"用2023年与2022年业务数的差确定每年的固定增量。","origin":"逐题标记"},{"id":"k-f3209d8bfe96ded2","label":"固定增量下的推算值等于起始量加上期数乘以每期增量","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"现期量=基期量＋n×增长量","why":"把每年增加的同一个数量累计到2023年的业务量上。","origin":"逐题标记"},{"id":"s-9fc2e5daf6bbb9d8","label":"按增量或增速推算达标时间","catalog_id":"D08","type":null,"role":"直接考查","field":"question","quote":"如保持2023年同比增量不变，则到哪一年Z省律师办理法律业务数将首次超过150万件？","why":"按固定年增量列严格不等式，取满足条件的最小整数年数并换算为年份。","origin":"逐题标记"}]},"国考 2025 地市级 行测#120":{"stem":"以下柱状图反映了2021、2022和2023年Z省律师、基层法律服务工作哪一指标的同比增量变化趋势（横轴位置\n表示增量为0）？","options":["律师事务所总数","律师人数","村（社区）法律顾问数","法律顾问数（不含村、社区）"],"answer":"D","analysis":"120. 正确答案：D\n解析：\n根据题干“以下柱状图反映了2021、2022和2023年······同比增量变化趋势（横轴位置表示增量为0）”，可判定本题为\n增长量比较问题。定位统计表可得2020-2023年Z省律师事务所总数、律师人数、村（社区）法律顾问数、法律顾问\n数（不含村、社区）。根据公式：增长量=现期量-基期量，可得2021-2023年各指标同比增长量：\nA项，律师事务所总数：2022年，1755-1705=50家；2023年，1826-1755=71家。2022年同比增长量＜2023年同比\n增长量，不符合柱状图变化趋势，排除；\nB项，律师人数：2021年，30889-27302=     人；2022年，36938-30889=      人。2021年同比增长量＜2022\n年同比增长量，不符合柱状图变化趋势，排除；\nC项，村（社区）法律顾问数：2021年（24951家）＜2020年（26153家），同比增长量＜0，而柱状图（横轴位置\n表示增量为0）中2021年同比增长量＞0，不符合，排除；\nD项，法律顾问数（不含村、社区）：2021年，89450-72739=             家；2022年，102251-89450=   家；\n2023年，111811-102251=   家。2021年同比增长量＞2022年同比增长量＞2023年同比增长量，符合柱状图变\n化趋势，当选。\n故正确答案为D。\n【考点】\n统计表,增长量比较","figs":["31f401e91aef8d11365d.pdf#24","31f401e91aef8d11365d.pdf#25","31f401e91aef8d11365d.pdf#23"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-5554da1d1a8d0b60","label":"同比增长量等于本期量减去上年同期量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"增长量=现期量-基期量","why":"柱图所示各年增量对应本年与上年的指标差值。","origin":"逐题标记"},{"id":"s-f29bc501c32a5bee","label":"计算与比较增长量","catalog_id":"D02","type":null,"role":"直接考查","field":"question","quote":"同比增量变化趋势","why":"用相邻年份数据求同比增量，再将其正负和大小顺序与柱图对照。","origin":"逐题标记"}]},"国考 2025 地市级 行测#121":{"stem":"2023年12月，资料中电影总放映场次最多的三个城市票房之和在以下哪个范围内？","options":["超过5亿元","4.5亿~4.75亿元之间","4.75亿~5亿元之间","不到4.5亿元"],"answer":"C","analysis":"121. 正确答案：C\n解析：\n定位图1可知2023年12月电影总放映场次最多的三个城市分别为上海、北京、成都，其票房分别为18682万元、\n19324万元、11085万元，则所求为18682+19324+11085=49091万元       亿元，在C项范围内。\n\n故正确答案为C。\n【考点】\n统计图,简单加减计算","figs":["31f401e91aef8d11365d.pdf#25"],"state":"已标记","notes":[],"domains":["统计","数学"],"nature":"综合题","current":false,"links":[{"id":"k-cf376dc793750737","label":"金额单位换算：1亿元等于10000万元","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"question","quote":"4.75亿~5亿元之间","why":"图中票房以万元计，判断亿元区间前须统一单位。","origin":"逐题标记"},{"id":"s-ddad42966dfee84f","label":"按一项指标筛选前几名并汇总另一项指标","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"电影总放映场次最多的三个城市票房之和","why":"先用放映场次确定城市，再读取同一批城市的票房并求和。","origin":"逐题标记","originalId":"s-f40681d34d4a1da0"}]},"国考 2025 地市级 行测#122":{"stem":"以下城市中2023年12月平均每场电影观众人次数最多的是：","options":["武汉","杭州","重庆","南京"],"answer":"A","analysis":"122. 正确答案：A\n解析：\n根据题干“以下城市中2023年12月平均······最多的是”，结合材料时间为2023年12月，可判定本题为现期平均数问\n题。定位图1、图2可得2023年12月各城市电影总放映场次以及总观众人次。根据平均每场电影观众人次数\n\n          ，则以下城市2023年12月平均每场电影观众人次数分别为：\n\n武汉：                  人次；\n\n杭州：                  人次；\n\n重庆：                  人次；\n\n南京：                  人次。\n\n综上，2023年12月平均每场电影观众人次数最多的是武汉。\n故正确答案为A。\n【考点】\n统计图,现期平均数","figs":["31f401e91aef8d11365d.pdf#25"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-bc653d5f836f1adb","label":"单位平均量等于总量除以对应单位数","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"各城市电影总放映场次以及总观众人次","why":"场均观众人次以总观众人次为分子，以总放映场次为分母。","origin":"逐题标记"},{"id":"s-e9ffdd08e7f0ec51","label":"计算平均数、倍数及其变化","catalog_id":"D07","type":null,"role":"直接考查","field":"question","quote":"平均每场电影观众人次数最多的是","why":"按城市配对两图数据，比较各备选城市的场均观众人次。","origin":"逐题标记"}]},"国考 2025 地市级 行测#123":{"stem":"2023年12月资料中有几个城市平均每人次观众创造的票房超过40元？","options":["3","4","5","6"],"answer":"B","analysis":"123. 正确答案：B\n解析：\n根据题干“2023年12月······平均每人次······”，结合材料时间为2023年12月，可判定本题为现期平均数问题。定位图1\n可知2023年12月各个城市电影票房，定位图2可知2023年12月各个城市电影总观众人次。根据公式：平均每人次观\n\n众创造的票房         ，则：\n\n北京：                   元/人次，符合；\n\n上海：                   元/人次，符合；\n\n深圳：                   元/人次，符合；\n\n广州：            元/人次，符合；\n\n成都：                   元/人次，不符合；\n\n武汉：                   元/人次，不符合；\n\n杭州：                   元/人次，不符合；\n\n重庆：                   元/人次，不符合；\n\n西安：                   元/人次，不符合；\n\n南京：                   元/人次，不符合。\n\n综上，2023年12月资料中北京、上海、深圳、广州平均每人次观众创造的票房超过40元，即有4个城市。\n故正确答案为B。\n【考点】\n统计图,现期平均数","figs":["31f401e91aef8d11365d.pdf#25"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-bc653d5f836f1adb","label":"单位平均量等于总量除以对应单位数","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"平均每人次观众创造的票房","why":"每人次平均票房等于总票房除以总观众人次。","origin":"逐题标记"},{"id":"s-e9ffdd08e7f0ec51","label":"计算平均数、倍数及其变化","catalog_id":"D07","type":null,"role":"直接考查","field":"question","quote":"有几个城市平均每人次观众创造的票房超过40元？","why":"逐城计算单位平均量，并按严格大于指定阈值的条件计数。","origin":"逐题标记"}]},"国考 2025 地市级 行测#124":{"stem":"如某月北京的电影总放映场次和平均每场座位数与2023年12月相同，但上座率增加5个百分点，则该月北京将\n有约多少万人次观众观影？","options":["602","431","794","696"],"answer":"A","analysis":"124. 正确答案：A\n解析：\n根据题干“······与2023年12月相同，但上座率增加5个百分点······”，结合材料时间为2023年12月，可判定本题为现期\n比重问题。\n\n方法一：根据上座率                   ，可知总观众人次=总放映场次×平均每场座位数×上座率，则2023年12\n\n月北京总观众人次=12月总放映场次×12月平均每场座位数×12月上座率。定位图2可得：2023年12月北京总观众人\n\n次为410.74万人次，上座率为10.75%。则2023年12月总放映场次×12月平均每场座位数\n\n           ，结合题干“某月北京的电影总放映场次和平均每场座位数与2023年12月相同，但上座率增加5个百\n\n分点”，则该月北京总观众人次=12月总放映场次×12月平均每场座位数×该月上座率\n                                     万人次，与A项最接近。\n\n方法二：定位图2可得：2023年12月北京总观众人次为410.74万人次，上座率为10.75%。结合题干“某月北京的电影\n总放映场次和平均每场座位数与2023年12月相同，但上座率增加5个百分点”，则北京该月上座率\n\n=10.75%+5%=15.75%。根据上座率                ，则座位数             ，可得：\n\n              ，整理可得：该月总观众人次                                 万人次，与A项最接近。\n\n故正确答案为A。\n【考点】\n统计图,现期比重","figs":["31f401e91aef8d11365d.pdf#25"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-b3ba9534e0541226","label":"上座率等于观众人次除以同期放映座位总数","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"总观众人次=总放映场次×平均每场座位数×上座率","why":"总放映场次与场均座位数的乘积是上座率的分母。","origin":"逐题标记"},{"id":"k-c5c1d4d13089938f","label":"百分点表示两个百分率的算术差","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"上座率增加5个百分点","why":"新上座率由原上座率直接加上5个百分点得到。","origin":"逐题标记"},{"id":"s-a7ce466b25f8ea1b","label":"总量固定时按比重变化推算部分量","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"电影总放映场次和平均每场座位数与2023年12月相同，但上座率增加5个百分点","why":"识别座位总数固定，再按新旧上座率的比值换算观众人次。","origin":"逐题标记","originalId":"s-4c65e2726b717348"}]},"国考 2025 地市级 行测#125":{"stem":"关于资料中城市2023年12月电影票房状况，能够从上述资料中推出的是：","options":["总观众人次数最多的三个城市，当月总观众之和不到1100万人次","广州平均每场电影的座位数少于深圳","上座率最高的城市，当月票房是上座率最低城市的2倍以上","上海、杭州、南京总放映场次是成都、重庆总放映场次的1.5倍以上"],"answer":"C","analysis":"125. 正确答案：C\n解析：\nA项：定位图2可得2023年12月全国电影票房前10城市总观众人次。最多的三个城市分别为北京（410.74万人次）、\n上海（398.05万人次）、成都（308.76万人次），410.74+398.05+308.76>410+398+308=1116万人次>1100万人\n次，错误；\nB项：定位图1可得：2023年12月广州、深圳总放映场次分别为21.67万场、21.53万场；定位图2可得：2023年12月\n广州观众人次数和上座率分别为294.00万人次、8.07%；深圳观众人次数和上座率分别为287.82万人次、8.72%。根\n据公式：上座率                   ，可得座位数             ，故2023年12月广州平均每场电影的座位数\n\n                                        ，深圳平均每场电影的座位数\n\n                  ，根据分数比较原则：分子大、分母小，分数值大，则2023年12月广州平均每场电影的\n\n座位数多于深圳，错误；\nC项：定位图1可得2023年12月全国电影票房前10城市票房；定位图2可得2023年12月全国电影票房前10城市上座\n率。资料中城市2023年12月上座率最高的城市是北京（10.75%），其票房为19324万元；上座率最低的城市是重庆\n（6.35%），其票房为8451万元。            倍，正确；\n\nD项：定位图1可得：2023年12月上海、杭州、南京、成都、重庆总放映场次分别为28.40万场、15.76万场、12.46\n万场、24.55万场、21.41万场。                          倍     倍，错误。\n\n故正确答案为C。\n【考点】\n统计图,综合分析","figs":["31f401e91aef8d11365d.pdf#25"],"state":"已标记","notes":[],"domains":["统计","数学"],"nature":"综合题","current":false,"links":[{"id":"k-a32ec9796384d5b1","label":"两量的倍数等于被比较量除以基准量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"当月票房是上座率最低城市的2倍以上","why":"以低上座率城市的票房为基准，判断两城市票房是否达到题设倍数。","origin":"逐题标记"},{"id":"s-ddad42966dfee84f","label":"按一项指标定位极值对象并比较另一项指标的倍数","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"上座率最高的城市，当月票房是上座率最低城市的2倍以上","why":"先用图2的上座率定位两个极值城市，再用图1的票房核验倍数关系。","origin":"逐题标记","originalId":"s-e41b4621e11b2346"}]},"国考 2025 地市级 行测#126":{"stem":"以下饼状图中，最能准确反映2023年一季度我国外贸进出口总额中，东部地区（白色）、中西部地区（斜线）\n和东北地区（黑色）外贸进出口额占比关系的是：","options":["","","",""],"answer":"A","analysis":"126. 正确答案：A\n解析：\n根据题干“以下饼状图中，最能准确反映2023年一季度······占比关系的是”，结合材料时间为2023年一季度，可判定\n本题为现期比重问题。定位文字材料第一段可得：2023年一季度，我国外贸进出口总额为9.89万亿元。其中，东部\n\n地区进出口7.75万亿元；中西部、东北地区分别进出口1.84万亿元、2975.4亿元。根据公式：比重                    ，则东部\n\n地区外贸进出口额占我国外贸进出口总额的比重为                       ，排除C、D两项；中西部地区与东北地区外贸\n\n进出口额的倍数关系为                    ，排除B项。\n\n故正确答案为A。\n【考点】\n文字资料,现期比重","figs":["31f401e91aef8d11365d.pdf#26","31f401e91aef8d11365d.pdf#27"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-share","label":"比重等于部分量除以总体量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"地区外贸进出口额占我国外贸进出口总额的比重","why":"以全国进出口总额为分母，可求地区进出口额占全国的份额。","origin":"逐题标记"},{"id":"k-36bf227073606f60","label":"饼图扇形的圆心角与其所表示的比重成正比","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"以下饼状图中，最能准确反映","why":"可以用扇形大小核对各地区的份额及其相对大小。","origin":"逐题标记"},{"id":"s-a7ce466b25f8ea1b","label":"计算现期比重","catalog_id":"7a985b326fc58141","type":null,"role":"直接考查","field":"answer","quote":"本题为现期比重问题","why":"将同期地区进出口额和全国进出口额统一单位后求比重。","origin":"逐题标记"},{"id":"s-6cfd92b2f027f1a1","label":"按份额及部分之间的倍数关系匹配饼图","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"进出口额的倍数关系为","why":"先用东部地区的份额筛选，再比较斜线和黑色扇形的相对大小。","origin":"逐题标记","originalId":"s-9eb831a734061161"}]},"国考 2025 地市级 行测#127":{"stem":"2023年一季度，东部地区外贸进口额约为多少万亿元？","options":["2.2","2.8","3.4","4.0"],"answer":"C","analysis":"127. 正确答案：C\n解析：\n根据题干“2023年一季度，东部地区外贸进口额约为多少万亿元”，结合材料给出2023年一季度东部地区外贸进出口\n总额、东部地区高技术产品出口额及其占东部地区出口额的比重，可判定本题为现期比重问题。定位文字材料第一\n段可得：2023年一季度，东部地区进出口7.75万亿元。定位文字材料第二段可得：（2023年）一季度，东部地区出\n\n口高技术产品7741.7亿元，占东部地区出口额比重为17.9%。根据公式：整体        ，则2023年一季度东部地区外\n\n贸出口额为                     万亿元。故2023年一季度东部地区外贸进口额为7.75-4.3=3.45万亿\n\n元，与C项最接近。\n故正确答案为C。\n【考点】\n文字资料,现期比重","figs":["31f401e91aef8d11365d.pdf#26"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-cc207829acf54194","label":"总体量等于部分量除以部分所占比重","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"M1","quote":"地区出口额比重为17.9%","why":"高技术产品出口额是部分量，其占比对应的总体是东部地区出口总额。","origin":"逐题标记"},{"id":"k-5d5ddc6eab42ab83","label":"进出口总额等于进口额与出口额之和","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"东部地区外贸进口额为7.75-4.3","why":"可从同一地区同期进出口总额中减去出口额，得到进口额。","origin":"逐题标记"},{"id":"s-a7ce466b25f8ea1b","label":"由部分量和比重反推总体量","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"根据公式：整体","why":"先由高技术产品出口额及其占比反推出口总额，为求进口额提供所需数据。","origin":"逐题标记","originalId":"s-3e51eb0e4a3152b7"}]},"国考 2025 地市级 行测#128":{"stem":"2023年一季度，中西部地区对“一带一路”沿线国家进出口贸易额同比增量约占同期中西部地区外贸进出口总额\n同比增量的：","options":["33%","55%","77%","99%"],"answer":"D","analysis":"128. 正确答案：D\n解析：\n根据题干“2023年一季度······占······”，结合材料时间为2023年一季度，可判定本题为现期比重问题。定位文字材料\n第一段可得：2023年一季度，中西部地区进出口1.84万亿元，同比增长12.6%。定位文字材料第三段可得：（2023\n年）一季度，中西部地区对“一带一路”沿线国家进出口7400.9亿元，同比增长38%。根据公式：增长量\n\n        、比重     ，可得所求\n\n                                                  ，与D项最接近。\n\n故正确答案为D。\n【考点】\n文字资料,现期比重","figs":["31f401e91aef8d11365d.pdf#26"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-3a19945eaea55744","label":"由现期量和增长率推算增长量的公式","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"根据公式：增长量","why":"同比增量等于现期量乘以同比增长率，再除以一加同比增长率。","origin":"逐题标记"},{"id":"k-share","label":"比重等于部分量除以总体量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"进出口贸易额同比增量约占同期中西部地区外贸进出口总额","why":"本题的分子与分母均采用同比增量口径。","origin":"逐题标记"},{"id":"s-f29bc501c32a5bee","label":"计算与比较增长量","catalog_id":"D02","type":null,"role":"直接考查","field":"answer","quote":"根据公式：增长量","why":"用两组现期量和同比增速分别估算对应的同比增量。","origin":"逐题标记"},{"id":"s-a7ce466b25f8ea1b","label":"计算现期比重","catalog_id":"7a985b326fc58141","type":null,"role":"直接考查","field":"answer","quote":"本题为现期比重问题","why":"统一单位后，用沿线国家贸易额增量除以地区进出口总额增量。","origin":"逐题标记"}]},"国考 2025 地市级 行测#129":{"stem":"2023年一季度，东部地区外贸进出口额占我国外贸进出口总额比重比上年同期：","options":["上升了5个百分点以上","上升了不到5个百分点","下降了5个百分点以上","下降了不到5个百分点"],"answer":"D","analysis":"129. 正确答案：D\n解析：\n根据题干“2023年一季度······占······比重比上年同期”，结合选项为“上升了/下降了+百分点”，可判定本题为两期比重\n问题。定位文字材料第一段可得：2023年一季度，我国外贸进出口总额为9.89万亿元（B），同比增加0.45万亿元。\n其中，东部地区进出口7.75万亿元（A），同比增长2.9%（a）。根据公式：增长率                ，可得2023\n\n年一季度我国外贸进出口总额同比增长率                     （b）；根据公式：两期比重差\n\n，则所求                            ，即下降了不到1.9个百分点，在D项范围内。\n\n故正确答案为D。\n【考点】\n文字资料,两期比重","figs":["31f401e91aef8d11365d.pdf#26"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-101058b53ba140f7","label":"增长率等于增长量除以基期量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"根据公式：增长率","why":"可先从全国进出口现期总额中减去同比增量得到基期总额，再求全国同比增速。","origin":"逐题标记"},{"id":"k-58db2e624f2d2295","label":"现期比重减去基期比重等于现期比重乘以部分与总体增速之差再除以一加部分增速","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"根据公式：两期比重差","why":"该关系可以将现期份额及两个同比增速换算成份额的百分点变化。","origin":"逐题标记","originalId":"k-938730e99fe91d67"},{"id":"s-22e0d443f4e8833e","label":"比较比重与百分点差","catalog_id":"D06","type":null,"role":"直接考查","field":"question","quote":"比重比上年同期","why":"先比较部分与总体的同比增速以判断方向，再估算比重差并匹配百分点区间。","origin":"逐题标记"}]},"国考 2025 地市级 行测#130":{"stem":"关于我国外贸进出口状况，能够从上述资料中推出的是：","options":["2023年3月东部地区高技术产品出口额","2022年一季度中西部地区一般贸易进出口额","2023年一季度全国高技术产品出口额","2022年东北地区汽车制造业出口额同比增量"],"answer":"B","analysis":"130. 正确答案：B\n解析：\nA项：定位文字材料第二段可得：（2023年）一季度，东部地区出口高技术产品7741.7亿元，3月增速为21%。但是\n材料缺少2023年1-2月份东部地区高技术产品出口额的相关数据，故2023年3月东部地区高技术产品出口额无法推\n出；\nB项：定位文字材料第一段可得：2023年一季度，中西部地区进出口1.84万亿元，同比增长12.6%；定位文字材料第\n三段可得：（2023年）一季度，中西部地区一般贸易进出口占中西部地区进出口总额的56.6%，同比提升4.9个百分\n点。根据公式：基期量        ，可得2022年一季度中西部地区进出口总额            ，2022年一季度，中西\n\n部地区一般贸易进出口占中西部地区进出口总额的比重为（56.6%-4.9%），则2022年一季度中西部地区一般贸易进\n\n出口额                   ，可以推出；\n\nC项：材料没有涉及全国高技术产品出口额的相关数据，故无法推出；\nD项：定位文字材料第四段可得：（2023年）一季度，东北地区汽车制造业出口同比增长62.3%，但是材料缺少\n2022年东北地区汽车制造业出口额的相关数据，故2022年东北地区汽车制造业出口额同比增量无法推出。\n故正确答案为B。\n\n【考点】\n文字资料,综合分析","figs":["31f401e91aef8d11365d.pdf#26"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-c1e02ee36e8303c5","label":"基期量等于现期量除以一加增长率","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"根据公式：基期量","why":"由地区进出口现期总额及同比增速可以求出上年同期总额。","origin":"逐题标记"},{"id":"k-008c16b7ba42d3b9","label":"基期比重等于现期比重减去以百分点表示的比重变动量","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"比重为（56.6%-4.9%）","why":"从现期比重中扣除同比提升的百分点，可以得到上年同期的一般贸易比重。","origin":"逐题标记"},{"id":"k-63601bb9dc8f610e","label":"部分量等于同期总体量乘以部分所占比重","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"地区一般贸易进出口占中西部地区进出口总额的56.6%","why":"用基期进出口总额乘以同一期一般贸易比重，可以推出一般贸易进出口额。","origin":"逐题标记"},{"id":"s-d495edd4c80a44de","label":"核对统计指标的计算条件与材料数据是否齐备","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"能够从上述资料中推出的是","why":"逐项核对时间、地区、指标口径与所需数据，判断材料能否支持计算。","origin":"逐题标记","originalId":"s-20ff7622876b9807"},{"id":"s-base","label":"反推基期量","catalog_id":"D01","type":null,"role":"解题依据","field":"answer","quote":"根据公式：基期量","why":"先由现期总额和同比增速反推基期总额，再结合基期比重求相应分项。","origin":"逐题标记"}]}},"mats":{"bf1a7a73204b8e6a":["题组1","（一）\n\n某科研机构今年拟举办甲、乙、丙、丁、戊、己、庚、辛8次学术会议，每个季度最多举办3次，且各次会议举办时\n间不重叠。具体安排要求如下：\n（1）丁、辛安排在第二季度；\n（2）甲、戊安排在同一个季度；\n（3）丁在乙之后丙之前举办；\n（4）丙在甲之前己之后举办。",["31f401e91aef8d11365d.pdf",20]],"c4a2e3f87ccca5cd":["题组2","（一）",["31f401e91aef8d11365d.pdf",21]],"820e0c714f0a2d81":["题组3","（二）",["31f401e91aef8d11365d.pdf",23]],"6042f1ec3fcb0466":["题组4","（三）\n\n\n\n\n注：上座率",["31f401e91aef8d11365d.pdf",25]],"d34c6286ae16dac4":["题组5","（四）\n\n      2023年一季度，我国外贸进出口总额为9.89万亿元，同比增加0.45万亿元。其中，东部地区进出口7.75万亿\n元，同比增长2.9%；中西部、东北地区分别进出口1.84万亿元、2975.4亿元，同比分别增长12.6%、9.4%。\n      2月份，东部地区进出口同比增速由1月份的下降11.1%转为增长7%，3月份增速扩大至15.8%。一季度有进出\n口实绩企业数量38.7万家，同比增长5.2%。一季度，东部地区出口高技术产品7741.7亿元，同比增长9.8%，占东部\n地区出口额比重为17.9%，同比提升0.7个百分点，其中3月增速为21%。\n      一季度，中西部地区民营企业进出口1.08万亿元，同比增长32.8%，中西部地区对“一带一路”沿线国家进出口\n7400.9亿元，同比增长38%。一般贸易占中西部地区进出口总额的56.6%，同比提升4.9个百分点。\n      一季度，东北地区黑色金属冶炼和压延加工业、汽车制造业、铁路船舶等其他运输设备制造业出口同比分别增\n长42.9%、62.3%、136.4%。化肥、种子分别进口25亿元、5867.6万元，同比分别增长117.8%、119.9%。",["31f401e91aef8d11365d.pdf",26]]}};
